    /// <summary>
    /// XAML markup extension for a list item whose text the XAML loader would lose: an empty
    /// string, or one that is only spaces (XAML drops white-space-only element text, and an empty
    /// &lt;sys:String/&gt; fails because System.String has no parameterless constructor).
    /// Usage: &lt;rtl:Str Value=" "/&gt; - attribute values keep their spaces.
    /// </summary>
    [System.Windows.Markup.MarkupExtensionReturnType(typeof(string))]
    public sealed class StrExtension : System.Windows.Markup.MarkupExtension
    {
        public StrExtension() { }
        public StrExtension(string value) { Value = value; }
        /// <summary>The exact text of the item.</summary>
        public string Value { get; set; } = "";
        public override object ProvideValue(IServiceProvider serviceProvider) => Value ?? "";
    }

