        /// <summary>Delphi global DecimalSeparator (reads/writes the current culture).</summary>
        public static char DecimalSeparator
        {
            get => CultureInfo.CurrentCulture.NumberFormat.NumberDecimalSeparator[0];
            set
            {
                var c = (CultureInfo)CultureInfo.CurrentCulture.Clone();
                c.NumberFormat.NumberDecimalSeparator = value.ToString();
                CultureInfo.CurrentCulture = c;
            }
        }

