        public static string IntToStr(long value) => value.ToString(CultureInfo.InvariantCulture);
        public static string IntToStr(int value) => value.ToString(CultureInfo.InvariantCulture);

        public static int StrToInt(string s)
        {
            if (TryStrToInt(s, out int v)) return v;
            throw new FormatException($"'{s}' is not a valid integer value");
        }

        public static long StrToInt64(string s)
        {
            s = (s ?? "").Trim();
            if (s.StartsWith("$")) return long.Parse(s.Substring(1), NumberStyles.HexNumber, CultureInfo.InvariantCulture);
            return long.Parse(s, NumberStyles.Integer, CultureInfo.InvariantCulture);
        }

        public static int StrToIntDef(string s, int def) => TryStrToInt(s, out int v) ? v : def;

        public static bool TryStrToInt(string s, out int value)
        {
            s = (s ?? "").Trim();
            if (s.StartsWith("$") || s.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            {
                string hex = s.StartsWith("$") ? s.Substring(1) : s.Substring(2);
                if (int.TryParse(hex, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out value)) return true;
                value = 0;
                return false;
            }
            return int.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture, out value);
        }

