        {
            if (TryStrToFloat(s, out double v)) return v;
            throw new FormatException($"'{s}' is not a valid floating point value");
        }

        public static double StrToFloatDef(string s, double def) => TryStrToFloat(s, out double v) ? v : def;

        public static bool TryStrToFloat(string s, out double value) =>
            double.TryParse((s ?? "").Trim(), NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out value);

