        /// <summary>FloatToStr uses 15 significant digits like Delphi.</summary>
        public static string FloatToStr(double value) => value.ToString("G15", CultureInfo.CurrentCulture);

        public static string FloatToStrF(double value, TFloatFormat format, int precision, int digits)
        {
            switch (format)
            {
                case TFloatFormat.ffFixed: return value.ToString("F" + digits, CultureInfo.CurrentCulture);
                case TFloatFormat.ffNumber: return value.ToString("N" + digits, CultureInfo.CurrentCulture);
                case TFloatFormat.ffCurrency: return value.ToString("C" + digits, CultureInfo.CurrentCulture);
                case TFloatFormat.ffExponent: return value.ToString("E" + Math.Max(0, precision - 1), CultureInfo.CurrentCulture);
                default: return value.ToString("G" + precision, CultureInfo.CurrentCulture);
            }
        }

