        /// <summary>Copy(S, Index, Count) with Delphi's 1-based, range-tolerant semantics.</summary>
        public static string Copy(string s, int index, int count)
        {
            s ??= "";
            if (index < 1) index = 1;
            if (index > s.Length || count <= 0) return "";
            if (count > s.Length - index + 1) count = s.Length - index + 1;
            return s.Substring(index - 1, count);
        }

        /// <summary>Copy(S, Index) (Delphi 2007+ overload) - rest of the string.</summary>
        public static string Copy(string s, int index) => Copy(s, index, int.MaxValue);

        /// <summary>Copy for dynamic arrays (0-based like Delphi arrays).</summary>
        public static T[] Copy<T>(T[] a, int index, int count)
        {
            if (a == null) return new T[0];
            if (index < 0) index = 0;
            if (index >= a.Length || count <= 0) return new T[0];
            count = Math.Min(count, a.Length - index);
            var r = new T[count];
            Array.Copy(a, index, r, 0, count);
            return r;
        }

        public static T[] Copy<T>(T[] a) => a == null ? new T[0] : (T[])a.Clone();

        /// <summary>Pos(SubStr, S): 1-based index, 0 when not found.</summary>
        public static int Pos(string sub, string s) => string.IsNullOrEmpty(sub) || s == null ? 0 : s.IndexOf(sub, StringComparison.Ordinal) + 1;
        public static int Pos(char sub, string s) => s == null ? 0 : s.IndexOf(sub) + 1;
        public static int AnsiPos(string sub, string s) => Pos(sub, s);
        public static int PosEx(string sub, string s, int offset = 1)
        {
            if (string.IsNullOrEmpty(sub) || s == null || offset < 1 || offset > s.Length) return 0;
            return s.IndexOf(sub, offset - 1, StringComparison.Ordinal) + 1;
        }

        public static int Length(string s) => s?.Length ?? 0;
        public static int Length(Array a) => a?.Length ?? 0;
        public static int Length(ICollection c) => c?.Count ?? 0;

        /// <summary>Delete(S, Index, Count) - modifies S in place (1-based).</summary>
        public static void Delete(ref string s, int index, int count)
        {
            s ??= "";
            if (index < 1 || index > s.Length || count <= 0) return;
            if (count > s.Length - index + 1) count = s.Length - index + 1;
            s = s.Remove(index - 1, count);
        }

        /// <summary>Insert(Source, S, Index) - modifies S in place (1-based).</summary>
        public static void Insert(string source, ref string s, int index)
        {
            s ??= "";
            if (index < 1) index = 1;
            if (index > s.Length + 1) index = s.Length + 1;
            s = s.Insert(index - 1, source ?? "");
        }

        /// <summary>SetLength for strings: returns the resized string (pads with #0, like Delphi).</summary>
        public static string SetLength(string s, int newLength)
        {
            s ??= "";
            if (newLength <= 0) return "";
            return s.Length >= newLength ? s.Substring(0, newLength) : s.PadRight(newLength, '\0');
        }

        public static string StringReplace(string s, string oldPattern, string newPattern, HashSet<TReplaceFlag> flags)
        {
            s ??= "";
            if (string.IsNullOrEmpty(oldPattern)) return s;
            bool all = flags != null && flags.Contains(TReplaceFlag.rfReplaceAll);
            var cmp = flags != null && flags.Contains(TReplaceFlag.rfIgnoreCase) ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
            if (all) return s.Replace(oldPattern, newPattern ?? "", cmp);
            int i = s.IndexOf(oldPattern, cmp);
            return i < 0 ? s : s.Substring(0, i) + newPattern + s.Substring(i + oldPattern.Length);
        }

        public static string QuotedStr(string s) => "'" + (s ?? "").Replace("'", "''") + "'";
        public static string AnsiQuotedStr(string s, char quote) => quote + (s ?? "").Replace(quote.ToString(), new string(quote, 2)) + quote;
        public static string AnsiDequotedStr(string s, char quote)
        {
            if (string.IsNullOrEmpty(s) || s[0] != quote) return s ?? "";
            string inner = s.Length >= 2 && s[s.Length - 1] == quote ? s.Substring(1, s.Length - 2) : s.Substring(1);
            return inner.Replace(new string(quote, 2), quote.ToString());
        }

