        public static int AnsiCompareText(string a, string b) => string.Compare(a ?? "", b ?? "", StringComparison.CurrentCultureIgnoreCase);
        public static int AnsiCompareStr(string a, string b) => string.Compare(a ?? "", b ?? "", StringComparison.CurrentCulture);
        public static bool AnsiSameText(string a, string b) => AnsiCompareText(a, b) == 0;
        public static bool AnsiSameStr(string a, string b) => AnsiCompareStr(a, b) == 0;
