        public static bool AnsiEndsText(string sub, string s) => (s ?? "").EndsWith(sub ?? "", StringComparison.CurrentCultureIgnoreCase);
        public static bool AnsiContainsText(string s, string sub) => (s ?? "").IndexOf(sub ?? "", StringComparison.CurrentCultureIgnoreCase) >= 0;
        public static bool AnsiStartsStr(string sub, string s) => (s ?? "").StartsWith(sub ?? "", StringComparison.CurrentCulture);
        public static string AnsiReplaceStr(string s, string from, string to) => (s ?? "").Replace(from ?? "", to ?? "");
        public static string AnsiReplaceText(string s, string from, string to) => string.IsNullOrEmpty(from) ? s ?? "" : (s ?? "").Replace(from, to ?? "", StringComparison.OrdinalIgnoreCase);

        public static string StringOfChar(char c, int count) => count <= 0 ? "" : new string(c, count);
        public static string DupeString(string s, int count) => count <= 0 ? "" : string.Concat(Enumerable.Repeat(s ?? "", count));
        public static string LeftStr(string s, int count) => Copy(s, 1, count);
        public static string RightStr(string s, int count) { s ??= ""; return count >= s.Length ? s : count <= 0 ? "" : s.Substring(s.Length - count); }
        public static string MidStr(string s, int start, int count) => Copy(s, start, count);
