        public static int LastDelimiter(string delimiters, string s)
        {
            if (s == null) return 0;
            for (int i = s.Length - 1; i >= 0; i--) if ((delimiters ?? "").IndexOf(s[i]) >= 0) return i + 1;
            return 0;
        }

        public static bool IsDelimiter(string delimiters, string s, int index) =>
            s != null && index >= 1 && index <= s.Length && (delimiters ?? "").IndexOf(s[index - 1]) >= 0;

        public static string AdjustLineBreaks(string s) => Regex.Replace(s ?? "", "\r\n|\r|\n", "\r\n");
        public static string WrapText(string s, int maxCol) => s ?? "";

        public static string BoolToStr(bool b, bool useBoolStrs = false) => useBoolStrs ? (b ? "True" : "False") : (b ? "-1" : "0");

        public static bool StrToBool(string s)
        {
            s = (s ?? "").Trim();
            if (s.Equals("true", StringComparison.OrdinalIgnoreCase)) return true;
            if (s.Equals("false", StringComparison.OrdinalIgnoreCase)) return false;
            if (double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out double d)) return d != 0;
            throw new FormatException($"'{s}' is not a valid boolean value");
        }

        public static bool StrToBoolDef(string s, bool def) { try { return StrToBool(s); } catch { return def; } }

        /// <summary>Str(X, S) equivalent - returns the string.</summary>
        public static string Str(object value) => Convert.ToString(value, CultureInfo.InvariantCulture);

        /// <summary>Val(S, V, Code): Code = 0 on success, else 1-based position of the error.</summary>
        public static void Val(string s, out int value, out int code)
        {
            code = TryStrToInt(s, out value) ? 0 : Math.Max(1, (s ?? "").Length);
        }

        public static void Val(string s, out float value, out int code) { Val(s, out double d, out code); value = (float)d; }
        public static void Val(string s, out double value, out int code)
        {
            code = double.TryParse((s ?? "").Trim(), NumberStyles.Float, CultureInfo.InvariantCulture, out value) ? 0 : Math.Max(1, (s ?? "").Length);
