        // ------------------------------------------------------------------ Format

        /// <summary>
        /// Delphi Format(). Supports %[index:][-][width][.prec]type with types
        /// d u e f g n m p s x (and * width/precision).
        /// </summary>
        public static string Format(string fmt, params object[] args)
        {
            fmt ??= "";
            args ??= new object[0];
            var sb = new StringBuilder();
            int argIndex = 0;
            var ci = CultureInfo.CurrentCulture;
            for (int i = 0; i < fmt.Length; i++)
            {
                char c = fmt[i];
                if (c != '%') { sb.Append(c); continue; }
                i++;
                if (i >= fmt.Length) break;
                if (fmt[i] == '%') { sb.Append('%'); continue; }

                // [index:]
                int start = i;
                int num = ReadFmtNumber(fmt, ref i, args, ref argIndex);
                if (i < fmt.Length && fmt[i] == ':') { argIndex = num < 0 ? 0 : num; i++; }
                else i = start;

                bool left = false;
                if (i < fmt.Length && fmt[i] == '-') { left = true; i++; }
                int width = ReadFmtNumber(fmt, ref i, args, ref argIndex);
                int prec = -1;
                if (i < fmt.Length && fmt[i] == '.') { i++; prec = ReadFmtNumber(fmt, ref i, args, ref argIndex); }
                if (i >= fmt.Length) break;
                char type = char.ToLowerInvariant(fmt[i]);
                object arg = argIndex < args.Length ? args[argIndex] : null;
                argIndex++;
                string text;
                switch (type)
                {
                    case 'd':
                        text = Convert.ToInt64(arg, ci).ToString(ci);
                        if (prec > 0) { bool neg = text.StartsWith("-"); text = text.TrimStart('-').PadLeft(prec, '0'); if (neg) text = "-" + text; }
                        break;
                    case 'u': text = Convert.ToUInt64(arg, ci).ToString(ci); break;
                    case 'x': text = Convert.ToInt64(arg, ci).ToString("X" + (prec > 0 ? prec.ToString(CultureInfo.InvariantCulture) : ""), CultureInfo.InvariantCulture); break;
                    case 'e': text = Convert.ToDouble(arg, ci).ToString("E" + (prec >= 0 ? Math.Max(0, prec - 1) : 14), ci); break;
                    case 'f': text = Convert.ToDouble(arg, ci).ToString("F" + (prec >= 0 ? prec : 2), ci); break;
                    case 'g': text = Convert.ToDouble(arg, ci).ToString("G" + (prec >= 0 ? prec : 15), ci); break;
                    case 'n': text = Convert.ToDouble(arg, ci).ToString("N" + (prec >= 0 ? prec : 2), ci); break;
                    case 'm': text = Convert.ToDouble(arg, ci).ToString("C" + (prec >= 0 ? prec : ci.NumberFormat.CurrencyDecimalDigits), ci); break;
                    case 'p': text = Convert.ToInt64(arg ?? 0, ci).ToString("X8", CultureInfo.InvariantCulture); break;
                    case 's':
                        text = Convert.ToString(arg, ci) ?? "";
                        if (prec >= 0 && text.Length > prec) text = text.Substring(0, prec);
                        break;
                    default: text = Convert.ToString(arg, ci); break;
                }
                if (width > 0) text = left ? text.PadRight(width) : text.PadLeft(width);
                sb.Append(text);
            }
            return sb.ToString();
        }

        private static int ReadFmtNumber(string fmt, ref int i, object[] args, ref int argIndex)
        {
            if (i < fmt.Length && fmt[i] == '*')
            {
                i++;
                return argIndex < args.Length ? Convert.ToInt32(args[argIndex++], CultureInfo.InvariantCulture) : 0;
            }
            int st = i;
            while (i < fmt.Length && char.IsDigit(fmt[i])) i++;
            return i > st ? int.Parse(fmt.Substring(st, i - st), CultureInfo.InvariantCulture) : -1;
        }

