        public static double EncodeDate(int year, int month, int day) => new DateTime(year, month, day).ToOADate();
        public static double EncodeTime(int hour, int min, int sec, int msec) => new TimeSpan(0, hour, min, sec, msec).TotalDays;

        public static void DecodeDate(double dt, out ushort year, out ushort month, out ushort day)
        {
            var d = DateTime.FromOADate(dt);
            year = (ushort)d.Year; month = (ushort)d.Month; day = (ushort)d.Day;
        }

        public static void DecodeTime(double dt, out ushort hour, out ushort min, out ushort sec, out ushort msec)
        {
            var d = DateTime.FromOADate(dt);
            hour = (ushort)d.Hour; min = (ushort)d.Minute; sec = (ushort)d.Second; msec = (ushort)d.Millisecond;
        }

