        public static int DayOfWeek(double dt) => (int)DateTime.FromOADate(dt).DayOfWeek + 1;
        /// <summary>DateUtils.DayOfTheWeek: 1 = Monday ... 7 = Sunday.</summary>
        public static int DayOfTheWeek(double dt) { int d = (int)DateTime.FromOADate(dt).DayOfWeek; return d == 0 ? 7 : d; }
        public static int YearOf(double dt) => DateTime.FromOADate(dt).Year;
        public static int MonthOf(double dt) => DateTime.FromOADate(dt).Month;
        public static int DayOf(double dt) => DateTime.FromOADate(dt).Day;
        public static int HourOf(double dt) => DateTime.FromOADate(dt).Hour;
        public static int MinuteOf(double dt) => DateTime.FromOADate(dt).Minute;
        public static int SecondOf(double dt) => DateTime.FromOADate(dt).Second;
        public static bool IsLeapYear(int year) => DateTime.IsLeapYear(year);
        public static int DaysInMonth(double dt) { var d = DateTime.FromOADate(dt); return DateTime.DaysInMonth(d.Year, d.Month); }
        public static double IncDay(double dt, int days = 1) => dt + days;
        public static double IncMonth(double dt, int months = 1) => DateTime.FromOADate(dt).AddMonths(months).ToOADate();
        public static double IncYear(double dt, int years = 1) => DateTime.FromOADate(dt).AddYears(years).ToOADate();
        public static double IncHour(double dt, long hours = 1) => dt + hours / 24.0;
        public static double IncMinute(double dt, long minutes = 1) => dt + minutes / 1440.0;
        public static double IncSecond(double dt, long seconds = 1) => dt + seconds / 86400.0;
        public static int DaysBetween(double a, double b) => (int)Math.Truncate(Math.Abs(a - b));
        public static long HoursBetween(double a, double b) => (long)Math.Truncate(Math.Abs(a - b) * 24);
        public static long MinutesBetween(double a, double b) => (long)Math.Truncate(Math.Abs(a - b) * 1440);
        public static long SecondsBetween(double a, double b) => (long)Math.Truncate(Math.Abs(a - b) * 86400);
        public static double StartOfTheDay(double dt) => Math.Floor(dt);
        public static double EndOfTheDay(double dt) => Math.Floor(dt) + (86399999 / 86400000.0);
        public static double DateOf(double dt) => Math.Floor(dt);
        public static double TimeOf(double dt) => dt - Math.Floor(dt);

        public static string DateToStr(double dt) => DateTime.FromOADate(dt).ToString("d", CultureInfo.CurrentCulture);
        public static string TimeToStr(double dt) => DateTime.FromOADate(dt).ToString("T", CultureInfo.CurrentCulture);
        public static string DateTimeToStr(double dt)
        {
            var d = DateTime.FromOADate(dt);
            return d.TimeOfDay == TimeSpan.Zero ? d.ToString("d", CultureInfo.CurrentCulture) : d.ToString("G", CultureInfo.CurrentCulture);
        }
        public static double StrToDate(string s) => DateTime.Parse(s, CultureInfo.CurrentCulture).Date.ToOADate();
        public static double StrToTime(string s) => DateTime.Parse(s, CultureInfo.CurrentCulture).TimeOfDay.TotalDays;
        public static double StrToDateTime(string s) => DateTime.Parse(s, CultureInfo.CurrentCulture).ToOADate();
        public static double StrToDateDef(string s, double def) => DateTime.TryParse(s, CultureInfo.CurrentCulture, DateTimeStyles.None, out var d) ? d.Date.ToOADate() : def;
        public static bool TryStrToDate(string s, out double value)
        {
            bool ok = DateTime.TryParse(s, CultureInfo.CurrentCulture, DateTimeStyles.None, out var d);
            value = ok ? d.Date.ToOADate() : 0;
            return ok;
        }

        /// <summary>
        /// FormatDateTime with Delphi format specifiers (d dd ddd dddd ddddd m mm mmm mmmm
        /// yy yyyy h hh n nn s ss z zzz am/pm a/p c t tt / : and 'quoted' text).
        /// Note: in Delphi "m" directly after h/hh means minutes.
        /// </summary>
        public static string FormatDateTime(string fmt, double dt)
        {
            var d = DateTime.FromOADate(dt);
            var ci = CultureInfo.CurrentCulture;
            var sb = new StringBuilder();
            fmt ??= "";
            bool lastWasHour = false;
            bool ampm = Regex.IsMatch(fmt, "am/pm|a/p", RegexOptions.IgnoreCase);
            int i = 0;
            while (i < fmt.Length)
            {
                char c = fmt[i];
                char lc = char.ToLowerInvariant(c);
                int run = 1;
                while (i + run < fmt.Length && char.ToLowerInvariant(fmt[i + run]) == lc) run++;

                if (c == '\'' || c == '"')
                {
                    int end = fmt.IndexOf(c, i + 1);
                    if (end < 0) end = fmt.Length;
                    sb.Append(fmt, i + 1, end - i - 1);
                    i = end + 1;
                    continue;
                }
                if (fmt.Substring(i).StartsWith("am/pm", StringComparison.OrdinalIgnoreCase)) { sb.Append(d.Hour < 12 ? "am" : "pm"); i += 5; continue; }
                if (fmt.Substring(i).StartsWith("a/p", StringComparison.OrdinalIgnoreCase)) { sb.Append(d.Hour < 12 ? "a" : "p"); i += 3; continue; }
                switch (lc)
                {
                    case 'd':
                        if (run == 1) sb.Append(d.Day);
                        else if (run == 2) sb.Append(d.Day.ToString("00", ci));
                        else if (run == 3) sb.Append(d.ToString("ddd", ci));
                        else if (run == 4) sb.Append(d.ToString("dddd", ci));
                        else if (run == 5) sb.Append(d.ToString("d", ci));
                        else sb.Append(d.ToString("D", ci));
                        lastWasHour = false;
                        break;
                    case 'm':
                        if (lastWasHour && run <= 2) sb.Append(run == 1 ? d.Minute.ToString(ci) : d.Minute.ToString("00", ci));
                        else if (run == 1) sb.Append(d.Month);
                        else if (run == 2) sb.Append(d.Month.ToString("00", ci));
                        else if (run == 3) sb.Append(d.ToString("MMM", ci));
                        else sb.Append(d.ToString("MMMM", ci));
                        lastWasHour = false;
                        break;
                    case 'y':
                        sb.Append(run <= 2 ? (d.Year % 100).ToString("00", ci) : d.Year.ToString("0000", ci));
                        lastWasHour = false;
                        break;
                    case 'h':
                        {
                            int h = ampm ? (d.Hour % 12 == 0 ? 12 : d.Hour % 12) : d.Hour;
                            sb.Append(run == 1 ? h.ToString(ci) : h.ToString("00", ci));
                            lastWasHour = true;
                        }
                        break;
                    case 'n':
                        sb.Append(run == 1 ? d.Minute.ToString(ci) : d.Minute.ToString("00", ci));
                        lastWasHour = false;
                        break;
                    case 's':
                        sb.Append(run == 1 ? d.Second.ToString(ci) : d.Second.ToString("00", ci));
                        lastWasHour = false;
                        break;
                    case 'z':
                        sb.Append(run < 3 ? d.Millisecond.ToString(ci) : d.Millisecond.ToString("000", ci));
                        run = Math.Min(run, 3);
                        break;
                    case 'c': sb.Append(DateTimeToStr(dt)); run = 1; break;
                    case 't': sb.Append(run == 1 ? d.ToString("t", ci) : d.ToString("T", ci)); run = Math.Min(run, 2); break;
                    case '/': sb.Append(ci.DateTimeFormat.DateSeparator); run = 1; break;
                    case ':': sb.Append(ci.DateTimeFormat.TimeSeparator); run = 1; break;
                    default:
                        sb.Append(fmt, i, run);
                        break;
                }
                i += run;
            }
            return sb.ToString();
        }

        // ============================================================== files & paths

        public static string ExtractFileName(string path) => Path.GetFileName(path ?? "");
        public static string ExtractFilePath(string path)
        {
            path ??= "";
            int i = Math.Max(path.LastIndexOf('\\'), Math.Max(path.LastIndexOf('/'), path.LastIndexOf(':')));
            return i < 0 ? "" : path.Substring(0, i + 1);
        }
        public static string ExtractFileDir(string path) => ExcludeTrailingPathDelimiter(ExtractFilePath(path));
        public static string ExtractFileExt(string path) => Path.GetExtension(path ?? "");
        public static string ExtractFileDrive(string path) => Path.GetPathRoot(path ?? "")?.TrimEnd('\\') ?? "";
        public static string ChangeFileExt(string path, string ext) => Path.ChangeExtension(path ?? "", string.IsNullOrEmpty(ext) ? null : ext);
        public static string ExpandFileName(string path) => Path.GetFullPath(path ?? ".");
        public static string IncludeTrailingPathDelimiter(string s) => string.IsNullOrEmpty(s) || s.EndsWith("\\") || s.EndsWith("/") ? s ?? "" : s + "\\";
        public static string IncludeTrailingBackslash(string s) => IncludeTrailingPathDelimiter(s);
        public static string ExcludeTrailingPathDelimiter(string s) => (s ?? "").Length > 1 && (s.EndsWith("\\") || s.EndsWith("/")) ? s.Substring(0, s.Length - 1) : s ?? "";
        public static string ExcludeTrailingBackslash(string s) => ExcludeTrailingPathDelimiter(s);
        public static bool FileExists(string path) => File.Exists(path);
        public static bool DirectoryExists(string path) => Directory.Exists(path);
        public static bool ForceDirectories(string path) { Directory.CreateDirectory(path); return true; }
        public static bool CreateDir(string path) { try { Directory.CreateDirectory(path); return true; } catch { return false; } }
        public static bool RemoveDir(string path) { try { Directory.Delete(path); return true; } catch { return false; } }
        public static bool DeleteFile(string path) { try { if (!File.Exists(path)) return false; File.Delete(path); return true; } catch { return false; } }
        public static bool RenameFile(string oldName, string newName) { try { File.Move(oldName, newName); return true; } catch { return false; } }
        public static bool CopyFile(string source, string dest, bool failIfExists) { try { File.Copy(source, dest, !failIfExists); return true; } catch { return false; } }
        public static string GetCurrentDir() => Directory.GetCurrentDirectory();
        public static bool SetCurrentDir(string dir) { try { Directory.SetCurrentDirectory(dir); return true; } catch { return false; } }
        public static void ChDir(string dir) => Directory.SetCurrentDirectory(dir);
        public static long FileSizeOf(string path) => File.Exists(path) ? new FileInfo(path).Length : -1;
        public static double FileDateToDateTime(string path) => File.GetLastWriteTime(path).ToOADate();
        public static string GetTempDir() => Path.GetTempPath();

        /// <summary>Lists files matching a mask (replacement for FindFirst/FindNext loops).</summary>
        public static string[] FindFiles(string mask) =>
            Directory.Exists(ExtractFileDir(mask)) ? Directory.GetFiles(ExtractFileDir(mask) == "" ? "." : ExtractFileDir(mask), ExtractFileName(mask)) : new string[0];

