        // ============================================================== sets
        // Delphi sets are represented as HashSet<T>.

        /// <summary>Builds a set from ranges, e.g. Rtl.SetOf(('a','z'), ('_','_')) for ['a'..'z','_'].</summary>
        public static HashSet<T> SetOf<T>(params (T Low, T High)[] ranges)
        {
            var set = new HashSet<T>();
            foreach (var r in ranges)
            {
                long lo = Convert.ToInt64(r.Low is Enum ? (object)Convert.ToInt64(r.Low) : r.Low, CultureInfo.InvariantCulture);
                long hi = Convert.ToInt64(r.High is Enum ? (object)Convert.ToInt64(r.High) : r.High, CultureInfo.InvariantCulture);
                for (long v = lo; v <= hi; v++) set.Add(FromOrdinal<T>(v));
            }
            return set;
        }

        private static T FromOrdinal<T>(long v)
        {
            var t = typeof(T);
            if (t.IsEnum) return (T)Enum.ToObject(t, v);
            if (t == typeof(char)) return (T)(object)(char)v;
            return (T)Convert.ChangeType(v, t, CultureInfo.InvariantCulture);
        }

        public static HashSet<T> SetUnion<T>(HashSet<T> a, HashSet<T> b) { var r = new HashSet<T>(a ?? new HashSet<T>()); if (b != null) r.UnionWith(b); return r; }
        public static HashSet<T> SetDifference<T>(HashSet<T> a, HashSet<T> b) { var r = new HashSet<T>(a ?? new HashSet<T>()); if (b != null) r.ExceptWith(b); return r; }
        public static HashSet<T> SetIntersect<T>(HashSet<T> a, HashSet<T> b) { var r = new HashSet<T>(a ?? new HashSet<T>()); r.IntersectWith(b ?? new HashSet<T>()); return r; }
        public static bool SetEquals<T>(HashSet<T> a, HashSet<T> b) => (a ?? new HashSet<T>()).SetEquals(b ?? new HashSet<T>());
        public static bool SetSubset<T>(HashSet<T> a, HashSet<T> b) => (a ?? new HashSet<T>()).IsSubsetOf(b ?? new HashSet<T>());
        public static bool SetSuperset<T>(HashSet<T> a, HashSet<T> b) => (a ?? new HashSet<T>()).IsSupersetOf(b ?? new HashSet<T>());
        public static HashSet<T> SetCopy<T>(HashSet<T> a) => new HashSet<T>(a ?? new HashSet<T>());

