        public static string ReadLn() => Console.ReadLine() ?? "";
        public static void ReadLn(out string s) => s = Console.ReadLine() ?? "";
        public static void ReadLn(out int v) => v = StrToIntDef(Console.ReadLine(), 0);
        public static void ReadLn(out double v) => v = StrToFloatDef(Console.ReadLine(), 0);
        public static void Read(out char c) { int k = Console.Read(); c = k < 0 ? '\0' : (char)k; }

        public static void Write(TextFile f, params object[] args) => f.Write(args);
        public static void WriteLn(TextFile f, params object[] args) { f.Write(args); f.Write("\r\n"); }
        public static void ReadLn(TextFile f, out string s) => s = f.ReadLine();
        public static void ReadLn(TextFile f) => f.ReadLine();
        public static void AssignFile(TextFile f, string fileName) => f.FileName = fileName;
        public static void Assign(TextFile f, string fileName) => f.FileName = fileName;
        public static void Reset(TextFile f) => f.OpenRead();
        public static void Rewrite(TextFile f) => f.OpenWrite(false);
        public static void Append(TextFile f) => f.OpenWrite(true);
        public static void CloseFile(TextFile f) => f.Close();
        public static void Close(TextFile f) => f.Close();
        public static bool Eof(TextFile f) => f.Eof;
        public static bool Eof() => Console.In.Peek() < 0;
        public static void Flush(TextFile f) => f.Flush();
        public static int IOResult() => 0;

        // ============================================================== dialogs

        private static Window ActiveWindow() =>
            System.Windows.Application.Current?.Windows.OfType<Window>().FirstOrDefault(w => w.IsActive)
            ?? System.Windows.Application.Current?.MainWindow;

        private static string AppTitle() => Application.Title;

        public static void ShowMessage(string msg)
        {
            if (SmokeTest.Enabled) { SmokeTest.Log("ShowMessage: " + msg); return; }
            var owner = ActiveWindow();
            if (owner != null && owner.IsVisible) MessageBox.Show(owner, msg ?? "", AppTitle());
            else MessageBox.Show(msg ?? "", AppTitle());
        }

        public static void ShowMessageFmt(string fmt, params object[] args) => ShowMessage(Format(fmt, args));

        /// <summary>MessageDlg(Msg, mtConfirmation, [mbYes, mbNo], 0) - returns mrXXX.</summary>
        public static int MessageDlg(string msg, TMsgDlgType type, HashSet<TMsgDlgBtn> buttons, int helpCtx = 0)
        {
            buttons ??= new HashSet<TMsgDlgBtn> { TMsgDlgBtn.mbOK };
            if (SmokeTest.Enabled)
            {
                // Unattended run: answer No/Cancel where possible so nothing is saved, deleted or sent.
                SmokeTest.Log($"MessageDlg ({type}): {msg}");
                return buttons.Contains(TMsgDlgBtn.mbNo) ? mrNo : buttons.Contains(TMsgDlgBtn.mbCancel) ? mrCancel : mrOk;
            }
            MessageBoxButton b;
            if (buttons.Contains(TMsgDlgBtn.mbYes) && buttons.Contains(TMsgDlgBtn.mbNo))
                b = buttons.Contains(TMsgDlgBtn.mbCancel) ? MessageBoxButton.YesNoCancel : MessageBoxButton.YesNo;
            else if (buttons.Contains(TMsgDlgBtn.mbCancel) || buttons.Contains(TMsgDlgBtn.mbAbort))
                b = MessageBoxButton.OKCancel;
            else b = MessageBoxButton.OK;

            MessageBoxImage img;
            string caption;
            switch (type)
            {
                case TMsgDlgType.mtWarning: img = MessageBoxImage.Warning; caption = "Warning"; break;
                case TMsgDlgType.mtError: img = MessageBoxImage.Error; caption = "Error"; break;
                case TMsgDlgType.mtInformation: img = MessageBoxImage.Information; caption = "Information"; break;
                case TMsgDlgType.mtConfirmation: img = MessageBoxImage.Question; caption = "Confirm"; break;
                default: img = MessageBoxImage.None; caption = AppTitle(); break;
            }
            var owner = ActiveWindow();
            var r = owner != null && owner.IsVisible ? MessageBox.Show(owner, msg ?? "", caption, b, img) : MessageBox.Show(msg ?? "", caption, b, img);
            switch (r)
            {
                case MessageBoxResult.Yes: return mrYes;
                case MessageBoxResult.No: return mrNo;
                case MessageBoxResult.OK: return buttons.Contains(TMsgDlgBtn.mbAbort) ? mrAbort : mrOk;
                default: return mrCancel;
            }
        }

        public static int MessageDlgPos(string msg, TMsgDlgType type, HashSet<TMsgDlgBtn> buttons, int helpCtx, int x, int y) =>
            MessageDlg(msg, type, buttons, helpCtx);

        /// <summary>Windows MessageBox (Application.MessageBox / Windows.MessageBox) - returns IDxxx.</summary>
        public static int MessageBoxApi(string text, string caption, int flags)
        {
            if (SmokeTest.Enabled)
            {
                SmokeTest.Log($"MessageBox: {caption}: {text}");
                switch (flags & 0x0F) { case MB_YESNO: return IDNO; case MB_OK: return IDOK; default: return IDCANCEL; }
            }
            MessageBoxButton b;
            switch (flags & 0x0F)
            {
                case MB_OKCANCEL: b = MessageBoxButton.OKCancel; break;
                case MB_YESNOCANCEL: b = MessageBoxButton.YesNoCancel; break;
                case MB_YESNO: b = MessageBoxButton.YesNo; break;
                case MB_RETRYCANCEL: case MB_ABORTRETRYIGNORE: b = MessageBoxButton.OKCancel; break;
                default: b = MessageBoxButton.OK; break;
            }
            MessageBoxImage img;
            switch (flags & 0xF0)
            {
                case MB_ICONERROR: img = MessageBoxImage.Error; break;
                case MB_ICONQUESTION: img = MessageBoxImage.Question; break;
                case MB_ICONWARNING: img = MessageBoxImage.Warning; break;
                case MB_ICONINFORMATION: img = MessageBoxImage.Information; break;
                default: img = MessageBoxImage.None; break;
            }
            var owner = ActiveWindow();
            var r = owner != null && owner.IsVisible ? MessageBox.Show(owner, text ?? "", caption ?? "", b, img) : MessageBox.Show(text ?? "", caption ?? "", b, img);
            switch (r)
            {
                case MessageBoxResult.Yes: return IDYES;
                case MessageBoxResult.No: return IDNO;
                case MessageBoxResult.OK: return (flags & 0x0F) == MB_RETRYCANCEL ? IDRETRY : IDOK;
                default: return IDCANCEL;
            }
        }

        /// <summary>InputBox(Caption, Prompt, Default) - simple modal WPF prompt.</summary>
        public static string InputBox(string caption, string prompt, string defaultValue)
        {
            string value = defaultValue ?? "";
            return InputQuery(caption, prompt, ref value) ? value : defaultValue ?? "";
        }

        public static bool InputQuery(string caption, string prompt, ref string value)
        {
            if (SmokeTest.Enabled) { SmokeTest.Log($"InputQuery: {caption}: {prompt} (cancelled)"); return false; }
            var w = new Window
            {
                Title = caption ?? "", SizeToContent = SizeToContent.WidthAndHeight, ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner, ShowInTaskbar = false, MinWidth = 320
            };
            w.SetResourceReference(Control.BackgroundProperty, SystemColors.ControlBrushKey); // theme-aware (Modern UI)
            var owner = ActiveWindow();
            if (owner != null && owner.IsVisible) w.Owner = owner;
            var panel = new StackPanel { Margin = new Thickness(12) };
            panel.Children.Add(new TextBlock { Text = prompt ?? "", Margin = new Thickness(0, 0, 0, 6) });
            var tb = new TextBox { Text = value ?? "", MinWidth = 290 };
            panel.Children.Add(tb);
            var buttons = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 12, 0, 0) };
            var ok = new Button { Content = "OK", Width = 75, IsDefault = true, Margin = new Thickness(0, 0, 6, 0) };
            var cancel = new Button { Content = "Cancel", Width = 75, IsCancel = true };
            ok.Click += (s, e) => w.DialogResult = true;
            buttons.Children.Add(ok);
            buttons.Children.Add(cancel);
            panel.Children.Add(buttons);
            w.Content = panel;
            w.Loaded += (s, e) => { tb.Focus(); tb.SelectAll(); };
            bool result = w.ShowDialog() == true;
            if (result) value = tb.Text;
            return result;
        }

