        /// <summary>Global Application object (Forms.Application).</summary>
        public static readonly TApplication Application = new TApplication();
        /// <summary>Global Screen object (Forms.Screen).</summary>
        public static readonly TScreen Screen = new TScreen();
        /// <summary>Global Mouse object.</summary>
        public static TPoint MouseCursorPos()
        {
            var w = ActiveWindow();
            if (w == null) return new TPoint();
            var p = w.PointToScreen(System.Windows.Input.Mouse.GetPosition(w));
            return new TPoint((int)p.X, (int)p.Y);
        }

        internal static bool _shuttingDown;

        // ============================================================== colours & brushes

        /// <summary>Resolves system colours ($FF0000xx) to an RGB TColor.</summary>
        public static int ToColorRef(int color)
        {
            if ((color & unchecked((int)0xFF000000)) != unchecked((int)0xFF000000)) return color & 0xFFFFFF;
            Color c;
            if (Modern.Enabled && Modern.TryMapSystemColor(color & 0xFF, out c)) return c.R | (c.G << 8) | (c.B << 16);
            switch (color & 0xFF)
            {
                case 1: c = SystemColors.DesktopColor; break;
                case 2: c = SystemColors.ActiveCaptionColor; break;
                case 3: c = SystemColors.InactiveCaptionColor; break;
                case 4: c = SystemColors.MenuColor; break;
                case 5: c = SystemColors.WindowColor; break;
                case 6: c = SystemColors.WindowFrameColor; break;
                case 7: c = SystemColors.MenuTextColor; break;
                case 8: c = SystemColors.WindowTextColor; break;
                case 9: c = SystemColors.ActiveCaptionTextColor; break;
                case 12: c = SystemColors.AppWorkspaceColor; break;
                case 13: c = SystemColors.HighlightColor; break;
                case 14: c = SystemColors.HighlightTextColor; break;
                case 15: c = SystemColors.ControlColor; break;
                case 16: c = SystemColors.ControlDarkColor; break;
                case 17: c = SystemColors.GrayTextColor; break;
                case 18: c = SystemColors.ControlTextColor; break;
                case 20: c = SystemColors.ControlLightLightColor; break;
                case 21: c = SystemColors.ControlDarkDarkColor; break;
                case 22: c = SystemColors.ControlLightColor; break;
                case 23: c = SystemColors.InfoTextColor; break;
                case 24: c = SystemColors.InfoColor; break;
                default: c = SystemColors.ControlColor; break;
            }
            return c.R | (c.G << 8) | (c.B << 16);
        }

        public static Color ToMediaColor(int color)
        {
            int rgb = ToColorRef(color);
            return Color.FromRgb((byte)(rgb & 0xFF), (byte)((rgb >> 8) & 0xFF), (byte)((rgb >> 16) & 0xFF));
        }

        public static Brush ToBrush(int color)
        {
            if (color == clNone) return Brushes.Transparent;
            var b = new SolidColorBrush(ToMediaColor(color));
            b.Freeze();
            return b;
        }

        public static int FromBrush(Brush b)
        {
            if (b is SolidColorBrush s) return RGB(s.Color.R, s.Color.G, s.Color.B);
            return clNone;
        }

        // ============================================================== VCL-style control access
        // The converter rewrites VCL property access on controls to these helpers,
        // e.g. Button1.Caption := 'OK'  ->  Rtl.SetCaption(Button1, "OK").

        /// <summary>Converts a Delphi caption ('&amp;File') into a WPF access-key text ('_File').</summary>
        public static string ToAccessText(string caption)
        {
            if (caption == null) return "";
            var sb = new StringBuilder();
            for (int i = 0; i < caption.Length; i++)
            {
                char ch = caption[i];
                if (ch == '_') sb.Append("__");
                else if (ch == '&')
                {
                    if (i + 1 < caption.Length && caption[i + 1] == '&') { sb.Append('&'); i++; }
                    else sb.Append('_');
                }
                else sb.Append(ch);
            }
            return sb.ToString();
        }

        /// <summary>Converts WPF access-key text back to a Delphi caption.</summary>
        public static string FromAccessText(string text)
        {
            if (text == null) return "";
            var sb = new StringBuilder();
            for (int i = 0; i < text.Length; i++)
            {
                char ch = text[i];
                if (ch == '&') sb.Append("&&");
                else if (ch == '_')
                {
                    if (i + 1 < text.Length && text[i + 1] == '_') { sb.Append('_'); i++; }
                    else sb.Append('&');
                }
                else sb.Append(ch);
            }
            return sb.ToString();
        }

        private static string StripAccess(string s) => (s ?? "").Replace("&&", "\u0001").Replace("&", "").Replace("\u0001", "&");

        public static string GetCaption(object c)
        {
            switch (c)
            {
                case null: return "";
                case Window w: return w.Title ?? "";
                case TAction a: return a.Caption;
                case HeaderedContentControl h: return h.Header is string hs ? FromAccessText(hs) : Convert.ToString(h.Header, CultureInfo.CurrentCulture) ?? "";
                case HeaderedItemsControl hi: return hi.Header is string his ? FromAccessText(his) : Convert.ToString(hi.Header, CultureInfo.CurrentCulture) ?? "";
                case ContentControl cc:
                    if (cc.Content is string s) return FromAccessText(s);
                    if (cc.Content is TextBlock t) return t.Text;
                    if (cc.Content is AccessText at) return FromAccessText(at.Text);
                    return Convert.ToString(cc.Content, CultureInfo.CurrentCulture) ?? "";
                case TextBlock tb: return tb.Text;
                case Border b:
                    {
                        var tbc = FindCaptionBlock(b);
                        return tbc?.Text ?? "";
                    }
                default: return "";
            }
        }

        public static void SetCaption(object c, string value)
        {
            value ??= "";
            switch (c)
            {
                case null: return;
                case Window w: w.Title = value; break;
                case TAction a: a.Caption = value; break;
                case HeaderedContentControl h: h.Header = ToAccessText(value); break;
                case HeaderedItemsControl hi: hi.Header = ToAccessText(value); break;
                case ContentControl cc:
                    if (cc.Content is TextBlock t) t.Text = StripAccess(value);
                    else cc.Content = ToAccessText(value);
                    break;
                case TextBlock tb: tb.Text = StripAccess(value); break;
                case Border b:
                    {
                        var tbc = FindCaptionBlock(b);
                        if (tbc != null) tbc.Text = value;
                        break;
                    }
            }
        }

        private static TextBlock FindCaptionBlock(DependencyObject root)
        {
            if (root is TextBlock tb && Equals(tb.Tag, "Caption")) return tb;
            if (root is Border b && b.Child != null) return FindCaptionBlock(b.Child);
            if (root is Panel p) foreach (UIElement ch in p.Children) { var r = FindCaptionBlock(ch); if (r != null) return r; }
            return null;
        }

        public static string GetText(object c)
        {
            switch (c)
            {
                case TextBox t: return t.Text;
                case PasswordBox p: return p.Password;
                case ComboBox cb: return cb.IsEditable ? cb.Text : Convert.ToString(cb.SelectedItem, CultureInfo.CurrentCulture) ?? "";
                case DatePicker dp: return dp.Text;
                default: return GetCaption(c);
            }
        }

        public static void SetText(object c, string value)
        {
            value ??= "";
            switch (c)
            {
                case TextBox t: t.Text = value; break;
                case PasswordBox p: p.Password = value; break;
                case ComboBox cb:
                    // VCL: ComboBox.Text := ... in code does not raise OnChange.
                    WithoutEvents(cb, () =>
                    {
                        if (cb.IsEditable) cb.Text = value;
                        else cb.SelectedItem = cb.Items.Cast<object>().FirstOrDefault(i => Convert.ToString(i, CultureInfo.CurrentCulture) == value);
                    });
                    break;
                case DatePicker dp: dp.Text = value; break;
                default: SetCaption(c, value); break;
            }
        }

        public static bool GetVisible(object c)
        {
            if (c is Window w) return w.IsVisible;
            if (c is UIElement u) return u.Visibility == Visibility.Visible;
            if (c is TAction a) return a.Visible;
            return false;
        }

        public static void SetVisible(object c, bool value)
        {
            if (c is Window w) { if (value) w.Show(); else w.Hide(); }
            else if (c is UIElement u) u.Visibility = value ? Visibility.Visible : Visibility.Collapsed;
            else if (c is TAction a) a.Visible = value;
        }

        public static bool GetEnabled(object c) => c is UIElement u ? u.IsEnabled : c is TAction a && a.Enabled;
        public static void SetEnabled(object c, bool value)
        {
            if (c is UIElement u) u.IsEnabled = value;
            else if (c is TAction a) a.Enabled = value;
            else if (c is TTimer t) t.Enabled = value;
        }

        public static bool GetChecked(object c)
        {
            switch (c)
            {
                case ToggleButton t: return t.IsChecked == true;
                case MenuItem m: return m.IsChecked;
                case TAction a: return a.Checked;
                default: return false;
            }
        }

        public static void SetChecked(object c, bool value)
        {
            switch (c)
            {
                case ToggleButton t: t.IsChecked = value; break;
                case MenuItem m: m.IsCheckable = true; m.IsChecked = value; break;
                case TAction a: a.Checked = value; break;
            }
        }

        /// <summary>TCheckBox.State: 0 = cbUnchecked, 1 = cbChecked, 2 = cbGrayed.</summary>
        public static int GetCheckState(object c) => c is ToggleButton t ? (t.IsChecked == null ? 2 : t.IsChecked == true ? 1 : 0) : 0;
        public static void SetCheckState(object c, int state) { if (c is ToggleButton t) t.IsChecked = state == 2 ? (bool?)null : state == 1; }
        public const int cbUnchecked = 0, cbChecked = 1, cbGrayed = 2;

        public static int GetItemIndex(object c)
        {
            switch (c)
            {
                case Selector s: return s.SelectedIndex;
                case GroupBox g:
                    {
                        var radios = RadioButtonsOf(g);
                        for (int i = 0; i < radios.Count; i++) if (radios[i].IsChecked == true) return i;
                        return -1;
                    }
                default: return -1;
            }
        }

        public static void SetItemIndex(object c, int index)
        {
            switch (c)
            {
                // VCL: ItemIndex := n in code does not raise OnClick/OnChange (only user selection does).
                case Selector s: WithoutEvents(s, () => s.SelectedIndex = index); break;
                case GroupBox g:
                    {
                        var radios = RadioButtonsOf(g);
                        for (int i = 0; i < radios.Count; i++) radios[i].IsChecked = i == index;
                        break;
                    }
            }
        }

        internal static Panel RadioPanelOf(GroupBox g) => g.Content as Panel;
        internal static List<RadioButton> RadioButtonsOf(GroupBox g) =>
            (RadioPanelOf(g)?.Children.OfType<RadioButton>() ?? Enumerable.Empty<RadioButton>()).ToList();

        /// <summary>ListBox1.Items / ComboBox1.Items / RadioGroup1.Items as TStrings.</summary>
        public static TStrings Items(object c)
        {
            switch (c)
            {
                case ItemsControl ic: return new ItemsControlStrings(ic);
                case GroupBox g: return new RadioGroupStrings(g);
                default: return new TStringList();
            }
        }

        /// <summary>Memo1.Lines as TStrings.</summary>
        public static TStrings Lines(object c) => c is TextBox t ? new TextBoxLines(t) : (TStrings)new TStringList();

        public static int GetSelStart(object c) => c is TextBox t ? t.SelectionStart : 0;
        public static void SetSelStart(object c, int v) { if (c is TextBox t) t.SelectionStart = Math.Max(0, Math.Min(v, t.Text.Length)); }
        public static int GetSelLength(object c) => c is TextBox t ? t.SelectionLength : 0;
        public static void SetSelLength(object c, int v) { if (c is TextBox t) t.SelectionLength = Math.Max(0, v); }
        public static string GetSelText(object c) => c is TextBox t ? t.SelectedText : "";
        public static void SetSelText(object c, string v) { if (c is TextBox t) t.SelectedText = v ?? ""; }

        public static int GetLeft(object c) => (int)Math.Round(c is Window w ? w.Left : c is FrameworkElement f ? (f.Parent is Canvas ? Canvas.GetLeft(f) : f.Margin.Left) : 0);
        public static int GetTop(object c) => (int)Math.Round(c is Window w ? w.Top : c is FrameworkElement f ? (f.Parent is Canvas ? Canvas.GetTop(f) : f.Margin.Top) : 0);

        public static void SetLeft(object c, int v)
        {
            if (c is Window w) w.Left = v;
            else if (c is FrameworkElement f)
            {
                if (f.Parent is Canvas) Canvas.SetLeft(f, v);
                else { var m = f.Margin; f.Margin = new Thickness(v, m.Top, m.Right, m.Bottom); }
            }
        }

        public static void SetTop(object c, int v)
        {
            if (c is Window w) w.Top = v;
            else if (c is FrameworkElement f)
            {
                if (f.Parent is Canvas) Canvas.SetTop(f, v);
                else { var m = f.Margin; f.Margin = new Thickness(m.Left, v, m.Right, m.Bottom); }
            }
        }

        // Size recorded from the form file for controls without a fixed Width/Height in XAML (stretched or
        // docked). Used before the first layout pass and while a control is on a hidden tab page, where
        // ActualWidth/ActualHeight are 0 but Delphi code expects the designed size.
        public static readonly DependencyProperty DesignWidthProperty =
            DependencyProperty.RegisterAttached("DesignWidth", typeof(double), typeof(Rtl), new PropertyMetadata(double.NaN));
        public static readonly DependencyProperty DesignHeightProperty =
            DependencyProperty.RegisterAttached("DesignHeight", typeof(double), typeof(Rtl), new PropertyMetadata(double.NaN));
        public static double GetDesignWidth(DependencyObject d) => (double)d.GetValue(DesignWidthProperty);
        public static void SetDesignWidth(DependencyObject d, double v) => d.SetValue(DesignWidthProperty, v);
        public static double GetDesignHeight(DependencyObject d) => (double)d.GetValue(DesignHeightProperty);
        public static void SetDesignHeight(DependencyObject d, double v) => d.SetValue(DesignHeightProperty, v);

        /// <summary>Delphi Width: actual size once laid out, else the XAML Width, else the size from the form file.</summary>
        public static int GetWidth(object c)
        {
            if (!(c is FrameworkElement f)) return 0;
            if (f.ActualWidth > 0) return (int)Math.Round(f.ActualWidth);
            if (!double.IsNaN(f.Width)) return (int)Math.Round(f.Width);
            double d = GetDesignWidth(f);
            return double.IsNaN(d) ? 0 : (int)Math.Round(d);
        }

        /// <summary>Delphi Height: actual size once laid out, else the XAML Height, else the size from the form file.</summary>
        public static int GetHeight(object c)
        {
            if (!(c is FrameworkElement f)) return 0;
            if (f.ActualHeight > 0) return (int)Math.Round(f.ActualHeight);
            if (!double.IsNaN(f.Height)) return (int)Math.Round(f.Height);
            double d = GetDesignHeight(f);
            return double.IsNaN(d) ? 0 : (int)Math.Round(d);
        }
        public static void SetWidth(object c, int v) { if (c is FrameworkElement f) f.Width = Math.Max(0, v); }
        public static void SetHeight(object c, int v) { if (c is FrameworkElement f) f.Height = Math.Max(0, v); }

        public static int GetClientWidth(object c) => c is Window w && w.Content is FrameworkElement f && f.ActualWidth > 0 ? (int)f.ActualWidth : c is Window w2 && w2.Content is FrameworkElement f2 ? GetWidth(f2) : GetWidth(c);
        public static int GetClientHeight(object c) => c is Window w && w.Content is FrameworkElement f && f.ActualHeight > 0 ? (int)f.ActualHeight : c is Window w2 && w2.Content is FrameworkElement f2 ? GetHeight(f2) : GetHeight(c);
        public static void SetClientWidth(object c, int v) { if (c is Window w && w.Content is FrameworkElement f) w.Width = w.ActualWidth - f.ActualWidth + v; else SetWidth(c, v); }
        public static void SetClientHeight(object c, int v) { if (c is Window w && w.Content is FrameworkElement f) w.Height = w.ActualHeight - f.ActualHeight + v; else SetHeight(c, v); }

        public static int GetColor(object c)
        {
            switch (c)
            {
                case Control ctl: return FromBrush(ctl.Background);
                case Panel p: return FromBrush(p.Background);
                case Border b: return FromBrush(b.Background);
                case System.Windows.Shapes.Shape s: return FromBrush(s.Fill);
                case TextBlock t: return FromBrush(t.Background);
                default: return clNone;
            }
        }

        public static void SetColor(object c, int color)
        {
            var brush = ToBrush(color);
            switch (c)
            {
                case Control ctl: ctl.Background = brush; break;
                case Panel p: p.Background = brush; break;
                case Border b: b.Background = brush; break;
                case System.Windows.Shapes.Shape s: s.Fill = brush; break;
                case TextBlock t: t.Background = brush; break;
            }
        }

        /// <summary>Control.Font as a TFont that writes through to the control.</summary>
        public static TFont Font(object c) => new TFont(c as DependencyObject);

        public static string GetHint(object c) => c is FrameworkElement f ? Convert.ToString(f.ToolTip, CultureInfo.CurrentCulture) ?? "" : c is TAction a ? a.Hint : "";
        public static void SetHint(object c, string v) { if (c is FrameworkElement f) f.ToolTip = string.IsNullOrEmpty(v) ? null : v; else if (c is TAction a) a.Hint = v; }

        public static int GetPosition(object c) => c is RangeBase r ? (int)Math.Round(r.Value) : 0;
        public static void SetPosition(object c, int v) { if (c is RangeBase r) r.Value = Math.Max(r.Minimum, Math.Min(r.Maximum, v)); }
        public static int GetMax(object c) => c is RangeBase r ? (int)r.Maximum : 0;
        public static void SetMax(object c, int v) { if (c is RangeBase r) r.Maximum = v; }
        public static int GetMin(object c) => c is RangeBase r ? (int)r.Minimum : 0;
        public static void SetMin(object c, int v) { if (c is RangeBase r) r.Minimum = v; }

        public static bool GetReadOnly(object c) => c is TextBoxBase t && t.IsReadOnly;
        public static void SetReadOnly(object c, bool v) { if (c is TextBoxBase t) t.IsReadOnly = v; else if (c is ComboBox cb) cb.IsReadOnly = v; }

        /// <summary>
        /// Delphi Tag. XAML stores the form-file value as a string ("1"); string grids keep it as the
        /// last part of "grid:cols:rows:tag". SetTag stores an int.
        /// </summary>
        public static int GetTag(object c)
        {
            object t = c is FrameworkElement f ? f.Tag : c is FrameworkContentElement fc ? fc.Tag : null;
            switch (t)
            {
                case int i: return i;
                case long l: return (int)l;
                case string s when s.StartsWith("grid:", StringComparison.Ordinal):
                    var parts = s.Split(':');
                    return parts.Length > 3 && int.TryParse(parts[3], NumberStyles.Integer, CultureInfo.InvariantCulture, out int g) ? g : 0;
                case string s when int.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture, out int v): return v;
                default: return 0;
            }
        }
        public static void SetTag(object c, int v)
        {
            if (c is DataGrid g && g.Tag is string gs && gs.StartsWith("grid:", StringComparison.Ordinal))
            {
                var parts = gs.Split(':');
                g.Tag = $"grid:{parts[1]}:{parts[2]}:{v}"; // keep the grid's column/row information
            }
            else if (c is FrameworkElement f) f.Tag = v;
            else if (c is FrameworkContentElement fc) fc.Tag = v;
        }

        public static string GetName(object c) => c is FrameworkElement f ? f.Name : "";

        public static void ClearControl(object c)
        {
            switch (c)
            {
                case TextBox t: t.Clear(); break;
                case PasswordBox p: p.Clear(); break;
                case ItemsControl ic: ic.Items.Clear(); break;
            }
        }

        public static void SetFocus(object c) { if (c is UIElement u) u.Focus(); }
        public static bool Focused(object c) => c is UIElement u && u.IsKeyboardFocusWithin;
        /// <summary>Control.BringToFront: above every sibling (repeated calls keep the latest one on top, as in the VCL).</summary>
        public static void BringToFront(object c)
        {
            if (c is Window w) { w.Activate(); return; }
            if (!(c is UIElement u)) return;
            int max = 0;
            if (VisualTreeHelper.GetParent(u) is Panel p)
                foreach (UIElement sibling in p.Children) if (sibling != u) max = Math.Max(max, Panel.GetZIndex(sibling));
            Panel.SetZIndex(u, max + 1);
        }

        /// <summary>Control.SendToBack: below every sibling.</summary>
        public static void SendToBack(object c)
        {
            if (!(c is UIElement u)) return;
            int min = 0;
            if (VisualTreeHelper.GetParent(u) is Panel p)
                foreach (UIElement sibling in p.Children) if (sibling != u) min = Math.Min(min, Panel.GetZIndex(sibling));
            Panel.SetZIndex(u, min - 1);
        }
        /// <summary>
        /// Control.Parent := Container - places a control created in code (TEdit.Create(Self) ...) inside a
        /// panel, group box, scroll box, tab page or form. It is positioned like a VCL control: Left/Top
        /// (Rtl.SetLeft/SetTop) become the margin from the container's top-left corner.
        /// Parent := nil removes it again.
        /// </summary>
        public static void SetParent(object control, object parent)
        {
            if (!(control is FrameworkElement child)) return;
            Detach(child);
            if (parent == null) return;
            var host = HostPanel(parent);
            if (host == null) return;
            if (child.HorizontalAlignment == HorizontalAlignment.Stretch) child.HorizontalAlignment = HorizontalAlignment.Left;
            if (child.VerticalAlignment == VerticalAlignment.Stretch) child.VerticalAlignment = VerticalAlignment.Top;
            host.Children.Add(child);
        }

        /// <summary>Control.Parent: the converted container (panel, group box, scroll box ...) a control is in.</summary>
        public static object GetParent(object control)
        {
            var d = control as DependencyObject;
            if (d == null) return null;
            var p = LogicalTreeHelper.GetParent(d) ?? VisualTreeHelper.GetParent(d);
            // Skip the layout panels the converter puts inside containers; report the container itself.
            while (p is Panel && !(p is Canvas) && (LogicalTreeHelper.GetParent(p) is FrameworkElement up) && (up is Panel || up is ScrollViewer || up is Border || up is ContentControl))
            {
                if (up is Window || up is UserControl || up is GroupBox || up is TabItem || up is ScrollViewer || up is Border) return up;
                p = up;
            }
            return p;
        }

        private static void Detach(FrameworkElement child)
        {
            switch (LogicalTreeHelper.GetParent(child) ?? VisualTreeHelper.GetParent(child))
            {
                case Panel p: p.Children.Remove(child); break;
                case ContentControl cc when cc.Content == child: cc.Content = null; break;
                case Decorator dec when dec.Child == child: dec.Child = null; break;
            }
        }

        /// <summary>The Panel inside a converted container that holds its freely positioned controls.</summary>
        private static Panel HostPanel(object container)
        {
            object content = container;
            for (int depth = 0; depth < 6 && content != null; depth++)
            {
                switch (content)
                {
                    case Panel p: return p;
                    case ScrollViewer sv: content = sv.Content; break;
                    case ContentControl cc:
                        if (cc.Content is Panel || cc.Content is FrameworkElement) { content = cc.Content; break; }
                        var g = new Grid(); cc.Content = g; return g;
                    case Decorator d:
                        if (d.Child != null) { content = d.Child; break; }
                        var g2 = new Grid(); d.Child = g2; return g2;
                    default: return null;
                }
            }
            return content as Panel;
        }

        /// <summary>Control.BorderStyle (bsNone = 0, bsSingle = 1): shows or hides the control's border.</summary>
        public static void SetBorderStyle(object c, int style)
        {
            if (c is Window w) { w.WindowStyle = style == 0 ? WindowStyle.None : WindowStyle.SingleBorderWindow; return; }
            if (c is Control ctl) ctl.BorderThickness = new Thickness(style == 0 ? 0 : 1);
            else if (c is Border b) b.BorderThickness = new Thickness(style == 0 ? 0 : 1);
        }

        public static int GetBorderStyle(object c) =>
            c is Window w ? (w.WindowStyle == WindowStyle.None ? 0 : 1)
            : c is Control ctl ? (ctl.BorderThickness.Left > 0 ? 1 : 0)
            : c is Border b ? (b.BorderThickness.Left > 0 ? 1 : 0) : 1;

        private static readonly ConditionalWeakTable<object, object> _owners = new ConditionalWeakTable<object, object>();

        /// <summary>TComponent.Create(AOwner): remembers the owner of a converted component.</summary>
        public static void SetOwner(object component, object owner)
        {
            if (component == null) return;
            _owners.Remove(component);
            if (owner != null) _owners.Add(component, owner);
        }

        /// <summary>TComponent.Owner: the registered owner, else the window that contains a control.</summary>
        public static object OwnerOf(object component)
        {
            if (component == null) return null;
            if (_owners.TryGetValue(component, out var o)) return o;
            if (component is DependencyObject d) return Window.GetWindow(d);
            return null;
        }

