        public static TStringGridModel Grid(object c) => TStringGridModel.For(c as DataGrid);

        // ---- image lists on tool bars (TToolBar.Images + TToolButton.ImageIndex)
        // ------------------------------------------------------------------ TUpDown

        /// <summary>
        /// Rtl.UpDown="True" on a ScrollBar (a converted TUpDown): shows only the two arrow buttons, like the VCL
        /// control. The buttons send the ScrollBar's LineUp/LineDown (LineLeft/LineRight) commands, so Value,
        /// SmallChange and the ValueChanged wiring of the conversion work unchanged.
        /// </summary>
        public static readonly DependencyProperty UpDownProperty =
            DependencyProperty.RegisterAttached("UpDown", typeof(bool), typeof(Rtl), new PropertyMetadata(false, (d, e) =>
            {
                if (d is ScrollBar sb && (bool)e.NewValue)
                {
                    sb.Template = UpDownTemplate(sb.Orientation);
                    sb.MinWidth = 0;
                    sb.MinHeight = 0;
                }
            }));
        public static bool GetUpDown(DependencyObject d) => (bool)d.GetValue(UpDownProperty);
        public static void SetUpDown(DependencyObject d, bool v) => d.SetValue(UpDownProperty, v);

        private static ControlTemplate _upDownV, _upDownH;

        private static ControlTemplate UpDownTemplate(Orientation o)
        {
            bool v = o == Orientation.Vertical;
            if (v && _upDownV != null) return _upDownV;
            if (!v && _upDownH != null) return _upDownH;
            // First button = up (vertical) / left (horizontal); glyphs from Segoe Fluent Icons / MDL2 (chevrons).
            string defs = v ? "<Grid.RowDefinitions><RowDefinition /><RowDefinition /></Grid.RowDefinitions>"
                            : "<Grid.ColumnDefinitions><ColumnDefinition /><ColumnDefinition /></Grid.ColumnDefinitions>";
            string pos2 = v ? "Grid.Row='1'" : "Grid.Column='1'";
            string cmd1 = v ? "ScrollBar.LineUpCommand" : "ScrollBar.LineLeftCommand", cmd2 = v ? "ScrollBar.LineDownCommand" : "ScrollBar.LineRightCommand";
            string g1 = v ? "&#xE70E;" : "&#xE76B;", g2 = v ? "&#xE70D;" : "&#xE76C;";
            string button(string pos, string cmd, string glyph) =>
                $"<RepeatButton {pos} Command='{{x:Static {cmd}}}' Focusable='False' Padding='0' Margin='0' MinWidth='0' MinHeight='0'>" +
                $"<TextBlock Text='{glyph}' FontFamily='Segoe Fluent Icons, Segoe MDL2 Assets' FontSize='7' HorizontalAlignment='Center' VerticalAlignment='Center' /></RepeatButton>";
            string xaml = "<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='ScrollBar'>" +
                          "<Grid SnapsToDevicePixels='True'>" + defs + button("", cmd1, g1) + button(pos2, cmd2, g2) + "</Grid></ControlTemplate>";
            var t = (ControlTemplate)System.Windows.Markup.XamlReader.Parse(xaml);
            if (v) _upDownV = t; else _upDownH = t;
            return t;
        }

        public static readonly DependencyProperty ImageIndexProperty =
            DependencyProperty.RegisterAttached("ImageIndex", typeof(int), typeof(Rtl), new PropertyMetadata(-1));
        public static int GetImageIndex(DependencyObject d) => (int)d.GetValue(ImageIndexProperty);
        public static void SetImageIndex(DependencyObject d, int v) => d.SetValue(ImageIndexProperty, v);

        private static readonly ConditionalWeakTable<object, TImageList> _imageLists = new ConditionalWeakTable<object, TImageList>();

        /// <summary>Control.Images (TToolBar, TListView ...).</summary>
        public static TImageList GetImages(object c) => c != null && _imageLists.TryGetValue(c, out var l) ? l : null;

        /// <summary>
        /// Control.Images := List - every button with rtl:Rtl.ImageIndex shows that image from the list
        /// (as a VCL tool bar does). Assigning another list (e.g. a different loop type) swaps the pictures.
        /// </summary>
        public static void SetImages(object c, TImageList list)
        {
            if (c == null) return;
            _imageLists.Remove(c);
            if (list != null) _imageLists.Add(c, list);
            if (c is ItemsControl ic)
                foreach (var item in ic.Items.OfType<ContentControl>())
                {
                    int index = GetImageIndex(item);
                    if (index < 0) continue;
                    var img = list?.GetImage(index);
                    item.Content = img == null ? null : new Image { Source = img, Stretch = Stretch.None, SnapsToDevicePixels = true };
                }
        }

        // Controls whose selection is being changed internally (grid columns rebuilt, Options changed ...).
        // WPF raises SelectionChanged for these changes, the VCL does not raise OnClick/OnChange, so the
        // generated event wiring skips the Delphi handler while a control is in this set.
        private static readonly HashSet<object> _suppressed = new HashSet<object>();

        /// <summary>True while the control's selection is changed by the runtime itself (no Delphi event).</summary>
        public static bool EventsSuppressed(object c) => c != null && _suppressed.Contains(c);

        /// <summary>Runs an internal change without raising the control's Delphi selection events.</summary>
        public static void WithoutEvents(object c, Action change)
        {
            if (c == null || !_suppressed.Add(c)) { change(); return; }
            try { change(); }
            finally { _suppressed.Remove(c); }
        }

        public static TPageControlModel Pages(object c) => new TPageControlModel(c as TabControl);

        // ============================================================== forms (TForm behaviour)

        private sealed class FormState
        {
            public bool IsModal;
            public int ModalResult;
            public TCloseEvent OnClose;
            public TCloseQueryEvent OnCloseQuery;
            /// <summary>True while OnCloseQuery/OnClose run (a Close call from there must not re-enter).</summary>
            public bool Closing;
        }

        /// <summary>
        /// Form.Close. Calling Close again from OnClose/OnCloseQuery is harmless in the VCL (a modal form just gets
        /// ModalResult := mrCancel); WPF throws, so a nested call is ignored here.
        /// </summary>
        public static void CloseForm(object form)
        {
            if (form is Window w)
            {
                var st = StateOf(w);
                if (st.Closing) { if (st.IsModal && st.ModalResult == mrNone) st.ModalResult = mrCancel; return; }
                w.Close();
                return;
            }
            // Other objects with a Close method (streams, data sets ...).
            form?.GetType().GetMethod("Close", Type.EmptyTypes)?.Invoke(form, null);
        }

        private static readonly ConditionalWeakTable<Window, FormState> _forms = new ConditionalWeakTable<Window, FormState>();
        private static FormState StateOf(Window w) => _forms.GetValue(w, _ => new FormState());

        /// <summary>
        /// Installs Delphi close semantics on a converted form: OnCloseQuery / OnClose
        /// handlers are honoured and non-main forms are hidden (caHide) rather than
        /// destroyed, so they can be shown again, just like auto-created VCL forms.
        /// </summary>
        public static void InstallFormBehaviour(Window w, TCloseQueryEvent onCloseQuery, TCloseEvent onClose)
        {
            var st = StateOf(w);
            st.OnClose = onClose;
            st.OnCloseQuery = onCloseQuery;
            w.Closing += (s, e) =>
            {
                if (_shuttingDown) return;
                bool canClose = true;
                bool isMain = System.Windows.Application.Current?.MainWindow == w;
                var action = isMain ? TCloseAction.caFree : TCloseAction.caHide;
                st.Closing = true;
                try
                {
                    st.OnCloseQuery?.Invoke(w, ref canClose);
                    if (!canClose) { e.Cancel = true; return; }
                    st.OnClose?.Invoke(w, ref action);
                }
                finally { st.Closing = false; }
                switch (action)
                {
                    case TCloseAction.caNone: e.Cancel = true; break;
                    case TCloseAction.caMinimize: e.Cancel = true; w.WindowState = WindowState.Minimized; break;
                    case TCloseAction.caHide:
                        if (st.IsModal && st.ModalResult == mrNone) st.ModalResult = mrCancel;
                        e.Cancel = true;
                        w.Hide();
                        break;
                    case TCloseAction.caFree:
                        if (isMain) _shuttingDown = true;
                        break;
                }
            };
        }

        /// <summary>Form.ShowModal - returns the ModalResult (mrOk, mrCancel ...).</summary>
        public static int ShowModal(Window w)
        {
            var st = StateOf(w);
            st.ModalResult = mrNone;
            st.IsModal = true;
            if (SmokeTest.Enabled)
            {
                // Unattended run: show the form without blocking, then cancel it.
                SmokeTest.Log("ShowModal " + w.GetType().Name);
                try { w.Show(); w.UpdateLayout(); }
                finally { st.IsModal = false; try { w.Hide(); } catch { } }
                return mrCancel;
            }
            var owner = ActiveWindow();
            if (owner != null && owner != w && owner.IsVisible && w.Owner == null) { try { w.Owner = owner; } catch { } }
            try { w.ShowDialog(); }
            finally { st.IsModal = false; }
            return st.ModalResult == mrNone ? mrCancel : st.ModalResult;
        }

        /// <summary>Form.ModalResult := X - ends a modal form (hides it) when X &lt;&gt; mrNone.</summary>
        public static void SetModalResult(Window w, int result)
        {
            var st = StateOf(w);
            st.ModalResult = result;
            if (result != mrNone && st.IsModal) w.Hide();
        }

        public static int GetModalResult(Window w) => StateOf(w).ModalResult;

        /// <summary>Button.ModalResult property: clicking the button ends the modal form.</summary>
        public static void SetButtonModalResult(ButtonBase b, int result)
        {
            b.Click += (s, e) =>
            {
                var w = Window.GetWindow(b);
                if (w != null) SetModalResult(w, result);
            };
        }

        public static void ShowForm(Window w) { w.Show(); w.Activate(); }
        public static void Release(Window w) { if (StateOf(w).Closing) return; _forms.Remove(w); w.Close(); }

        public static TWindowState GetWindowState(Window w) =>
            w.WindowState == WindowState.Maximized ? TWindowState.wsMaximized : w.WindowState == WindowState.Minimized ? TWindowState.wsMinimized : TWindowState.wsNormal;
        public static void SetWindowState(Window w, TWindowState s) =>
            w.WindowState = s == TWindowState.wsMaximized ? WindowState.Maximized : s == TWindowState.wsMinimized ? WindowState.Minimized : WindowState.Normal;

        public static object GetActiveControl(Window w) => FocusManager.GetFocusedElement(w);
