        // ============================================================== keyboard / mouse adapters

        /// <summary>Current TShiftState from the keyboard modifiers and mouse buttons.</summary>
        public static TShiftState CurrentShift()
        {
            var s = new TShiftState();
            var m = Keyboard.Modifiers;
            if ((m & ModifierKeys.Shift) != 0) s.Add(TShiftStateItem.ssShift);
            if ((m & ModifierKeys.Control) != 0) s.Add(TShiftStateItem.ssCtrl);
            if ((m & ModifierKeys.Alt) != 0) s.Add(TShiftStateItem.ssAlt);
            if (System.Windows.Input.Mouse.LeftButton == MouseButtonState.Pressed) s.Add(TShiftStateItem.ssLeft);
            if (System.Windows.Input.Mouse.RightButton == MouseButtonState.Pressed) s.Add(TShiftStateItem.ssRight);
            if (System.Windows.Input.Mouse.MiddleButton == MouseButtonState.Pressed) s.Add(TShiftStateItem.ssMiddle);
            return s;
        }

        /// <summary>Win32 virtual-key code (VK_xxx) of a WPF key event.</summary>
        public static ushort VirtualKey(KeyEventArgs e)
        {
            var key = e.Key == Key.System ? e.SystemKey : e.Key;
            return (ushort)KeyInterop.VirtualKeyFromKey(key);
        }

        public static TMouseButton MouseButtonOf(MouseButtonEventArgs e) =>
            e.ChangedButton == System.Windows.Input.MouseButton.Right ? TMouseButton.mbRight :
            e.ChangedButton == System.Windows.Input.MouseButton.Middle ? TMouseButton.mbMiddle : TMouseButton.mbLeft;

        /// <summary>Registers a VCL ShortCut (e.g. scCtrl + Ord('S')) on a window.</summary>
        public static void AddShortCut(Window w, int shortCut, Action action)
        {
            if (w == null || shortCut == 0 || action == null) return;
            w.PreviewKeyDown += (s, e) =>
            {
                int vk = VirtualKey(e);
                var m = Keyboard.Modifiers;
                int sc = vk;
                if ((m & ModifierKeys.Shift) != 0) sc |= scShift;
                if ((m & ModifierKeys.Control) != 0) sc |= scCtrl;
                if ((m & ModifierKeys.Alt) != 0) sc |= scAlt;
                if (sc == shortCut) { action(); e.Handled = true; }
            };
        }

        public static int ShortCut(int key, TShiftState shift)
        {
            int sc = key;
            if (shift != null)
            {
                if (shift.Contains(TShiftStateItem.ssShift)) sc |= scShift;
                if (shift.Contains(TShiftStateItem.ssCtrl)) sc |= scCtrl;
                if (shift.Contains(TShiftStateItem.ssAlt)) sc |= scAlt;
            }
            return sc;
        }

        public static string ShortCutToText(int shortCut)
        {
            if (shortCut == 0) return "";
            var sb = new StringBuilder();
            if ((shortCut & scCtrl) != 0) sb.Append("Ctrl+");
            if ((shortCut & scShift) != 0) sb.Append("Shift+");
            if ((shortCut & scAlt) != 0) sb.Append("Alt+");
            int vk = shortCut & 0xFF;
            var key = KeyInterop.KeyFromVirtualKey(vk);
            string name = key.ToString();
            if (key >= Key.D0 && key <= Key.D9) name = ((char)('0' + (key - Key.D0))).ToString();
            if (key == Key.Delete) name = "Del";
            if (key == Key.Insert) name = "Ins";
            if (key == Key.Return) name = "Enter";
            if (key == Key.Escape) name = "Esc";
            sb.Append(name);
            return sb.ToString();
        }

        /// <summary>Raises <paramref name="handler"/> whenever the selected radio button of a TRadioGroup changes.</summary>
        public static void HookRadioGroup(GroupBox g, Action handler)
        {
            foreach (var rb in RadioButtonsOf(g)) rb.Checked += (s, e) => handler();
        }

        /// <summary>Wraps a handler call so that exceptions show a message like the VCL's Application.HandleException.</summary>
        public static void Guard(Action action)
        {
            try { action(); }
            catch (EAbort) { }
            catch (Exception ex) { Application.HandleException(ex); }
        }

        /// <summary>Guard for a handler with a result: returns <paramref name="onError"/> after reporting an exception.</summary>
        public static T Guard<T>(Func<T> func, T onError)
        {
            try { return func(); }
            catch (EAbort) { return onError; }
            catch (Exception ex) { Application.HandleException(ex); return onError; }
        }
    }

    // ===================================================================== TStrings family

    /// <summary>Delphi TStrings: list of strings with optional associated objects.</summary>
    public abstract class TStrings : IEnumerable<string>
    {
        public abstract int Count { get; }
        public abstract string this[int index] { get; set; }
        public abstract void Insert(int index, string s);
        public abstract void Delete(int index);
        public abstract void Clear();

        public virtual object GetObject(int index) => null;
        public virtual void PutObject(int index, object value) { }

        public string Delimiter { get; set; } = ",";
        public char QuoteChar { get; set; } = '"';
        public string NameValueSeparator { get; set; } = "=";

        public virtual int Add(string s) { Insert(Count, s); return Count - 1; }
        public virtual int AddObject(string s, object o) { int i = Add(s); PutObject(i, o); return i; }
        public void Append(string s) => Add(s);
        public void AddStrings(TStrings other) { foreach (var s in other) Add(s); }
        public void AddStrings(IEnumerable<string> other) { foreach (var s in other) Add(s); }
        public virtual void Assign(TStrings other) { Clear(); if (other != null) for (int i = 0; i < other.Count; i++) AddObject(other[i], other.GetObject(i)); }
        public virtual int IndexOf(string s) { for (int i = 0; i < Count; i++) if (string.Equals(this[i], s, StringComparison.OrdinalIgnoreCase)) return i; return -1; }
        public int IndexOfObject(object o) { for (int i = 0; i < Count; i++) if (Equals(GetObject(i), o)) return i; return -1; }
        public void Exchange(int a, int b) { var s = this[a]; var o = GetObject(a); this[a] = this[b]; PutObject(a, GetObject(b)); this[b] = s; PutObject(b, o); }
        public void Move(int from, int to) { var s = this[from]; var o = GetObject(from); Delete(from); Insert(to, s); PutObject(to, o); }
        public void BeginUpdate() { }
        public void EndUpdate() { }
        public void Free() { }
        public string[] ToArray() => this.ToList().ToArray();

        public string GetName(int index) { var s = this[index]; int p = s.IndexOf(NameValueSeparator, StringComparison.Ordinal); return p < 0 ? "" : s.Substring(0, p); }
        public string GetValueFromIndex(int index) { var s = this[index]; int p = s.IndexOf(NameValueSeparator, StringComparison.Ordinal); return p < 0 ? "" : s.Substring(p + NameValueSeparator.Length); }
        public int IndexOfName(string name) { for (int i = 0; i < Count; i++) if (string.Equals(GetName(i), name, StringComparison.OrdinalIgnoreCase)) return i; return -1; }

        /// <summary>Values[Name] getter.</summary>
        public string GetValue(string name) { int i = IndexOfName(name); return i < 0 ? "" : GetValueFromIndex(i); }

        /// <summary>Values[Name] := Value setter (empty value deletes the entry, as in Delphi).</summary>
        public void SetValue(string name, string value)
        {
            int i = IndexOfName(name);
            if (string.IsNullOrEmpty(value)) { if (i >= 0) Delete(i); return; }
            if (i < 0) Add(name + NameValueSeparator + value); else this[i] = name + NameValueSeparator + value;
        }

        public virtual string Text
        {
            get { var sb = new StringBuilder(); for (int i = 0; i < Count; i++) sb.Append(this[i]).Append("\r\n"); return sb.ToString(); }
            set
            {
                Clear();
                if (string.IsNullOrEmpty(value)) return;
                var lines = value.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n');
                int n = lines.Length;
                if (n > 0 && lines[n - 1].Length == 0) n--;
                for (int i = 0; i < n; i++) Add(lines[i]);
            }
        }

        public string CommaText
        {
            get => string.Join(",", this.Select(s => s.IndexOfAny(new[] { ',', ' ', '"' }) >= 0 ? "\"" + s.Replace("\"", "\"\"") + "\"" : s));
            set { var d = Delimiter; Delimiter = ","; DelimitedText = value; Delimiter = d; }
        }

        public string DelimitedText
        {
            get => string.Join(Delimiter, this.Select(s => s.Contains(Delimiter) || s.Contains(" ") ? QuoteChar + s + QuoteChar : s));
            set
            {
                Clear();
                if (value == null) return;
                var sb = new StringBuilder();
                bool inQuote = false;
                char delim = string.IsNullOrEmpty(Delimiter) ? ',' : Delimiter[0];
                for (int i = 0; i < value.Length; i++)
                {
                    char c = value[i];
                    if (c == QuoteChar) { if (inQuote && i + 1 < value.Length && value[i + 1] == QuoteChar) { sb.Append(c); i++; } else inQuote = !inQuote; }
                    else if (!inQuote && (c == delim || (delim == ',' && c == ' '))) { Add(sb.ToString()); sb.Clear(); }
                    else sb.Append(c);
                }
                Add(sb.ToString());
            }
        }

        public void LoadFromFile(string fileName) => Text = File.ReadAllText(fileName, Encoding.Default);
        public void SaveToFile(string fileName) => File.WriteAllText(fileName, Text, Encoding.Default);

        public IEnumerator<string> GetEnumerator() { for (int i = 0; i < Count; i++) yield return this[i]; }
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
        public override string ToString() => Text;
    }

    public enum TDuplicates { dupIgnore, dupAccept, dupError }

    /// <summary>Delphi TStringList.</summary>
    public class TStringList : TStrings
    {
        private readonly List<string> _items = new List<string>();
        private readonly List<object> _objects = new List<object>();
        private bool _sorted;

        public TStringList() { }
        public TStringList(IEnumerable<string> items) { foreach (var s in items) Add(s); }

        public bool CaseSensitive { get; set; }
        public TDuplicates Duplicates { get; set; } = TDuplicates.dupAccept;
        public TNotifyEvent OnChange { get; set; }

        public bool Sorted
        {
            get => _sorted;
            set { _sorted = value; if (value) Sort(); }
        }

        public override int Count => _items.Count;
        public override string this[int index]
        {
            get => _items[index];
            set { _items[index] = value ?? ""; OnChange?.Invoke(this); }
        }

        public override object GetObject(int index) => _objects[index];
        public override void PutObject(int index, object value) => _objects[index] = value;

        public override int Add(string s)
        {
            s ??= "";
            if (_sorted)
            {
                int i = 0;
                var cmp = CaseSensitive ? StringComparison.Ordinal : StringComparison.OrdinalIgnoreCase;
                while (i < _items.Count && string.Compare(_items[i], s, cmp) < 0) i++;
                if (Duplicates != TDuplicates.dupAccept && i < _items.Count && string.Equals(_items[i], s, cmp))
                {
                    if (Duplicates == TDuplicates.dupError) throw new InvalidOperationException("String list does not allow duplicates");
                    return i;
                }
                Insert(i, s);
                return i;
            }
            Insert(_items.Count, s);
            return _items.Count - 1;
        }

        public override void Insert(int index, string s) { _items.Insert(index, s ?? ""); _objects.Insert(index, null); OnChange?.Invoke(this); }
        public override void Delete(int index) { _items.RemoveAt(index); _objects.RemoveAt(index); OnChange?.Invoke(this); }
        public override void Clear() { _items.Clear(); _objects.Clear(); OnChange?.Invoke(this); }

        public override int IndexOf(string s)
        {
            var cmp = CaseSensitive ? StringComparison.Ordinal : StringComparison.OrdinalIgnoreCase;
            for (int i = 0; i < _items.Count; i++) if (string.Equals(_items[i], s, cmp)) return i;
            return -1;
        }

        public bool Find(string s, out int index) { index = IndexOf(s); return index >= 0; }

        public void Sort()
        {
            var cmp = CaseSensitive ? StringComparer.Ordinal : StringComparer.OrdinalIgnoreCase;
            var pairs = _items.Zip(_objects, (s, o) => (s, o)).OrderBy(p => p.s, cmp).ToList();
            _items.Clear(); _objects.Clear();
            foreach (var p in pairs) { _items.Add(p.s); _objects.Add(p.o); }
        }

        public void CustomSort(Func<TStringList, int, int, int> compare)
        {
            var idx = Enumerable.Range(0, Count).ToList();
            idx.Sort((a, b) => compare(this, a, b));
            var s = idx.Select(i => _items[i]).ToList();
            var o = idx.Select(i => _objects[i]).ToList();
            _items.Clear(); _items.AddRange(s);
            _objects.Clear(); _objects.AddRange(o);
        }
    }

    /// <summary>TStrings view over an ItemsControl (ListBox, ComboBox...).</summary>
    public sealed class ItemsControlStrings : TStrings
    {
        private readonly ItemsControl _c;
        public ItemsControlStrings(ItemsControl c) { _c = c; }
        public override int Count => _c.Items.Count;
        public override string this[int index]
        {
            get { var o = _c.Items[index]; return o is ContentControl cc ? Convert.ToString(cc.Content, CultureInfo.CurrentCulture) : Convert.ToString(o, CultureInfo.CurrentCulture); }
            set
            {
                // VCL list boxes and combo boxes (LB_/CB_INSERTSTRING) do not raise for an index past the
                // end - the string is appended. Code such as "for i := Count to 44 do ListBox.Items[i] := ''"
                // relies on that, so behave the same instead of throwing ArgumentOutOfRangeException.
                if (index < 0) throw new ArgumentOutOfRangeException(nameof(index), $"List index out of bounds ({index})");
                if (index >= _c.Items.Count) _c.Items.Add(value ?? "");
                else _c.Items[index] = value ?? "";
            }
        }
        public override void Insert(int index, string s)
        {
            if (index < 0 || index >= _c.Items.Count) _c.Items.Add(s ?? ""); // -1 / past the end = append, as in the VCL
            else _c.Items.Insert(index, s ?? "");
        }
        public override void Delete(int index) => _c.Items.RemoveAt(index);
        public override void Clear() => _c.Items.Clear();
    }

    /// <summary>TStrings view over a TMemo (WPF TextBox): one string per line.</summary>
    public sealed class TextBoxLines : TStrings
    {
        private readonly TextBox _t;
        public TextBoxLines(TextBox t) { _t = t; }
        private List<string> Get()
        {
            var text = _t.Text ?? "";
            if (text.Length == 0) return new List<string>();
            var lines = text.Replace("\r\n", "\n").Split('\n').ToList();
            if (lines.Count > 0 && lines[lines.Count - 1].Length == 0) lines.RemoveAt(lines.Count - 1);
            return lines;
        }
        private void Put(List<string> lines) => _t.Text = lines.Count == 0 ? "" : string.Join("\r\n", lines) + "\r\n";
        public override int Count => Get().Count;
        public override string this[int index] { get => Get()[index]; set { var l = Get(); l[index] = value ?? ""; Put(l); } }
        public override void Insert(int index, string s) { var l = Get(); l.Insert(index, s ?? ""); Put(l); }
        public override void Delete(int index) { var l = Get(); l.RemoveAt(index); Put(l); }
        public override void Clear() => _t.Clear();
        public override int Add(string s)
        {
            // Fast path used by Memo1.Lines.Add: append and scroll to end.
            var text = _t.Text ?? "";
            if (text.Length > 0 && !text.EndsWith("\n")) text += "\r\n";
            _t.Text = text + (s ?? "") + "\r\n";
            _t.ScrollToEnd();
            return Count - 1;
        }
        public override string Text { get => _t.Text; set => _t.Text = value ?? ""; }
    }

    /// <summary>TStrings view over a TRadioGroup (GroupBox containing RadioButtons).</summary>
    public sealed class RadioGroupStrings : TStrings
    {
        private readonly GroupBox _g;
        public RadioGroupStrings(GroupBox g) { _g = g; }
        private Panel P => Rtl.RadioPanelOf(_g);
        public override int Count => Rtl.RadioButtonsOf(_g).Count;
        public override string this[int index]
        {
            get => Rtl.GetCaption(Rtl.RadioButtonsOf(_g)[index]);
            set => Rtl.SetCaption(Rtl.RadioButtonsOf(_g)[index], value);
        }
        public override void Insert(int index, string s)
        {
            if (P == null) _g.Content = new System.Windows.Controls.Primitives.UniformGrid { Columns = 1, Margin = new Thickness(4) };
            P.Children.Insert(index, new RadioButton { Content = Rtl.ToAccessText(s), VerticalAlignment = VerticalAlignment.Center });
        }
        public override void Delete(int index) => P?.Children.RemoveAt(index);
        public override void Clear() => P?.Children.Clear();
    }

