    /// <summary>Delphi TList / TObjectList (list of object references).</summary>
    public class TList : IEnumerable<object>
    {
        protected readonly List<object> Items = new List<object>();
        public bool OwnsObjects { get; set; }
        public TList() { }
        public TList(bool ownsObjects) { OwnsObjects = ownsObjects; }
        public int Count { get => Items.Count; set { while (Items.Count < value) Items.Add(null); if (Items.Count > value) Items.RemoveRange(value, Items.Count - value); } }
        public int Capacity { get; set; }
        public object this[int index] { get => Items[index]; set => Items[index] = value; }
        public int Add(object o) { Items.Add(o); return Items.Count - 1; }
        public void Insert(int index, object o) => Items.Insert(index, o);
        public void Delete(int index) => Items.RemoveAt(index);
        public int Remove(object o) { int i = Items.IndexOf(o); if (i >= 0) Items.RemoveAt(i); return i; }
        public object Extract(object o) { Remove(o); return o; }
        public int IndexOf(object o) => Items.IndexOf(o);
        public void Clear() => Items.Clear();
        public void Exchange(int a, int b) { var t = Items[a]; Items[a] = Items[b]; Items[b] = t; }
        public void Move(int from, int to) { var t = Items[from]; Items.RemoveAt(from); Items.Insert(to, t); }
        public object First() => Items.Count > 0 ? Items[0] : null;
        public object Last() => Items.Count > 0 ? Items[Items.Count - 1] : null;
        public void Pack() => Items.RemoveAll(o => o == null);
        public void Sort(Comparison<object> compare) => Items.Sort(compare);
        public void Free() { }
        public IEnumerator<object> GetEnumerator() => Items.GetEnumerator();
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
    }

    public class TObjectList : TList
    {
        public TObjectList() { OwnsObjects = true; }
        public TObjectList(bool ownsObjects) : base(ownsObjects) { }
    }

