    /// <summary>Delphi TextFile (AssignFile / Reset / Rewrite / ReadLn / WriteLn / CloseFile).</summary>
    public sealed class TextFile
    {
        private StreamReader _reader;
        private StreamWriter _writer;
        public string FileName { get; set; }
        public void OpenRead() { Close(); _reader = new StreamReader(FileName, Encoding.Default); }
        public void OpenWrite(bool append) { Close(); _writer = new StreamWriter(FileName, append, Encoding.Default); }
        public void Write(params object[] args) { if (_writer == null) throw new IOException("File not open for writing"); foreach (var a in args) _writer.Write(Convert.ToString(a, CultureInfo.CurrentCulture)); }
        public string ReadLine() { if (_reader == null) throw new IOException("File not open for reading"); return _reader.ReadLine() ?? ""; }
        public bool Eof => _reader == null || _reader.EndOfStream;
        public void Flush() => _writer?.Flush();
        public void Close() { _reader?.Dispose(); _reader = null; _writer?.Dispose(); _writer = null; }
    }

    /// <summary>TFileStream with Delphi open modes (fmCreate, fmOpenRead ...).</summary>
    public class TFileStream : FileStream
    {
        public TFileStream(string fileName, int mode) : base(fileName, ModeOf(mode), AccessOf(mode), FileShare.ReadWrite) { }
        private static FileMode ModeOf(int m) => (m & 0xFF00) == Rtl.fmCreate ? FileMode.Create : FileMode.Open;
        private static FileAccess AccessOf(int m) => (m & 0xFF00) == Rtl.fmCreate ? FileAccess.ReadWrite : (m & 3) == 0 ? FileAccess.Read : (m & 3) == 1 ? FileAccess.Write : FileAccess.ReadWrite;
        public long Size => Length;
        public void Free() => Dispose();
    }

    public class TMemoryStream : MemoryStream
    {
        public long Size => Length;
        public void LoadFromFile(string f) { SetLength(0); var b = File.ReadAllBytes(f); Write(b, 0, b.Length); Position = 0; }
        public void SaveToFile(string f) => File.WriteAllBytes(f, ToArray());
        public void Free() => Dispose();
    }

