    /// <summary>Forms.TApplication replacement (Rtl.Application).</summary>
    public sealed class TApplication
    {
        private string _title;

        public string Title
        {
            get => _title ?? System.Windows.Application.Current?.MainWindow?.Title ?? System.Diagnostics.Process.GetCurrentProcess().ProcessName;
            set => _title = value;
        }

        public string ExeName => Environment.ProcessPath ?? "";
