        public int HintHidePause { get; set; } = 2500;
        public bool Terminated => Rtl._shuttingDown;
        public Window MainForm => System.Windows.Application.Current?.MainWindow;
        public Action<object, Exception> OnException { get; set; }
        /// <summary>Application.OnHint (not raised automatically - WPF shows tooltips itself).</summary>
        public Action<object> OnHint { get; set; }
        public string Hint { get; set; } = "";
        /// <summary>Application.HelpContext / HelpCommand: WinHelp is not available in WPF (TODO: link your help system).</summary>
        public bool HelpContext(int context) => false;
        public bool HelpCommand(int command, int data) => false;
        public bool HelpJump(string topic) => false;

        public void Initialize() { }
        public void Run() { }
        public void CreateHandle() { }

        public void Terminate()
        {
            Rtl._shuttingDown = true;
            System.Windows.Application.Current?.Shutdown();
        }

        /// <summary>Processes pending UI messages (Application.ProcessMessages).</summary>
        public void ProcessMessages()
        {
            var frame = new DispatcherFrame();
            Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,
                new DispatcherOperationCallback(f => { ((DispatcherFrame)f).Continue = false; return null; }), frame);
            Dispatcher.PushFrame(frame);
        }

        public int MessageBox(string text, string caption, int flags = 0) => Rtl.MessageBoxApi(text, string.IsNullOrEmpty(caption) ? Title : caption, flags);

        public void Minimize() { var w = MainForm; if (w != null) w.WindowState = WindowState.Minimized; }
        public void Restore() { var w = MainForm; if (w != null) w.WindowState = WindowState.Normal; }
        public void BringToFront() => MainForm?.Activate();

        public void HandleException(Exception ex)
        {
            SmokeTest.LogException("Unhandled exception", ex);
            if (SmokeTest.Enabled) return; // unattended run: log only, no message box
            if (OnException != null) { OnException(this, ex); return; }
            System.Windows.MessageBox.Show(ex.Message, Title, MessageBoxButton.OK, MessageBoxImage.Error);
        }

        public void ShowException(Exception ex) => HandleException(ex);
    }

    /// <summary>
    /// Run log and unattended smoke test for converted applications.
    ///
    /// Every unhandled exception (normal runs too) is appended with its full stack trace to
    /// "DelphiToWpf_run.log" next to the executable, so problems can be reviewed after a run.
    ///
    /// Started with the command-line switch /smoketest the application starts as usual, then shows
    /// every auto-created form once, selects every tab page of every TabControl (running the
    /// OnChange/OnShow code behind them) and exits. Message boxes, input boxes and modal forms are
    /// answered automatically (No / Cancel) and written to the log instead of waiting for a user.
    /// </summary>
    public static class SmokeTest
    {
        /// <summary>True when the application was started with /smoketest.</summary>
        public static bool Enabled { get; private set; }

        /// <summary>Full path of the run log.</summary>
        public static string LogPath => Path.Combine(AppContext.BaseDirectory, "DelphiToWpf_run.log");

        private static int _errors;

        /// <summary>Called by App.OnStartup with the command-line arguments.</summary>
        public static void Begin(string[] args)
        {
            Enabled = args != null && args.Any(a => a.Equals("/smoketest", StringComparison.OrdinalIgnoreCase) || a.Equals("-smoketest", StringComparison.OrdinalIgnoreCase));
            if (Enabled)
            {
                try { File.WriteAllText(LogPath, ""); } catch { }
                Log("Smoke test started");
            }
        }

        public static void Log(string line)
        {
            try { File.AppendAllText(LogPath, $"[{DateTime.Now:HH:mm:ss.fff}] {line}{Environment.NewLine}"); } catch { }
        }

        public static void LogException(string context, Exception ex)
        {
            if (ex is EAbort) return;
            _errors++;
            Log($"ERROR {context}: {ex}");
        }

        /// <summary>Called by App.OnStartup after the main form is shown.</summary>
        public static void Run(Application app)
        {
            if (!Enabled) return;
            app.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle, new Action(() =>
            {
                Log("Main form shown: " + app.MainWindow?.GetType().Name);
                Step("Tab pages of " + app.MainWindow?.GetType().Name, () => CycleTabs(app.MainWindow));
                foreach (var w in app.Windows.OfType<Window>().ToList())
                {
                    if (w == app.MainWindow) continue;
                    var name = w.GetType().Name;
                    // Forms are shown here without the set-up their caller normally does first
                    // (e.g. DeviceConfig.Loop := ... before ShowModal), so a nil-reference error in
                    // OnShow can be expected rather than a conversion problem - the log says so.
                    Step("Show " + name + " (opened directly by the smoke test, without the caller's set-up)", () => { w.Show(); w.UpdateLayout(); });
                    Step("Tab pages of " + name, () => CycleTabs(w));
                    Step("Hide " + name, () => w.Hide());
                }
                Log($"Smoke test finished: {_errors} error(s)");
                try { app.Shutdown(_errors); } catch { }
            }));
        }

        private static void Step(string what, Action a)
        {
            Log(what);
            try { a(); }
            catch (Exception ex) { LogException(what, ex); }
        }

        private static void CycleTabs(DependencyObject root)
        {
            if (root == null) return;
            var tabs = new List<TabControl>();
            Collect(root, tabs);
            foreach (var tc in tabs)
            {
                int original = tc.SelectedIndex;
                for (int i = 0; i < tc.Items.Count; i++)
                {
                    int index = i;
                    string page = tc.Items[index] is TabItem ti ? Convert.ToString(ti.Header, CultureInfo.CurrentCulture) : index.ToString(CultureInfo.InvariantCulture);
                    Step($"  {tc.Name} -> {page}", () => { tc.SelectedIndex = index; tc.UpdateLayout(); });
                }
                Step($"  {tc.Name} -> back to {original}", () => tc.SelectedIndex = original);
            }
        }

        private static void Collect(DependencyObject d, List<TabControl> tabs)
        {
            if (d is TabControl tc) tabs.Add(tc);
            foreach (var child in LogicalTreeHelper.GetChildren(d).OfType<DependencyObject>()) Collect(child, tabs);
        }
    }

    /// <summary>Forms.TScreen replacement (Rtl.Screen).</summary>
    public sealed class TScreen
    {
        /// <summary>Screen.Cursor := crHourGlass etc.</summary>
        public int Cursor
        {
            get => _cursor;
            set
            {
                _cursor = value;
                Mouse.OverrideCursor = value == Rtl.crDefault ? null : TScreen.ToCursor(value);
            }
        }
        private int _cursor;

        public int Width => (int)SystemParameters.PrimaryScreenWidth;
        public int Height => (int)SystemParameters.PrimaryScreenHeight;
        public int WorkAreaWidth => (int)SystemParameters.WorkArea.Width;
        public int WorkAreaHeight => (int)SystemParameters.WorkArea.Height;
        public int PixelsPerInch => 96;
        public Window ActiveForm => System.Windows.Application.Current?.Windows.OfType<Window>().FirstOrDefault(w => w.IsActive);
        public int FormCount => System.Windows.Application.Current?.Windows.Count ?? 0;

        public static Cursor ToCursor(int c)
        {
            switch (c)
            {
                case Rtl.crArrow: return Cursors.Arrow;
                case Rtl.crCross: return Cursors.Cross;
                case Rtl.crIBeam: return Cursors.IBeam;
                case Rtl.crSizeNESW: return Cursors.SizeNESW;
                case Rtl.crSizeNS: case Rtl.crVSplit: return Cursors.SizeNS;
                case Rtl.crSizeNWSE: return Cursors.SizeNWSE;
                case Rtl.crSizeWE: case Rtl.crHSplit: return Cursors.SizeWE;
                case Rtl.crUpArrow: return Cursors.UpArrow;
                case Rtl.crHourGlass: case Rtl.crSQLWait: return Cursors.Wait;
                case Rtl.crAppStart: return Cursors.AppStarting;
                case Rtl.crNo: case Rtl.crNoDrop: return Cursors.No;
                case Rtl.crHelp: return Cursors.Help;
                case Rtl.crHandPoint: return Cursors.Hand;
                case Rtl.crSizeAll: return Cursors.SizeAll;
                case Rtl.crNone: return Cursors.None;
                default: return null;
            }
        }
    }

