    /// <summary>ExtCtrls.TTimer on top of DispatcherTimer (runs on the UI thread like the VCL timer).</summary>
    public sealed class TTimer
    {
        private readonly DispatcherTimer _timer = new DispatcherTimer();
        private bool _enabled = true;
        private int _interval = 1000;

        public TTimer() { _timer.Tick += (s, e) => { if (OnTimer != null) Rtl.Guard(() => OnTimer(this)); }; }
        public TTimer(object owner) : this() { }

        /// <summary>OnTimer handler (procedure(Sender: TObject) of object).</summary>
        public Action<object> OnTimer { get; set; }
        public string Name { get; set; }
        public int Tag { get; set; }

        public bool Enabled { get => _enabled; set { _enabled = value; Update(); } }
        public int Interval { get => _interval; set { _interval = value; Update(); } }

        /// <summary>Call once the form is constructed (the converter does this) so a timer enabled at design time starts.</summary>
        public void Start() => Update(true);

        private bool _started;
        private void Update(bool start = false)
        {
            if (start) _started = true;
            _timer.Stop();
            if (_started && _enabled && _interval > 0)
            {
                _timer.Interval = TimeSpan.FromMilliseconds(_interval);
                _timer.Start();
            }
        }

        public void Free() { _enabled = false; _timer.Stop(); }
    }

    public sealed class TOpenDialog
    {
        public TOpenDialog() { }
        public TOpenDialog(object owner) { }
        public string FileName { get; set; } = "";
        public string Filter { get; set; } = "";
        public int FilterIndex { get; set; } = 1;
        public string InitialDir { get; set; } = "";
        public string Title { get; set; } = "";
        public string DefaultExt { get; set; } = "";
        public bool MultiSelect { get; set; }
        public TStrings Files { get; } = new TStringList();
        public string Name { get; set; }

        public bool Execute()
        {
            var d = new Microsoft.Win32.OpenFileDialog
            {
                FileName = FileName ?? "", Filter = Filter ?? "", FilterIndex = Math.Max(1, FilterIndex),
                InitialDirectory = InitialDir ?? "", Title = Title ?? "", DefaultExt = DefaultExt ?? "", Multiselect = MultiSelect
            };
            if (d.ShowDialog() != true) return false;
            FileName = d.FileName;
            FilterIndex = d.FilterIndex;
            Files.Clear();
            foreach (var f in d.FileNames) Files.Add(f);
            return true;
        }

        public void Free() { }
    }

    public sealed class TSaveDialog
    {
        public TSaveDialog() { }
        public TSaveDialog(object owner) { }
        public string FileName { get; set; } = "";
        public string Filter { get; set; } = "";
        public int FilterIndex { get; set; } = 1;
        public string InitialDir { get; set; } = "";
        public string Title { get; set; } = "";
        public string DefaultExt { get; set; } = "";
        public bool OverwritePrompt { get; set; } = true;
        public string Name { get; set; }

        public bool Execute()
        {
            var d = new Microsoft.Win32.SaveFileDialog
            {
                FileName = FileName ?? "", Filter = Filter ?? "", FilterIndex = Math.Max(1, FilterIndex),
                InitialDirectory = InitialDir ?? "", Title = Title ?? "", DefaultExt = DefaultExt ?? "", OverwritePrompt = OverwritePrompt
            };
            if (d.ShowDialog() != true) return false;
            FileName = d.FileName;
            FilterIndex = d.FilterIndex;
            return true;
        }

        public void Free() { }
    }

    /// <summary>TColorDialog: WPF has no colour dialog; this shows a simple palette picker.</summary>
    public sealed class TColorDialog
    {
        public TColorDialog() { }
        public TColorDialog(object owner) { }
        public int Color { get; set; } = Rtl.clBlack;
        public string Name { get; set; }

        public bool Execute()
        {
            int[] palette = { Rtl.clBlack, Rtl.clMaroon, Rtl.clGreen, Rtl.clOlive, Rtl.clNavy, Rtl.clPurple, Rtl.clTeal, Rtl.clGray,
                              Rtl.clSilver, Rtl.clRed, Rtl.clLime, Rtl.clYellow, Rtl.clBlue, Rtl.clFuchsia, Rtl.clAqua, Rtl.clWhite };
            var w = new Window { Title = "Colour", SizeToContent = SizeToContent.WidthAndHeight, ResizeMode = ResizeMode.NoResize, WindowStartupLocation = WindowStartupLocation.CenterScreen };
            var grid = new UniformGrid { Columns = 8, Margin = new Thickness(8) };
            int chosen = Color;
            bool ok = false;
            foreach (var c in palette)
            {
                var b = new Button { Width = 28, Height = 28, Margin = new Thickness(2), Background = Rtl.ToBrush(c) };
                int cc = c;
                b.Click += (s, e) => { chosen = cc; ok = true; w.Close(); };
                grid.Children.Add(b);
            }
            w.Content = grid;
            w.ShowDialog();
            if (ok) Color = chosen;
            return ok;
        }

        public void Free() { }
    }

