    /// <summary>TImageList placeholder (images are not converted).</summary>
    public sealed class TImageList
    {
        private readonly List<BitmapSource> _images = new List<BitmapSource>();
        private string _resourcePath;

        public TImageList() { }
        public TImageList(object owner) { }
        public string Name { get; set; }
        public int Width { get; set; } = 16;
        public int Height { get; set; } = 16;
        public int Count => _images.Count;

        /// <summary>
        /// Images from the form file: the converter copies the TImageList "Bitmap" data (an ImageList_Write
        /// stream - "IL" header, image bitmap, mask bitmap) to this project resource; it is split here.
        /// </summary>
        public string ResourcePath
        {
            get => _resourcePath;
            set
            {
                _resourcePath = value;
                _images.Clear();
                if (string.IsNullOrEmpty(value)) return;
                try
                {
                    var info = Application.GetResourceStream(new Uri(value, UriKind.Relative));
                    if (info == null) return;
                    using (var ms = new MemoryStream())
                    {
                        info.Stream.CopyTo(ms);
                        _images.AddRange(ImageListStream.Read(ms.ToArray(), Width, Height));
                    }
                }
                catch (Exception ex) { SmokeTest.Log($"TImageList {Name}: images could not be read ({ex.Message})"); }
            }
        }

        /// <summary>Image <paramref name="index"/> (null when out of range).</summary>
        public BitmapSource GetImage(int index) => index >= 0 && index < _images.Count ? _images[index] : null;

        /// <summary>ImageList.GetBitmap(Index, Bitmap): copies the image into the TBitmap.</summary>
        public void GetBitmap(int index, TBitmap bitmap)
        {
            var img = GetImage(index);
            if (img != null && bitmap != null) bitmap.Source = img;
        }

        public void GetIcon(int index, object icon) { }

        public int Add(object image, object mask)
        {
            var src = TBitmap.SourceOf(image) as BitmapSource;
            if (src == null) return -1;
            _images.Add(src);
            return _images.Count - 1;
        }

        public void Delete(int index) { if (index >= 0 && index < _images.Count) _images.RemoveAt(index); }
        public void Clear() => _images.Clear();
        public void Free() { }

        /// <summary>Draw(Canvas, X, Y, Index): draws the image on a TCanvas.</summary>
        public void Draw(TCanvas canvas, int x, int y, int index, bool enabled = true)
        {
            var img = GetImage(index);
            if (img != null && canvas != null) canvas.Draw(x, y, img);
        }
    }

    /// <summary>
    /// Reader for the comctl32 ImageList_Write stream that Delphi stores as TImageList.Bitmap:
    /// a 28-byte ILHEAD ("IL", version, count, max, grow, cx, cy, bkcolor, flags, overlays), the image
    /// bitmap (images in rows of 4) and, with ILC_MASK, a monochrome mask bitmap (white = transparent).
    /// </summary>
    internal static class ImageListStream
    {
        public static List<BitmapSource> Read(byte[] data, int defWidth, int defHeight)
        {
            var result = new List<BitmapSource>();
            int pos = 0;
            int count, cx, cy, flags;
            if (data.Length > 28 && data[0] == (byte)'I' && data[1] == (byte)'L')
            {
                count = BitConverter.ToUInt16(data, 4);
                cx = BitConverter.ToUInt16(data, 10);
                cy = BitConverter.ToUInt16(data, 12);
                flags = BitConverter.ToUInt16(data, 18);
                pos = 28;
            }
            else return result;

            var image = ReadBmp(data, ref pos, out int iw, out int ih);
            if (image == null || cx <= 0 || cy <= 0) return result;
            uint[] mask = null; int mw = 0, mh = 0;
            if ((flags & 1) != 0 && pos + 14 < data.Length && data[pos] == (byte)'B' && data[pos + 1] == (byte)'M')
                mask = ReadBmp(data, ref pos, out mw, out mh);

            // Are there real alpha values? (32-bit DDB lists often store 0 in every alpha byte.)
            bool hasAlpha = false;
            foreach (var px in image) if ((px >> 24) != 0) { hasAlpha = true; break; }

            int perRow = Math.Max(1, iw / cx);
            for (int n = 0; n < count; n++)
            {
                int ox = (n % perRow) * cx, oy = (n / perRow) * cy;
                if (ox + cx > iw || oy + cy > ih) break;
                var pixels = new uint[cx * cy];
                for (int y = 0; y < cy; y++)
                    for (int x = 0; x < cx; x++)
                    {
                        uint p = image[(oy + y) * iw + ox + x];
                        bool transparent = mask != null && ox + x < mw && oy + y < mh && (mask[(oy + y) * mw + ox + x] & 0x00FFFFFF) != 0;
                        uint a = transparent ? 0u : hasAlpha ? (p >> 24) : 255u;
                        pixels[y * cx + x] = (a << 24) | (p & 0x00FFFFFF);
                    }
                var bmp = BitmapSource.Create(cx, cy, 96, 96, PixelFormats.Bgra32, null, pixels, cx * 4);
                bmp.Freeze();
                result.Add(bmp);
            }
            return result;
        }

        /// <summary>Decodes an uncompressed BMP (1/4/8/24/32 bpp) to top-down 0xAARRGGBB pixels.</summary>
        private static uint[] ReadBmp(byte[] d, ref int pos, out int w, out int h)
        {
            w = h = 0;
            if (pos + 54 > d.Length || d[pos] != (byte)'B' || d[pos + 1] != (byte)'M') return null;
            int hdr = pos + 14;
            int infoSize = BitConverter.ToInt32(d, hdr);
            w = BitConverter.ToInt32(d, hdr + 4);
            int rawH = BitConverter.ToInt32(d, hdr + 8);
            bool topDown = rawH < 0;
            h = Math.Abs(rawH);
            int bpp = BitConverter.ToUInt16(d, hdr + 14);
            int compression = BitConverter.ToInt32(d, hdr + 16);
            int clrUsed = BitConverter.ToInt32(d, hdr + 32);
            if (compression != 0 && compression != 3) return null;
            int palCount = bpp <= 8 ? (clrUsed > 0 ? clrUsed : 1 << bpp) : 0;
            int palPos = hdr + infoSize + (compression == 3 && infoSize == 40 ? 12 : 0);
            var palette = new uint[palCount];
            for (int i = 0; i < palCount; i++) palette[i] = BitConverter.ToUInt32(d, palPos + i * 4) & 0x00FFFFFF;
            int bits = palPos + palCount * 4;
            int stride = ((w * bpp + 31) / 32) * 4;
            var px = new uint[w * h];
            for (int y = 0; y < h; y++)
            {
                int row = bits + (topDown ? y : h - 1 - y) * stride;
                for (int x = 0; x < w; x++)
                {
                    uint v;
                    switch (bpp)
                    {
                        case 1: v = palette[(d[row + x / 8] >> (7 - x % 8)) & 1]; break;
                        case 4: v = palette[(d[row + x / 2] >> (x % 2 == 0 ? 4 : 0)) & 0x0F]; break;
                        case 8: v = palette[d[row + x]]; break;
                        case 24: v = (uint)(d[row + x * 3] | d[row + x * 3 + 1] << 8 | d[row + x * 3 + 2] << 16); break;
                        case 32: v = BitConverter.ToUInt32(d, row + x * 4); break;
                        default: return null;
                    }
                    px[y * w + x] = v;
                }
            }
            pos = bits + stride * h;
            return px;
        }
    }

    /// <summary>ActnList.TAction.</summary>
    public sealed class TAction
    {
        public TAction() { }
        public TAction(object owner) { }
        public string Name { get; set; }
        public string Caption { get; set; } = "";
        public string Hint { get; set; } = "";
        public string Category { get; set; } = "";
        public bool Enabled { get; set; } = true;
        public bool Checked { get; set; }
        public bool Visible { get; set; } = true;
        public int ShortCut { get; set; }
        public int ImageIndex { get; set; } = -1;
        public int Tag { get; set; }
        public Action<object> OnExecute { get; set; }
        public Action<object> OnUpdate { get; set; }

        public bool Execute()
        {
            if (!Enabled) return false;
            if (OnExecute != null) Rtl.Guard(() => OnExecute(this));
            return OnExecute != null;
        }

        /// <summary>Connects a control to this action (Control.Action := Action1).</summary>
        public void Attach(FrameworkElement c)
        {
            if (c is ButtonBase b) b.Click += (s, e) => Execute();
            else if (c is MenuItem m) m.Click += (s, e) => Execute();
            c.IsEnabled = Enabled;
            if (!string.IsNullOrEmpty(Caption) && string.IsNullOrEmpty(Rtl.GetCaption(c))) Rtl.SetCaption(c, Caption);
        }

        public void Free() { }
    }

    /// <summary>TFont view over a WPF control: writes Name/Size/Style/Color straight to the control.</summary>
    public sealed class TFont
    {
        private readonly DependencyObject _c;
        public TFont(DependencyObject c) { _c = c; }
        /// <summary>A free-standing font (TFont.Create, Canvas.Font): values are kept in a private TextBlock.</summary>
        public TFont() { _c = new TextBlock { FontFamily = new FontFamily("Segoe UI"), FontSize = 8 * 96.0 / 72.0 }; }
        public TFont(object owner) : this() { }
        /// <summary>Raised by Delphi code when the font changes (kept for compatibility, not raised automatically).</summary>
        public Action<object> OnChange { get; set; }
        public int PixelsPerInch { get; set; } = 96;
        public int Charset { get; set; } = 1;
        public TFontPitch Pitch { get; set; }
        public void Free() { }

        public string Name
        {
            get => (_c?.GetValue(System.Windows.Documents.TextElement.FontFamilyProperty) as FontFamily)?.Source ?? "";
            set => _c?.SetValue(System.Windows.Documents.TextElement.FontFamilyProperty, new FontFamily(value));
        }

        /// <summary>Size in points (Delphi) - WPF uses device-independent pixels (1/96 inch).</summary>
        public int Size
        {
            get => _c == null ? 0 : (int)Math.Round((double)_c.GetValue(System.Windows.Documents.TextElement.FontSizeProperty) * 72.0 / 96.0);
            set => _c?.SetValue(System.Windows.Documents.TextElement.FontSizeProperty, value * 96.0 / 72.0);
        }

        /// <summary>Height in pixels (negative = character height, as in Delphi).</summary>
        public int Height
        {
            get => _c == null ? 0 : -(int)Math.Round((double)_c.GetValue(System.Windows.Documents.TextElement.FontSizeProperty));
            set => _c?.SetValue(System.Windows.Documents.TextElement.FontSizeProperty, (double)Math.Abs(value));
        }

        public int Color
        {
            get => Rtl.FromBrush(_c?.GetValue(System.Windows.Documents.TextElement.ForegroundProperty) as Brush);
            set => _c?.SetValue(System.Windows.Documents.TextElement.ForegroundProperty, Rtl.ToBrush(value));
        }

        public HashSet<TFontStyle> Style
        {
            get
            {
                var s = new HashSet<TFontStyle>();
                if (_c == null) return s;
                if ((FontWeight)_c.GetValue(System.Windows.Documents.TextElement.FontWeightProperty) >= FontWeights.Bold) s.Add(TFontStyle.fsBold);
                if ((FontStyle)_c.GetValue(System.Windows.Documents.TextElement.FontStyleProperty) == FontStyles.Italic) s.Add(TFontStyle.fsItalic);
                if (_c is TextBlock tb && tb.TextDecorations != null)
                {
                    if (tb.TextDecorations.Any(d => d.Location == TextDecorationLocation.Underline)) s.Add(TFontStyle.fsUnderline);
                    if (tb.TextDecorations.Any(d => d.Location == TextDecorationLocation.Strikethrough)) s.Add(TFontStyle.fsStrikeOut);
                }
                return s;
            }
            set
            {
                if (_c == null) return;
                value ??= new HashSet<TFontStyle>();
                _c.SetValue(System.Windows.Documents.TextElement.FontWeightProperty, value.Contains(TFontStyle.fsBold) ? FontWeights.Bold : FontWeights.Normal);
                _c.SetValue(System.Windows.Documents.TextElement.FontStyleProperty, value.Contains(TFontStyle.fsItalic) ? FontStyles.Italic : FontStyles.Normal);
                if (_c is TextBlock tb)
                {
                    var deco = new TextDecorationCollection();
                    if (value.Contains(TFontStyle.fsUnderline)) deco.Add(TextDecorations.Underline);
                    if (value.Contains(TFontStyle.fsStrikeOut)) deco.Add(TextDecorations.Strikethrough);
                    tb.TextDecorations = deco;
                }
            }
        }

        public void Assign(TFont other)
        {
            if (other == null) return;
            Name = other.Name; Size = other.Size; Color = other.Color; Style = other.Style;
            OnChange?.Invoke(this);
        }

        public void Assign(TFontData other)
        {
            if (other == null) return;
            Name = other.Name; Size = other.Size; Color = other.Color; Style = other.Style;
        }
    }

    // ===================================================================== IniFiles

    /// <summary>IniFiles.TIniFile replacement (reads/writes a classic .ini file).</summary>
    public class TIniFile
    {
        private readonly List<(string Section, List<KeyValuePair<string, string>> Values)> _sections = new List<(string, List<KeyValuePair<string, string>>)>();
        public string FileName { get; }

        public TIniFile(string fileName)
        {
            // Delphi resolves a bare file name against the Windows directory; we use the exe folder instead.
            FileName = Path.IsPathRooted(fileName) ? fileName : Path.Combine(AppContext.BaseDirectory, fileName);
            if (File.Exists(FileName)) Load();
        }

        private void Load()
        {
            List<KeyValuePair<string, string>> cur = null;
            foreach (var raw in File.ReadAllLines(FileName, Encoding.Default))
            {
                var line = raw.Trim();
                if (line.Length == 0 || line.StartsWith(";")) continue;
                if (line.StartsWith("[") && line.EndsWith("]"))
                {
                    cur = new List<KeyValuePair<string, string>>();
                    _sections.Add((line.Substring(1, line.Length - 2), cur));
                    continue;
                }
                if (cur == null) continue;
                int eq = line.IndexOf('=');
                if (eq < 0) cur.Add(new KeyValuePair<string, string>(line, ""));
                else cur.Add(new KeyValuePair<string, string>(line.Substring(0, eq).Trim(), line.Substring(eq + 1)));
            }
        }

        private List<KeyValuePair<string, string>> Section(string name, bool create)
        {
            foreach (var s in _sections) if (string.Equals(s.Section, name, StringComparison.OrdinalIgnoreCase)) return s.Values;
            if (!create) return null;
            var l = new List<KeyValuePair<string, string>>();
            _sections.Add((name, l));
            return l;
        }

        public string ReadString(string section, string ident, string def)
        {
            var s = Section(section, false);
            if (s == null) return def;
            foreach (var kv in s) if (string.Equals(kv.Key, ident, StringComparison.OrdinalIgnoreCase)) return kv.Value;
            return def;
        }

        public void WriteString(string section, string ident, string value)
        {
            var s = Section(section, true);
            for (int i = 0; i < s.Count; i++)
                if (string.Equals(s[i].Key, ident, StringComparison.OrdinalIgnoreCase)) { s[i] = new KeyValuePair<string, string>(s[i].Key, value ?? ""); Save(); return; }
            s.Add(new KeyValuePair<string, string>(ident, value ?? ""));
            Save();
        }

        public int ReadInteger(string section, string ident, int def) => Rtl.StrToIntDef(ReadString(section, ident, ""), def);
        public void WriteInteger(string section, string ident, int value) => WriteString(section, ident, value.ToString(CultureInfo.InvariantCulture));
        public bool ReadBool(string section, string ident, bool def) { var s = ReadString(section, ident, ""); return s == "" ? def : s != "0"; }
        public void WriteBool(string section, string ident, bool value) => WriteString(section, ident, value ? "1" : "0");
        public double ReadFloat(string section, string ident, double def) => Rtl.StrToFloatDef(ReadString(section, ident, ""), def);
        public void WriteFloat(string section, string ident, double value) => WriteString(section, ident, Rtl.FloatToStr(value));
        public double ReadDateTime(string section, string ident, double def) => Rtl.StrToDateDef(ReadString(section, ident, ""), def);
        public void WriteDateTime(string section, string ident, double value) => WriteString(section, ident, Rtl.DateTimeToStr(value));
        public bool SectionExists(string section) => Section(section, false) != null;
        public bool ValueExists(string section, string ident) => Section(section, false)?.Any(kv => string.Equals(kv.Key, ident, StringComparison.OrdinalIgnoreCase)) == true;

        public void ReadSection(string section, TStrings strings)
        {
            strings.Clear();
            var s = Section(section, false);
            if (s != null) foreach (var kv in s) strings.Add(kv.Key);
        }

        public void ReadSections(TStrings strings)
        {
            strings.Clear();
            foreach (var s in _sections) strings.Add(s.Section);
        }

        public void ReadSectionValues(string section, TStrings strings)
        {
            strings.Clear();
            var s = Section(section, false);
            if (s != null) foreach (var kv in s) strings.Add(kv.Key + "=" + kv.Value);
        }

        public void EraseSection(string section)
        {
            _sections.RemoveAll(s => string.Equals(s.Section, section, StringComparison.OrdinalIgnoreCase));
            Save();
        }

        public void DeleteKey(string section, string ident)
        {
            Section(section, false)?.RemoveAll(kv => string.Equals(kv.Key, ident, StringComparison.OrdinalIgnoreCase));
            Save();
        }

        public void UpdateFile() => Save();

        private void Save()
        {
            var sb = new StringBuilder();
            foreach (var s in _sections)
            {
                sb.Append('[').Append(s.Section).Append("]\r\n");
                foreach (var kv in s.Values) sb.Append(kv.Key).Append('=').Append(kv.Value).Append("\r\n");
                sb.Append("\r\n");
            }
            var dir = Path.GetDirectoryName(FileName);
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            File.WriteAllText(FileName, sb.ToString(), Encoding.Default);
        }

        public void Free() { }
    }

