    /// <summary>
    /// TStringGrid emulation on a WPF DataGrid: Rtl.Grid(StringGrid1).Cells[Col, Row].
    /// Row 0 / column 0 behave as ordinary cells (fixed rows/cols are not rendered differently).
    /// </summary>
    public sealed class TStringGridModel
    {
        private static readonly ConditionalWeakTable<DataGrid, TStringGridModel> _models = new ConditionalWeakTable<DataGrid, TStringGridModel>();
        private readonly DataGrid _grid;
        private readonly DataTable _table = new DataTable();

        public static TStringGridModel For(DataGrid g) => g == null ? new TStringGridModel(null) : _models.GetValue(g, x => new TStringGridModel(x));

        private TStringGridModel(DataGrid g)
        {
            _grid = g;
            if (g != null)
            {
                int cols = g.Tag is string t && t.StartsWith("grid:") ? int.Parse(t.Split(':')[1], CultureInfo.InvariantCulture) : 5;
                int rows = g.Tag is string t2 && t2.StartsWith("grid:") ? int.Parse(t2.Split(':')[2], CultureInfo.InvariantCulture) : 5;
                g.AutoGenerateColumns = true;
                g.CanUserAddRows = false;
                g.HeadersVisibility = DataGridHeadersVisibility.None;
                ColCount = cols;
                RowCount = rows;
                g.ItemsSource = _table.DefaultView;
            }
        }

        public CellAccessor Cells => new CellAccessor(this);

        public sealed class CellAccessor
        {
            private readonly TStringGridModel _m;
            internal CellAccessor(TStringGridModel m) { _m = m; }
            public string this[int col, int row]
            {
                get => col >= 0 && row >= 0 && col < _m._table.Columns.Count && row < _m._table.Rows.Count ? Convert.ToString(_m._table.Rows[row][col], CultureInfo.CurrentCulture) : "";
                set
                {
                    if (col >= _m.ColCount) _m.ColCount = col + 1;
                    if (row >= _m.RowCount) _m.RowCount = row + 1;
                    _m._table.Rows[row][col] = value ?? "";
                }
            }
        }

        public int ColCount
        {
            get => _table.Columns.Count;
            set
            {
                while (_table.Columns.Count < value) _table.Columns.Add("C" + _table.Columns.Count, typeof(string));
                while (_table.Columns.Count > value && value >= 0) _table.Columns.RemoveAt(_table.Columns.Count - 1);
                Refresh();
            }
        }

        public int RowCount
        {
            get => _table.Rows.Count;
            set
            {
                while (_table.Rows.Count < value) _table.Rows.Add(_table.NewRow());
                while (_table.Rows.Count > value && value >= 0) _table.Rows.RemoveAt(_table.Rows.Count - 1);
            }
        }

        private int _fixedRows = 1, _fixedCols = 1;
        /// <summary>Fixed (grey, non-scrolling header) rows - drawn in the button-face colour as in the VCL.</summary>
        public int FixedRows { get => _fixedRows; set { _fixedRows = value; RefreshFixedStyle(); } }
        /// <summary>Fixed (grey) columns on the left.</summary>
        public int FixedCols { get => _fixedCols; set { _fixedCols = value; RefreshFixedStyle(); } }

        private readonly Dictionary<int, int> _colWidths = new Dictionary<int, int>();

        /// <summary>Grid.ColWidths[i] (the form file stores them as ColWidths = (46 93 ...)).</summary>
        public SizeAccessor ColWidths => new SizeAccessor(
            i => _colWidths.TryGetValue(i, out var w) ? w : DefaultColWidth,
            (i, w) => { _colWidths[i] = w; ApplyColumnWidths(); });

        /// <summary>Indexed Grid.ColWidths[i] / RowHeights[i].</summary>
        public sealed class SizeAccessor
        {
            private readonly Func<int, int> _get; private readonly Action<int, int> _set;
            internal SizeAccessor(Func<int, int> get, Action<int, int> set) { _get = get; _set = set; }
            public int this[int index] { get => _get(index); set => _set(index, value); }
        }

        /// <summary>Sets every column width at once (used for the form-file ColWidths list).</summary>
        public void SetColWidths(params int[] widths)
        {
            for (int i = 0; i < widths.Length; i++) _colWidths[i] = widths[i];
            ApplyColumnWidths();
        }

        private void ApplyColumnWidths()
        {
            if (_grid == null) return;
            foreach (var c in _grid.Columns)
            {
                int i = c.DisplayIndex >= 0 ? c.DisplayIndex : _grid.Columns.IndexOf(c);
                c.Width = new DataGridLength(_colWidths.TryGetValue(i, out var w) ? w : _colWidth);
            }
        }

        /// <summary>Fixed rows and columns get the VCL clBtnFace background.</summary>
        private void RefreshFixedStyle()
        {
            if (_grid == null) return;
            if (!_fixedHooked)
            {
                _fixedHooked = true;
                _grid.LoadingRow += (s, e) => StyleRow(e.Row);
                // VCL: fixed rows/columns (headers) cannot become the current cell - a click there changes nothing.
                _grid.PreviewMouseLeftButtonDown += (s, e) =>
                {
                    var hit = e.OriginalSource as DependencyObject;
                    while (hit != null && !(hit is DataGridCell) && !(hit is DataGridRowHeader)) hit = VisualTreeHelper.GetParent(hit) ?? LogicalTreeHelper.GetParent(hit);
                    if (hit is DataGridCell cell)
                    {
                        var row = DataGridRow.GetRowContainingElement(cell);
                        int r = row?.GetIndex() ?? -1, c = cell.Column?.DisplayIndex ?? -1;
                        if ((r >= 0 && r < _fixedRows) || (c >= 0 && c < _fixedCols)) e.Handled = true;
                    }
                };
                // Keyboard: moving onto a fixed row/column puts the current cell back where it was.
                int goodRow = -1, goodCol = -1;
                _grid.SelectedCellsChanged += (s, e) =>
                {
                    if (Rtl.EventsSuppressed(_grid)) return;
                    int r = CurrentRowIndex(), c = Col;
                    if (r < 0) return;
                    if (r < _fixedRows || c < _fixedCols)
                    {
                        if (goodRow >= 0) Rtl.WithoutEvents(_grid, () => Select(goodRow, goodCol));
                    }
                    else { goodRow = r; goodCol = c; }
                };
                _grid.AutoGeneratedColumns += (s, e) => { ApplyColumnWidths(); StyleFixedColumns(); };
            }
            foreach (var row in Rtl.Descendants<DataGridRow>(_grid)) StyleRow(row);
            StyleFixedColumns();
        }
        private bool _fixedHooked;

        private void StyleRow(DataGridRow row)
        {
            bool isFixed = row.GetIndex() < _fixedRows;
            if (isFixed) row.SetResourceReference(Control.BackgroundProperty, SystemColors.ControlBrushKey);
            else row.ClearValue(Control.BackgroundProperty);
        }

        private void StyleFixedColumns()
        {
            if (_grid == null || OwnerDraw != null) return;
            for (int i = 0; i < _grid.Columns.Count; i++)
            {
                if (i < _fixedCols)
                {
                    var st = new Style(typeof(DataGridCell));
                    st.Setters.Add(new Setter(Control.BackgroundProperty, new DynamicResourceExtension(SystemColors.ControlBrushKey)));
                    _grid.Columns[i].CellStyle = st;
                }
                else _grid.Columns[i].CellStyle = null;
            }
        }

        /// <summary>OnDrawCell handler (set by Rtl.OwnerDrawGrid): the grid shows owner-drawn cells.</summary>
        internal Action<int, int, TRect, HashSet<TGridDrawStateItem>> OwnerDraw;
        internal DataGrid GridControl => _grid;

        /// <summary>Owner-drawn grid: one template column per Delphi column, each cell is a DrawGridCell.</summary>
        internal void RebuildColumns()
        {
            if (_grid == null || OwnerDraw == null) return;
            int row = CurrentRowIndex(), col = Col;
            Rtl.WithoutEvents(_grid, () =>
            {
                _grid.AutoGenerateColumns = false;
                _grid.Columns.Clear();
                for (int i = 0; i < ColCount; i++)
                {
                    var factory = new FrameworkElementFactory(typeof(DrawGridCell));
                    factory.SetValue(DrawGridCell.ColumnProperty, i);
                    _grid.Columns.Add(new DataGridTemplateColumn
                    {
                        CellTemplate = new DataTemplate { VisualTree = factory },
                        Width = new DataGridLength(_colWidth)
                    });
                }
                _grid.ItemsSource = null;
                _grid.ItemsSource = _table.DefaultView;
                ApplyColumnWidths();
                if (row >= 0) Select(row, col);
            });
        }

        private HashSet<TGridOption> _options = new HashSet<TGridOption> { TGridOption.goFixedVertLine, TGridOption.goFixedHorzLine, TGridOption.goVertLine, TGridOption.goHorzLine, TGridOption.goRangeSelect };
        /// <summary>Grid.Options: goEditing controls whether cells can be edited, goRowSelect selects whole rows.</summary>
        public HashSet<TGridOption> Options
        {
            get => new HashSet<TGridOption>(_options);
            set
            {
                _options = value ?? new HashSet<TGridOption>();
                if (_grid == null) return;
                _grid.IsReadOnly = !_options.Contains(TGridOption.goEditing);
                var unit = _options.Contains(TGridOption.goRowSelect) ? DataGridSelectionUnit.FullRow : DataGridSelectionUnit.Cell;
                if (_grid.SelectionUnit != unit)
                {
                    // Changing SelectionUnit clears the selection in WPF; keep the current row and raise no OnClick.
                    int row = CurrentRowIndex(), col = Col;
                    Rtl.WithoutEvents(_grid, () =>
                    {
                        _grid.SelectionUnit = unit;
                        if (row >= 0) Select(row, col);
                    });
                }
                _grid.GridLinesVisibility = _options.Contains(TGridOption.goVertLine) && _options.Contains(TGridOption.goHorzLine) ? DataGridGridLinesVisibility.All
                                          : _options.Contains(TGridOption.goVertLine) ? DataGridGridLinesVisibility.Vertical
                                          : _options.Contains(TGridOption.goHorzLine) ? DataGridGridLinesVisibility.Horizontal : DataGridGridLinesVisibility.None;
            }
        }

        private int _colWidth = 64;
        public int DefaultColWidth
        {
            get => _colWidth;
            set
            {
                _colWidth = value;
                if (_grid == null) return;
                _grid.ColumnWidth = new DataGridLength(value);
                foreach (var c in _grid.Columns) c.Width = new DataGridLength(value);
            }
        }

        /// <summary>
        /// Smallest row that shows the grid's font without clipping: Delphi row heights were chosen for MS Sans Serif,
        /// and Segoe UI (used by the Modern UI option) needs about 2 px more at the same size.
        /// </summary>
        private int MinRowHeightForFont()
        {
            double size = _grid.FontSize > 0 ? _grid.FontSize : 12;
            double spacing = _grid.FontFamily?.LineSpacing ?? 1.2;
            return (int)Math.Ceiling(size * spacing) + 2; // + grid line and a little room for descenders
        }

        public int DefaultRowHeight
        {
            get => _grid != null && !double.IsNaN(_grid.RowHeight) ? (int)_grid.RowHeight : 24;
            set { if (_grid != null) _grid.RowHeight = Modern.Enabled ? Math.Max(value, MinRowHeightForFont()) : value; }
        }

        /// <summary>Grid.MouseToCell: cell under a point (pixels relative to the grid); -1 when outside.</summary>
        public void MouseToCell(int x, int y, out int col, out int row)
        {
            col = -1; row = -1;
            if (_grid == null) return;
            var hit = _grid.InputHitTest(new Point(x, y)) as DependencyObject;
            while (hit != null && !(hit is DataGridCell)) hit = VisualTreeHelper.GetParent(hit);
            if (hit is DataGridCell cell)
            {
                col = cell.Column?.DisplayIndex ?? -1;
                var rowEl = DataGridRow.GetRowContainingElement(cell);
                row = rowEl?.GetIndex() ?? -1;
            }
        }
        /// <summary>
        /// Current row. A VCL grid always has a current cell (Row starts at FixedRows), while a WPF DataGrid
        /// can have no selection - then the first non-fixed row is reported, as in Delphi.
        /// Works in both selection modes: whole rows (goRowSelect) and single cells.
        /// </summary>
        public int Row
        {
            get
            {
                int r = CurrentRowIndex();
                if (r >= 0) return r;
                return RowCount <= 0 ? 0 : Math.Min(Math.Max(FixedRows, 0), RowCount - 1);
            }
            set => Select(value, Col);
        }

        /// <summary>Current column (cell selection mode follows the DataGrid's current cell).</summary>
        public int Col
        {
            get
            {
                if (_grid?.CurrentCell.Column != null) return _grid.CurrentCell.Column.DisplayIndex;
                return _col;
            }
            set { _col = value; Select(CurrentRowIndex() >= 0 ? CurrentRowIndex() : Row, value); }
        }
        private int _col;

        private int CurrentRowIndex()
        {
            if (_grid == null) return -1;
            object item = _grid.SelectionUnit == DataGridSelectionUnit.FullRow ? _grid.SelectedItem
                : _grid.CurrentCell.Item ?? (_grid.SelectedCells.Count > 0 ? _grid.SelectedCells[0].Item : null);
            return item == null ? -1 : _grid.Items.IndexOf(item);
        }

        /// <summary>
        /// Makes (row, col) the current cell. In row mode the row is selected; in cell mode the cell is
        /// selected (setting SelectedIndex there throws "SelectionUnit ... prevents rows from being selected").
        /// </summary>
        private void Select(int row, int col)
        {
            if (_grid == null) return;
            if (row < 0 || row >= _grid.Items.Count) { if (_grid.SelectionUnit == DataGridSelectionUnit.FullRow) _grid.SelectedIndex = -1; else _grid.SelectedCells.Clear(); return; }
            var item = _grid.Items[row];
            var column = _grid.Columns.Count == 0 ? null : _grid.Columns.FirstOrDefault(c => c.DisplayIndex == Math.Max(0, Math.Min(col, _grid.Columns.Count - 1)));
            if (_grid.SelectionUnit == DataGridSelectionUnit.FullRow)
            {
                _grid.SelectedIndex = row;
            }
            else
            {
                _grid.SelectedCells.Clear();
                if (column != null) _grid.SelectedCells.Add(new DataGridCellInfo(item, column));
            }
            if (column != null) _grid.CurrentCell = new DataGridCellInfo(item, column);
        }

        private void Refresh()
        {
            if (_grid == null) return;
            if (OwnerDraw != null) { RebuildColumns(); return; }
            int row = CurrentRowIndex(), col = Col;
            Rtl.WithoutEvents(_grid, () =>
            {
                _grid.ItemsSource = null;
                _grid.ItemsSource = _table.DefaultView;
                if (row >= 0) Select(row, col); // columns rebuilt, keep the current cell
            });
        }
    }

    /// <summary>
    /// One cell of an owner-drawn grid (OnDrawCell). OnRender calls the Delphi handler with a TCanvas
    /// that records into this cell, then draws the recording.
    /// </summary>
    public sealed class DrawGridCell : FrameworkElement
    {
        public static readonly DependencyProperty ColumnProperty =
            DependencyProperty.Register(nameof(Column), typeof(int), typeof(DrawGridCell), new FrameworkPropertyMetadata(0, FrameworkPropertyMetadataOptions.AffectsRender));
        public int Column { get => (int)GetValue(ColumnProperty); set => SetValue(ColumnProperty, value); }

        protected override Size MeasureOverride(Size availableSize) => new Size(0, 0);

        protected override void OnRender(DrawingContext dc)
        {
            var row = DataGridRow.GetRowContainingElement(this);
            var grid = row == null ? null : ItemsControl.ItemsControlFromItemContainer(row) as DataGrid;
            if (grid == null) return;
            var model = TStringGridModel.For(grid);
            if (model.OwnerDraw == null) return;
            int r = row.GetIndex(), c = Column;
            int w = (int)Math.Ceiling(ActualWidth), h = (int)Math.Ceiling(ActualHeight);
            if (w <= 0 || h <= 0) return;
            var state = new HashSet<TGridDrawStateItem>();
            if (r < model.FixedRows || c < model.FixedCols) state.Add(TGridDrawStateItem.gdFixed);
            if (r == model.Row && c == model.Col) { state.Add(TGridDrawStateItem.gdSelected); if (grid.IsKeyboardFocusWithin) state.Add(TGridDrawStateItem.gdFocused); }
            var canvas = new TCanvas();
            try { Rtl.PaintWith(grid, canvas, () => model.OwnerDraw(c, r, new TRect(0, 0, w, h), state)); }
            catch (Exception ex) { SmokeTest.LogException($"OnDrawCell ({c},{r})", ex); }
            dc.PushClip(new RectangleGeometry(new Rect(0, 0, w, h)));
            dc.DrawDrawing(canvas.Drawing);
            dc.Pop();
        }
    }

