    // ===================================================================== TThread

    /// <summary>Classes.TThread replacement. Override Execute; use Synchronize for UI access.</summary>
    public abstract class TThread
    {
        private readonly Thread _thread;
        private volatile bool _terminated;
        private bool _started;

        protected TThread(bool createSuspended)
        {
            _thread = new Thread(Run) { IsBackground = true };
            if (!createSuspended) Start();
        }

        public bool FreeOnTerminate { get; set; }
        public bool Terminated => _terminated;
        public int ReturnValue { get; set; }
        public Action<object> OnTerminate { get; set; }

        protected abstract void Execute();

        private void Run()
        {
            try { Execute(); }
            catch (Exception ex) { System.Diagnostics.Debug.WriteLine(ex); }
            if (OnTerminate != null)
                System.Windows.Application.Current?.Dispatcher.Invoke(() => OnTerminate(this));
        }

        public void Start() { if (!_started) { _started = true; _thread.Start(); } }
        public void Resume() => Start();
        public void Terminate() => _terminated = true;
        public int WaitFor() { _thread.Join(); return ReturnValue; }
        public void Free() { Terminate(); }

        /// <summary>Runs a method on the UI thread (TThread.Synchronize).</summary>
        protected void Synchronize(Action method)
        {
            var d = System.Windows.Application.Current?.Dispatcher;
            if (d == null || d.CheckAccess()) method(); else d.Invoke(method);
        }

        protected void Queue(Action method) => System.Windows.Application.Current?.Dispatcher.BeginInvoke(method);
    }

    // ===================================================================== TSplitter

    /// <summary>
    /// ExtCtrls.TSplitter: a thin thumb placed in a DockPanel next to the element it
    /// resizes (the previous sibling docked to the same side), exactly like the VCL.
    /// </summary>
    public sealed class TSplitterThumb : Thumb
    {
        public TSplitterThumb()
        {
            SetResourceReference(BackgroundProperty, SystemColors.ControlBrushKey);
            DragDelta += OnDragDelta;
            Loaded += (s, e) =>
            {
                var dock = DockPanel.GetDock(this);
                Cursor = dock == Dock.Left || dock == Dock.Right ? Cursors.SizeWE : Cursors.SizeNS;
            };
            Template = CreateTemplate();
        }

        private static ControlTemplate CreateTemplate()
        {
            var t = new ControlTemplate(typeof(TSplitterThumb));
            var border = new FrameworkElementFactory(typeof(Border));
            border.SetBinding(Border.BackgroundProperty, new System.Windows.Data.Binding("Background") { RelativeSource = System.Windows.Data.RelativeSource.TemplatedParent });
            t.VisualTree = border;
            return t;
        }

        /// <summary>Minimum size of the resized control (TSplitter.MinSize).</summary>
        public double MinSize { get; set; } = 30;

        private void OnDragDelta(object sender, DragDeltaEventArgs e)
        {
            if (!(Parent is DockPanel panel)) return;
            var dock = DockPanel.GetDock(this);
            int idx = panel.Children.IndexOf(this);
            FrameworkElement target = null;
            for (int i = idx - 1; i >= 0; i--)
            {
                if (panel.Children[i] is FrameworkElement fe && DockPanel.GetDock(fe) == dock && fe.Visibility == Visibility.Visible) { target = fe; break; }
            }
            if (target == null) return;
            switch (dock)
            {
                case Dock.Left: target.Width = Math.Max(MinSize, target.ActualWidth + e.HorizontalChange); break;
                case Dock.Right: target.Width = Math.Max(MinSize, target.ActualWidth - e.HorizontalChange); break;
                case Dock.Top: target.Height = Math.Max(MinSize, target.ActualHeight + e.VerticalChange); break;
                case Dock.Bottom: target.Height = Math.Max(MinSize, target.ActualHeight - e.VerticalChange); break;
            }
        }
    }

    // ===================================================================== misc helpers

    public static partial class Rtl
    {
        /// <summary>TVarRec.VType codes for "array of const" parameters.</summary>
        public const int vtInteger = 0, vtBoolean = 1, vtChar = 2, vtExtended = 3, vtString = 4, vtPointer = 5, vtPChar = 6,
            vtObject = 7, vtClass = 8, vtWideChar = 9, vtPWideChar = 10, vtAnsiString = 11, vtCurrency = 12, vtVariant = 13,
            vtInterface = 14, vtWideString = 15, vtInt64 = 16;

        /// <summary>Equivalent of TVarRec.VType for an element of an "array of const" (params object[]).</summary>
        public static int VType(object v)
        {
            switch (v)
            {
                case int _: case short _: case byte _: case sbyte _: case ushort _: return vtInteger;
                case long _: case uint _: case ulong _: return vtInt64;
                case bool _: return vtBoolean;
                case char _: return vtChar;
                case double _: case float _: return vtExtended;
                case decimal _: return vtCurrency;
                case string _: return vtAnsiString;
                case null: return vtPointer;
                case Type _: return vtClass;
                default: return vtObject;
            }
        }

        /// <summary>S[Index] := C for immutable .NET strings (1-based index, like Delphi).</summary>
        public static string SetChar(string s, int index, char c)
        {
            s ??= "";
            if (index < 1 || index > s.Length) throw new IndexOutOfRangeException($"String index {index} out of range");
            var a = s.ToCharArray();
            a[index - 1] = c;
            return new string(a);
        }
    }

    /// <summary>Image1.Picture / BitBtn1.Glyph access (LoadFromFile, SaveToFile, Assign).</summary>
    public sealed class PictureProxy
    {
        private readonly object _control;
        public PictureProxy(object control) { _control = control; }

        public void LoadFromFile(string fileName) => Rtl.LoadPicture(_control, fileName);

        public void SaveToFile(string fileName)
        {
            if (_control is Image img && img.Source is BitmapSource bmp)
            {
                BitmapEncoder enc = Path.GetExtension(fileName).ToLowerInvariant() == ".png" ? new PngBitmapEncoder()
                                  : Path.GetExtension(fileName).ToLowerInvariant() == ".jpg" ? new JpegBitmapEncoder() : (BitmapEncoder)new BmpBitmapEncoder();
                enc.Frames.Add(BitmapFrame.Create(bmp));
                using (var fs = File.Create(fileName)) enc.Save(fs);
            }
        }

        public void Assign(object other)
        {
            if (_control is Image img)
            {
                if (other is PictureProxy p && p._control is Image src) img.Source = src.Source;
                else if (other == null) img.Source = null;
            }
        }

        public int Width => _control is Image img && img.Source != null ? (int)img.Source.Width : 0;
        public int Height => _control is Image img && img.Source != null ? (int)img.Source.Height : 0;
        public object Graphic => (_control as Image)?.Source;

        /// <summary>Picture.Bitmap: a TBitmap view; assigning to it (Bitmap.Assign / LoadFromFile) updates the control.</summary>
        public TBitmap Bitmap
        {
            get
            {
                var b = new TBitmap { Source = (_control as Image)?.Source as BitmapSource };
                b.Changed += () => { if (_control is Image img) img.Source = b.Source; };
                return b;
            }
            set { if (_control is Image img) img.Source = value?.Source; }
        }
    }

