    {
        [System.Runtime.InteropServices.DllImport("user32.dll")] private static extern bool GetCursorPos(out TPoint p);
        [System.Runtime.InteropServices.DllImport("user32.dll")] private static extern bool SetCursorPos(int x, int y);
