    /// <summary>
    /// Registry.TRegIniFile / TRegistry replacement: INI-style access to HKEY_CURRENT_USER\&lt;key&gt;
    /// (sections are sub-keys, idents are values) using Microsoft.Win32.Registry.
    /// </summary>
    public class TRegIniFile
    {
        public string FileName { get; }
        public TRegIniFile(string key) { FileName = key ?? ""; }
        public static TRegIniFile Create(string key) => new TRegIniFile(key);

        private Microsoft.Win32.RegistryKey Open(string section, bool write)
        {
            string path = string.IsNullOrEmpty(section) ? FileName : FileName.TrimEnd('\\') + "\\" + section;
            try { return write ? Microsoft.Win32.Registry.CurrentUser.CreateSubKey(path) : Microsoft.Win32.Registry.CurrentUser.OpenSubKey(path); }
            catch { return null; }
        }

        public string ReadString(string section, string ident, string def)
        {
            using (var k = Open(section, false)) return k?.GetValue(ident) is object v ? Convert.ToString(v, CultureInfo.InvariantCulture) : def;
        }
        public int ReadInteger(string section, string ident, int def)
        {
            using (var k = Open(section, false))
            {
                var v = k?.GetValue(ident);
                if (v is int i) return i;
                return v != null && int.TryParse(Convert.ToString(v, CultureInfo.InvariantCulture), out var n) ? n : def;
            }
        }
        public bool ReadBool(string section, string ident, bool def) => ReadInteger(section, ident, def ? 1 : 0) != 0;
        public void WriteString(string section, string ident, string value) { using (var k = Open(section, true)) k?.SetValue(ident, value ?? ""); }
        public void WriteInteger(string section, string ident, int value) { using (var k = Open(section, true)) k?.SetValue(ident, value, Microsoft.Win32.RegistryValueKind.DWord); }
        public void WriteBool(string section, string ident, bool value) => WriteInteger(section, ident, value ? 1 : 0);
        public void DeleteKey(string section, string ident) { using (var k = Open(section, true)) k?.DeleteValue(ident, false); }
        public void EraseSection(string section) { try { Microsoft.Win32.Registry.CurrentUser.DeleteSubKeyTree(FileName.TrimEnd('\\') + "\\" + section, false); } catch { } }
        public bool SectionExists(string section) { using (var k = Open(section, false)) return k != null; }
        public bool ValueExists(string section, string ident) { using (var k = Open(section, false)) return k?.GetValue(ident) != null; }
        public void ReadSection(string section, TStrings strings) { using (var k = Open(section, false)) if (k != null) foreach (var n in k.GetValueNames()) strings.Add(n); }
        public void ReadSections(TStrings strings) { using (var k = Open("", false)) if (k != null) foreach (var n in k.GetSubKeyNames()) strings.Add(n); }
        public void Free() { }
        public void UpdateFile() { }
