        private static readonly ConditionalWeakTable<object, Dictionary<string, Action<object>>> _runtimeEvents = new ConditionalWeakTable<object, Dictionary<string, Action<object>>>();

        /// <summary>
        /// Run-time assignment of a notify event (Edit1.OnClick := Handler; nil removes it). The
        /// handler is attached once per control/event through the matching WPF event.
        /// </summary>
        public static void SetEvent(object control, string eventName, Action<object> handler)
        {
            if (control == null) return;
            var table = _runtimeEvents.GetValue(control, _ => new Dictionary<string, Action<object>>(StringComparer.OrdinalIgnoreCase));
            bool attached = table.ContainsKey(eventName);
            table[eventName] = handler;
            if (attached) return;
            void Fire() { if (table.TryGetValue(eventName, out var h) && h != null) Guard(() => h(control)); }
            switch (eventName.ToLowerInvariant())
            {
                case "onclick":
                    if (control is ButtonBase bb) bb.Click += (s, e) => Fire();
                    else if (control is MenuItem mi) mi.Click += (s, e) => Fire();
                    // Controls such as TextBox handle the mouse themselves (e.Handled) - listen to handled events too.
                    else if (control is UIElement u) u.AddHandler(UIElement.MouseLeftButtonUpEvent, new MouseButtonEventHandler((s, e) => Fire()), true);
                    break;
                case "ondblclick":
                    if (control is Control c2) c2.MouseDoubleClick += (s, e) => Fire();
                    else if (control is UIElement u2) u2.MouseLeftButtonDown += (s, e) => { if (e.ClickCount == 2) Fire(); };
                    break;
                case "onchange":
                    if (control is TextBox tb) tb.TextChanged += (s, e) => Fire();
                    else if (control is ToggleButton t) { t.Checked += (s, e) => Fire(); t.Unchecked += (s, e) => Fire(); }
                    else if (control is Selector sel) sel.SelectionChanged += (s, e) => { if (e.OriginalSource == sel) Fire(); };
                    else if (control is RangeBase rb) rb.ValueChanged += (s, e) => Fire();
                    break;
                case "onselect":
                    if (control is Selector sel2) sel2.SelectionChanged += (s, e) => { if (e.OriginalSource == sel2) Fire(); };
                    break;
                case "ondropdown":
                    if (control is ComboBox cb) cb.DropDownOpened += (s, e) => Fire();
                    break;
                case "oncloseup":
                    if (control is ComboBox cb2) cb2.DropDownClosed += (s, e) => Fire();
                    break;
                case "onenter":
                    if (control is UIElement u3) u3.GotKeyboardFocus += (s, e) => { if (e.NewFocus == control) Fire(); };
                    break;
                case "onexit":
                    if (control is UIElement u4) u4.LostKeyboardFocus += (s, e) => { if (e.OldFocus == control) Fire(); };
                    break;
                case "onshow":
                case "onhide":
                    if (control is UIElement u5) u5.IsVisibleChanged += (s, e) => { if ((bool)e.NewValue == (eventName.Equals("OnShow", StringComparison.OrdinalIgnoreCase))) Fire(); };
                    break;
                case "onresize":
                    if (control is FrameworkElement fe) fe.SizeChanged += (s, e) => Fire();
                    break;
            }
        }

