        /// <summary>StrLen / StrPCopy for PChar code converted to strings.</summary>
        public static int StrLen(string s) { if (s == null) return 0; int i = s.IndexOf('\0'); return i < 0 ? s.Length : i; }
        public static string StrPCopy(string dest, string source) => source ?? "";
        public static char[] StrPCopy(char[] dest, string source)
        {
            if (dest == null) return null;
            source ??= "";
            int n = Math.Min(source.Length, dest.Length - 1);
            source.CopyTo(0, dest, 0, Math.Max(0, n));
            if (n >= 0 && n < dest.Length) dest[n] = '\0';
            return dest;
        }
        /// <summary>StrPas: string from a zero-terminated char buffer.</summary>
        public static string StrPas(char[] buffer) { if (buffer == null) return ""; int i = Array.IndexOf(buffer, '\0'); return i < 0 ? new string(buffer) : new string(buffer, 0, i); }


        /// <summary>Form.Components / ComponentCount: the named elements and non-visual component fields of a form.</summary>
        public static List<object> Components(object owner)
        {
            var list = new List<object>();
            if (owner == null) return list;
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly;
            for (var t = owner.GetType(); t != null && t.Namespace != null && !t.Namespace.StartsWith("System", StringComparison.Ordinal); t = t.BaseType)
                foreach (var f in t.GetFields(flags))
                {
                    var v = f.GetValue(owner);
                    if (v != null && !(v is string) && !v.GetType().IsValueType && !f.Name.StartsWith("<", StringComparison.Ordinal) && !list.Contains(v)) list.Add(v);
                }
            return list;
        }

        /// <summary>Control.Controls / ControlCount: direct child controls (logical children).</summary>
        public static List<FrameworkElement> Controls(object parent)
        {
            var list = new List<FrameworkElement>();
            if (parent is DependencyObject d)
                foreach (var c in LogicalTreeHelper.GetChildren(d))
                {
                    if (c is FrameworkElement fe && (fe is Panel || fe is Decorator) && string.IsNullOrEmpty(fe.Name))
                        list.AddRange(Controls(fe));   // layout containers generated by the converter
                    else if (c is FrameworkElement f2) list.Add(f2);
                }
            return list;
        }

