        /// <summary>Control.Canvas: a canvas whose drawing is shown on top of the control.</summary>
        public static TCanvas CanvasOf(object control)
        {
            // While an owner-drawn cell is painted (OnDrawCell), Grid.Canvas is the canvas of that cell.
            if (control != null && _paintCanvases.TryGetValue(control, out var paint)) return paint;
            return TCanvas.ForControl(control as FrameworkElement);
        }

        private static readonly Dictionary<object, TCanvas> _paintCanvases = new Dictionary<object, TCanvas>();

        /// <summary>Runs <paramref name="paint"/> with Control.Canvas redirected to <paramref name="canvas"/>.</summary>
        internal static void PaintWith(object control, TCanvas canvas, Action paint)
        {
            _paintCanvases.TryGetValue(control, out var previous);
            _paintCanvases[control] = canvas;
            try { paint(); }
            finally { if (previous != null) _paintCanvases[control] = previous; else _paintCanvases.Remove(control); }
        }

        /// <summary>
        /// TDrawGrid / TStringGrid OnDrawCell: every cell of the grid is drawn by the Delphi handler.
        /// Rect is the cell rectangle (cell coordinates, 0,0 = top-left of the cell) and Canvas
        /// (Grid.Canvas inside the handler) draws into that cell.
        /// </summary>
        public static void OwnerDrawGrid(object grid, Action<int, int, TRect, HashSet<TGridDrawStateItem>> drawCell)
        {
            if (!(grid is DataGrid g)) return;
            var model = TStringGridModel.For(g);
            model.OwnerDraw = drawCell;
            g.GridLinesVisibility = DataGridGridLinesVisibility.None;
            g.HeadersVisibility = DataGridHeadersVisibility.None;
            g.SelectionUnit = DataGridSelectionUnit.Cell;
            g.SelectionMode = DataGridSelectionMode.Single;
            g.IsReadOnly = true;
            g.CanUserResizeColumns = false;
            g.CanUserResizeRows = false;
            g.CanUserReorderColumns = false;
            g.CanUserSortColumns = false;
            // The handler paints the whole cell: no selection colour or padding from the DataGrid theme.
            var cellStyle = new Style(typeof(DataGridCell));
            cellStyle.Setters.Add(new Setter(Control.BorderThicknessProperty, new Thickness(0)));
            cellStyle.Setters.Add(new Setter(Control.PaddingProperty, new Thickness(0)));
            cellStyle.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty, HorizontalAlignment.Stretch));
            cellStyle.Setters.Add(new Setter(Control.VerticalContentAlignmentProperty, VerticalAlignment.Stretch));
            cellStyle.Setters.Add(new Setter(Control.BackgroundProperty, Brushes.Transparent));
            cellStyle.Setters.Add(new Setter(Control.FocusVisualStyleProperty, null));
            var selected = new Trigger { Property = DataGridCell.IsSelectedProperty, Value = true };
            selected.Setters.Add(new Setter(Control.BackgroundProperty, Brushes.Transparent));
            selected.Setters.Add(new Setter(Control.BorderThicknessProperty, new Thickness(0)));
            cellStyle.Triggers.Add(selected);
            g.CellStyle = cellStyle;
            model.RebuildColumns();
            g.SelectedCellsChanged += (s, e) => InvalidateCells(g);
        }

        /// <summary>Repaints every owner-drawn cell of a grid (Grid.Invalidate / Repaint).</summary>
        internal static void InvalidateCells(DataGrid g)
        {
            foreach (var cell in Descendants<DrawGridCell>(g)) cell.InvalidateVisual();
        }

        internal static IEnumerable<T> Descendants<T>(DependencyObject root) where T : DependencyObject
        {
            if (root == null) yield break;
            int n = VisualTreeHelper.GetChildrenCount(root);
            for (int i = 0; i < n; i++)
            {
                var child = VisualTreeHelper.GetChild(root, i);
                if (child is T t) yield return t;
                foreach (var d in Descendants<T>(child)) yield return d;
            }
        }

        /// <summary>
        /// TPageControl.OnChanging(Sender, var AllowChange): runs before a tab clicked by the user becomes active
        /// (ActivePage is still the old page); AllowChange := False keeps the old page.
        /// </summary>
        public static void HookPageChanging(object tabs, Func<bool> changing)
        {
            if (!(tabs is TabControl tc)) return;
            tc.PreviewMouseLeftButtonDown += (s, e) =>
            {
                var d = e.OriginalSource as DependencyObject;
                while (d != null && !(d is TabItem)) d = VisualTreeHelper.GetParent(d) ?? LogicalTreeHelper.GetParent(d);
                if (d is TabItem ti && ti != tc.SelectedItem && tc.Items.Contains(ti) && !EventsSuppressed(tc))
                    if (!Guard(changing, true)) e.Handled = true;
            };
        }

        /// <summary>
        /// TStringGrid.OnSetEditText(Sender, ACol, ARow, Value): called when the user has edited a cell
        /// (in WPF when the edit is committed - Enter, Tab or leaving the cell).
        /// </summary>
        public static void HookSetEditText(object grid, Action<int, int, string> setEditText)
        {
            if (!(grid is DataGrid g)) return;
            g.CellEditEnding += (s, e) =>
            {
                if (e.EditAction != DataGridEditAction.Commit || !(e.EditingElement is TextBox tb)) return;
                int col = e.Column?.DisplayIndex ?? -1, row = e.Row?.GetIndex() ?? -1;
                if (col >= 0 && row >= 0) Guard(() => setEditText(col, row, tb.Text));
            };
        }

        /// <summary>
        /// Grid.OnSelectCell(Sender, ACol, ARow, var CanSelect): called when the current cell changes.
        /// When the handler sets CanSelect := False the previous cell is selected again.
        /// </summary>
        public static void HookSelectCell(object grid, Func<int, int, bool> selectCell)
        {
            if (!(grid is DataGrid g)) return;
            var model = TStringGridModel.For(g);
            int lastRow = -1, lastCol = -1;
            g.CurrentCellChanged += (s, e) =>
            {
                if (EventsSuppressed(g) || g.CurrentCell.Column == null || g.CurrentCell.Item == null) return;
                int col = g.CurrentCell.Column.DisplayIndex, row = g.Items.IndexOf(g.CurrentCell.Item);
                if (col == lastCol && row == lastRow) return;
                bool ok = Guard(() => selectCell(col, row), true);
                if (ok) { lastCol = col; lastRow = row; }
                else if (lastRow >= 0) WithoutEvents(g, () => { model.Row = lastRow; model.Col = lastCol; });
            };
        }

