        /// <summary>
        /// TComponent.FindComponent: finds a named element of a form/frame (x:Name) or a field
        /// of that name (non-visual components). Returns null when nothing matches.
        /// </summary>
        public static object FindComponent(object owner, string name)
        {
            if (owner == null || string.IsNullOrEmpty(name)) return null;
            if (owner is FrameworkElement fe)
            {
                try { var found = fe.FindName(name); if (found != null) return found; } catch { }
            }
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public |
                                                         System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.IgnoreCase;
            for (var t = owner.GetType(); t != null; t = t.BaseType)
            {
                var f = t.GetField(name, flags);
                if (f != null) return f.GetValue(owner);
            }
            if (owner is DependencyObject d) return FindByNameInTree(d, name);
            return null;
        }

        private static object FindByNameInTree(DependencyObject root, string name)
        {
            foreach (var child in LogicalTreeHelper.GetChildren(root))
            {
                if (child is FrameworkElement c && string.Equals(c.Name, name, StringComparison.OrdinalIgnoreCase)) return c;
                if (child is DependencyObject dc) { var r = FindByNameInTree(dc, name); if (r != null) return r; }
            }
            return null;
        }

        private static readonly ConditionalWeakTable<object, StrongBox<bool>> _down = new ConditionalWeakTable<object, StrongBox<bool>>();
        private static readonly ConditionalWeakTable<object, StrongBox<int>> _helpContext = new ConditionalWeakTable<object, StrongBox<int>>();

        /// <summary>TSpeedButton/TToolButton.Down (ToggleButton.IsChecked, otherwise remembered per control).</summary>
        public static bool GetDown(object c)
        {
            if (c is ToggleButton tb) return tb.IsChecked == true;
            return c != null && _down.TryGetValue(c, out var v) && v.Value;
        }

        public static void SetDown(object c, bool value)
        {
            if (c is ToggleButton tb) { tb.IsChecked = value; return; }
            if (c == null) return;
            _down.GetValue(c, _ => new StrongBox<bool>()).Value = value;
            if (c is Control ctl) ShowDown(ctl, value);
            // Grouped check buttons: pressing one releases the others of its group (VCL TToolButton.Grouped).
            if (value && _checkButtons.TryGetValue(c, out var opt) && opt.Grouped && c is FrameworkElement fe)
                foreach (var other in GroupOf(fe))
                    if (other != c && GetDown(other)) { _down.GetValue(other, _ => new StrongBox<bool>()).Value = false; if (other is Control oc) ShowDown(oc, false); }
        }

        /// <summary>Pressed look of a check tool button / speed button (VCL "Down").</summary>
        private static void ShowDown(Control ctl, bool down)
        {
            if (down && Modern.Enabled)
            {
                // Theme colours, so a "down" button reads correctly in light and dark mode.
                ctl.SetResourceReference(Control.BackgroundProperty, SystemColors.ControlLightLightBrushKey);
                ctl.SetResourceReference(Control.BorderBrushProperty, SystemColors.HighlightBrushKey);
                ctl.BorderThickness = new Thickness(1);
            }
            else if (down)
            {
                ctl.Background = new SolidColorBrush(Color.FromRgb(0xCC, 0xE4, 0xF7));
                ctl.BorderBrush = new SolidColorBrush(Color.FromRgb(0x3C, 0x7F, 0xB1));
                ctl.BorderThickness = new Thickness(1);
            }
            else
            {
                ctl.ClearValue(Control.BackgroundProperty);
                ctl.ClearValue(Control.BorderBrushProperty);
                ctl.ClearValue(Control.BorderThicknessProperty);
            }
        }

        private sealed class CheckButtonOptions { public bool Grouped; public bool AllowAllUp; }
        private static readonly ConditionalWeakTable<object, CheckButtonOptions> _checkButtons = new ConditionalWeakTable<object, CheckButtonOptions>();

        /// <summary>
        /// TToolButton with Style = tbsCheck (or a TSpeedButton with GroupIndex): a click toggles Down before
        /// OnClick runs. Grouped buttons next to each other (up to a separator) behave like radio buttons;
        /// with AllowAllUp = False the pressed button of a group cannot be released by clicking it again.
        /// </summary>
        public static void CheckToolButton(object button, bool grouped, bool allowAllUp)
        {
            if (!(button is ButtonBase b)) return;
            _checkButtons.AddOrUpdate(b, new CheckButtonOptions { Grouped = grouped, AllowAllUp = allowAllUp });
            // PreviewMouseLeftButtonUp runs before Click, so OnClick sees the new Down state (as in Delphi).
            b.PreviewMouseLeftButtonUp += (s, e) => { if (b.IsEnabled && b.IsMouseOver && b.IsPressed) Toggle(b); };
            b.PreviewKeyDown += (s, e) => { if (e.Key == Key.Space || e.Key == Key.Enter) Toggle(b); };
        }

        private static void Toggle(ButtonBase b)
        {
            if (!_checkButtons.TryGetValue(b, out var opt)) return;
            bool down = !GetDown(b);
            if (!down && opt.Grouped && !opt.AllowAllUp) return;   // the group must keep one button down
            SetDown(b, down);
        }

        /// <summary>The grouped check buttons next to <paramref name="fe"/> in its tool bar (separators end a group).</summary>
        private static IEnumerable<object> GroupOf(FrameworkElement fe)
        {
            IList items = (fe.Parent as ItemsControl)?.Items ?? (IList)(fe.Parent as Panel)?.Children;
            if (items == null) yield break;
            var list = items.Cast<object>().ToList();
            int i = list.IndexOf(fe);
            if (i < 0) yield break;
            bool InGroup(object o) => o != null && _checkButtons.TryGetValue(o, out var op) && op.Grouped;
            int start = i, end = i;
            while (start > 0 && InGroup(list[start - 1])) start--;
            while (end < list.Count - 1 && InGroup(list[end + 1])) end++;
            for (int k = start; k <= end; k++) yield return list[k];
        }

        /// <summary>HelpContext of a control (kept for reference; WinHelp is not available in WPF).</summary>
        public static int GetHelpContext(object c) => c != null && _helpContext.TryGetValue(c, out var v) ? v.Value : 0;
        public static void SetHelpContext(object c, int value) { if (c != null) _helpContext.GetValue(c, _ => new StrongBox<int>()).Value = value; }

        /// <summary>TCheckListBox.Checked[Index] / State[Index].</summary>
        public static CheckListAccessor CheckList(object c) => new CheckListAccessor(c as ItemsControl);

