        private static class NativeMethods
        {
            [System.Runtime.InteropServices.DllImport("user32.dll")] public static extern bool MessageBeep(uint uType);
            [System.Runtime.InteropServices.DllImport("user32.dll")] public static extern IntPtr GetFocus();
            [System.Runtime.InteropServices.DllImport("user32.dll")] public static extern bool IsWindow(IntPtr hWnd);
            [System.Runtime.InteropServices.DllImport("user32.dll")] public static extern int GetSystemMetrics(int index);
            [System.Runtime.InteropServices.DllImport("user32.dll", CharSet = System.Runtime.InteropServices.CharSet.Auto)]
            public static extern IntPtr SendMessage(IntPtr hWnd, uint msg, IntPtr wParam, IntPtr lParam);
            [System.Runtime.InteropServices.DllImport("user32.dll", CharSet = System.Runtime.InteropServices.CharSet.Auto)]
            public static extern bool PostMessage(IntPtr hWnd, uint msg, IntPtr wParam, IntPtr lParam);
            [System.Runtime.InteropServices.DllImport("gdi32.dll")] public static extern int GetDeviceCaps(IntPtr hdc, int index);
        }

        public const int LOGPIXELSX = 88, LOGPIXELSY = 90, HORZRES = 8, VERTRES = 10, HORZSIZE = 4, VERTSIZE = 6,
                         PHYSICALWIDTH = 110, PHYSICALHEIGHT = 111, PHYSICALOFFSETX = 112, PHYSICALOFFSETY = 113;
        public const int SM_CXSCREEN = 0, SM_CYSCREEN = 1, SM_CXVSCROLL = 2, SM_CYHSCROLL = 3, SM_CYCAPTION = 4, SM_CXBORDER = 5, SM_CYBORDER = 6;
        public const uint MB_SIMPLEBEEP = 0xFFFFFFFF;

        /// <summary>Windows.MessageBeep (falls back to Console.Beep where user32 is not available).</summary>
        public static bool MessageBeep(uint uType)
        {
            try { return NativeMethods.MessageBeep(uType); }
            catch { try { Console.Beep(); } catch { } return true; }
        }
        public static bool MessageBeep(int uType) => MessageBeep(unchecked((uint)uType));

        public static IntPtr GetFocus() { try { return NativeMethods.GetFocus(); } catch { return IntPtr.Zero; } }
        public static bool IsWindow(IntPtr hWnd) { try { return NativeMethods.IsWindow(hWnd); } catch { return false; } }
        public static int GetSystemMetrics(int index) { try { return NativeMethods.GetSystemMetrics(index); } catch { return 0; } }

        /// <summary>
        /// Windows.SendMessage. Note that WPF controls have no window handle of their own, so
        /// messages sent to converted controls (EM_xxx, WM_xxx) do nothing - see the TODO at the call.
        /// </summary>
        public static int SendMessage(IntPtr hWnd, int msg, int wParam, int lParam)
        {
            if (hWnd == IntPtr.Zero) return 0;
            try { return (int)NativeMethods.SendMessage(hWnd, unchecked((uint)msg), new IntPtr(wParam), new IntPtr(lParam)); } catch { return 0; }
        }
        public static IntPtr SendMessage(IntPtr hWnd, uint msg, IntPtr wParam, IntPtr lParam)
        {
            if (hWnd == IntPtr.Zero) return IntPtr.Zero;
            try { return NativeMethods.SendMessage(hWnd, msg, wParam, lParam); } catch { return IntPtr.Zero; }
        }
        public static bool PostMessage(IntPtr hWnd, int msg, int wParam, int lParam)
        {
            if (hWnd == IntPtr.Zero) return false;
            try { return NativeMethods.PostMessage(hWnd, unchecked((uint)msg), new IntPtr(wParam), new IntPtr(lParam)); } catch { return false; }
        }

        /// <summary>
        /// Windows.GetDeviceCaps. For Printer.Handle / Printer.Canvas.Handle the emulated printer's
        /// values are returned (600 dpi, A4); for other handles the real GDI value (screen: 96 dpi).
        /// </summary>
        public static int GetDeviceCaps(IntPtr hdc, int index)
        {
            if (hdc == TPrinter.PrinterHandle) return TPrinter.Instance.DeviceCaps(index);
            if (hdc == IntPtr.Zero)
            {
                switch (index)
                {
                    case LOGPIXELSX: case LOGPIXELSY: return 96;
                    case HORZRES: return (int)SystemParameters.PrimaryScreenWidth;
                    case VERTRES: return (int)SystemParameters.PrimaryScreenHeight;
                    default: return 0;
                }
            }
            try { return NativeMethods.GetDeviceCaps(hdc, index); } catch { return 0; }
        }
    }

    /// <summary>TCheckListBox.Checked[i] for a converted list box (items are CheckBox elements or plain items).</summary>
    public sealed class CheckListAccessor
    {
        private readonly ItemsControl _list;
        private static readonly ConditionalWeakTable<object, Dictionary<int, bool>> _state = new ConditionalWeakTable<object, Dictionary<int, bool>>();
        public CheckListAccessor(ItemsControl list) { _list = list; }

        public bool this[int index]
        {
            get
            {
                if (_list == null || index < 0 || index >= _list.Items.Count) return false;
                if (_list.Items[index] is CheckBox cb) return cb.IsChecked == true;
                return _state.GetValue(_list, _ => new Dictionary<int, bool>()).TryGetValue(index, out var v) && v;
            }
            set
            {
                if (_list == null || index < 0 || index >= _list.Items.Count) return;
                if (_list.Items[index] is CheckBox cb) { cb.IsChecked = value; return; }
                if (_list.Items[index] is string text)
                {
                    // Turn the plain item into a check box so the state is visible.
                    _list.Items[index] = new CheckBox { Content = text, IsChecked = value };
                    return;
                }
                _state.GetValue(_list, _ => new Dictionary<int, bool>())[index] = value;
            }
        }
    }

    /// <summary>TBrush (Canvas.Brush or Control.Brush). For a control, Color sets the background.</summary>
    public sealed class TBrush
    {
        private readonly object _owner;
        private int _color = Rtl.clWhite;
        public TBrush() { }
        public TBrush(object owner) { _owner = owner; if (owner != null) _color = Rtl.GetColor(owner); }
        public int Color { get => _color; set { _color = value; if (_owner != null) Rtl.SetColor(_owner, value); } }
        public TBrushStyle Style { get; set; } = TBrushStyle.bsSolid;
        public void Assign(TBrush other) { if (other != null) { Color = other.Color; Style = other.Style; } }
        internal Brush ToMedia() => Style == TBrushStyle.bsClear ? null : Rtl.ToBrush(_color);
        public void Free() { }
    }

    /// <summary>TPen (Canvas.Pen).</summary>
    public sealed class TPen
    {
        public int Color { get; set; } = Rtl.clBlack;
        public int Width { get; set; } = 1;
        public TPenStyle Style { get; set; } = TPenStyle.psSolid;
        public int Mode { get; set; }
        public void Assign(TPen other) { if (other != null) { Color = other.Color; Width = other.Width; Style = other.Style; } }
        internal Pen ToMedia()
        {
            if (Style == TPenStyle.psClear) return null;
            var p = new Pen(Rtl.ToBrush(Color), Math.Max(1, Width));
            switch (Style)
            {
                case TPenStyle.psDash: p.DashStyle = DashStyles.Dash; break;
                case TPenStyle.psDot: p.DashStyle = DashStyles.Dot; break;
                case TPenStyle.psDashDot: p.DashStyle = DashStyles.DashDot; break;
                case TPenStyle.psDashDotDot: p.DashStyle = DashStyles.DashDotDot; break;
            }
            p.Freeze();
            return p;
        }
        public void Free() { }
    }

    /// <summary>
    /// TCanvas: records drawing into <see cref="Drawing"/>. Units are canvas pixels at
    /// <see cref="PixelsPerInch"/> (96 for screen canvases, 600 for the printer).
    /// </summary>
    public sealed class TCanvas
    {
        private static readonly ConditionalWeakTable<FrameworkElement, TCanvas> _controlCanvases = new ConditionalWeakTable<FrameworkElement, TCanvas>();
        private Point _pos;

        public TCanvas() : this(96) { }
        public TCanvas(int pixelsPerInch) { PixelsPerInch = pixelsPerInch; _font = new TFont(); }

        /// <summary>Recorded drawing in canvas pixels.</summary>
        public DrawingGroup Drawing { get; private set; } = new DrawingGroup();
        public int PixelsPerInch { get; }
        private TFont _font;
        /// <summary>Canvas.Font: assigning a font copies its values (as Delphi does).</summary>
        public TFont Font { get => _font; set { if (_font == null) _font = new TFont(); _font.Assign(value); } }
        public TPen Pen { get; } = new TPen();
        public TBrush Brush { get; } = new TBrush();
        /// <summary>Device context handle: the printer canvas returns Printer.Handle so GetDeviceCaps works.</summary>
        public IntPtr Handle { get; internal set; } = IntPtr.Zero;
        public int CopyMode { get; set; }
        public TPoint PenPos { get => new TPoint((int)_pos.X, (int)_pos.Y); set => _pos = new Point(value.X, value.Y); }
        /// <summary>Raised after every drawing call (the control overlay re-renders).</summary>
        public event EventHandler Changed;
        public Action<object> OnChange { get; set; }

        /// <summary>The canvas of a control: its drawing is shown in an overlay on top of the control.</summary>
        internal static TCanvas ForControl(FrameworkElement fe)
        {
            if (fe == null) return new TCanvas();
            return _controlCanvases.GetValue(fe, e =>
            {
                var c = new TCanvas();
                c.AttachOverlay(e);
                return c;
            });
        }

        private void AttachOverlay(FrameworkElement fe)
        {
            var image = new Image { Source = new DrawingImage(Drawing), Stretch = Stretch.None, IsHitTestVisible = false,
                                    HorizontalAlignment = HorizontalAlignment.Left, VerticalAlignment = VerticalAlignment.Top };
            Panel host = fe as Panel ?? (fe as Window)?.Content as Panel ?? (fe as UserControl)?.Content as Panel ?? (fe as Border)?.Child as Panel;
            if (host != null) { Panel.SetZIndex(image, int.MaxValue); host.Children.Add(image); }
            else if (fe is Border b && b.Child == null) b.Child = image;
            Changed += (s, e) => image.Source = new DrawingImage(Drawing);
        }

        private void Draw(Action<DrawingContext> paint)
        {
            using (var dc = Drawing.Append()) paint(dc);
            Changed?.Invoke(this, EventArgs.Empty);
            OnChange?.Invoke(this);
        }

        private double EmSize => Math.Max(1, (Font.Size > 0 ? Font.Size : 8) * PixelsPerInch / 72.0);

        private FormattedText Format(string text, Brush brush) =>
            new FormattedText(text ?? "", CultureInfo.CurrentCulture, FlowDirection.LeftToRight,
                new Typeface(new FontFamily(string.IsNullOrEmpty(Font.Name) ? "Segoe UI" : Font.Name),
                             Font.Style.Contains(TFontStyle.fsItalic) ? FontStyles.Italic : FontStyles.Normal,
                             Font.Style.Contains(TFontStyle.fsBold) ? FontWeights.Bold : FontWeights.Normal, FontStretches.Normal),
                EmSize, brush, 1.0);

        public void MoveTo(int x, int y) => _pos = new Point(x, y);

        public void LineTo(int x, int y)
        {
            var from = _pos; var to = new Point(x, y);
            var pen = Pen.ToMedia();
            if (pen != null) Draw(dc => dc.DrawLine(pen, from, to));
            _pos = to;
        }

        public void TextOut(int x, int y, string text)
        {
            var ft = Format(text, Rtl.ToBrush(Font.Color));
            var back = Brush.Style == TBrushStyle.bsClear ? null : Brush.ToMedia();
            Draw(dc =>
            {
                if (back != null) dc.DrawRectangle(back, null, new Rect(x, y, ft.WidthIncludingTrailingWhitespace, ft.Height));
                dc.DrawText(ft, new Point(x, y));
            });
            _pos = new Point(x + ft.WidthIncludingTrailingWhitespace, y);
        }

        public void TextRect(TRect r, int x, int y, string text)
        {
            var ft = Format(text, Rtl.ToBrush(Font.Color));
            var back = Brush.ToMedia();
            var rect = new Rect(r.Left, r.Top, Math.Max(0, r.Right - r.Left), Math.Max(0, r.Bottom - r.Top));
            Draw(dc =>
            {
                dc.PushClip(new RectangleGeometry(rect));
                if (back != null) dc.DrawRectangle(back, null, rect);
                dc.DrawText(ft, new Point(x, y));
                dc.Pop();
            });
        }

        public int TextWidth(string text) => (int)Math.Ceiling(Format(text, Brushes.Black).WidthIncludingTrailingWhitespace);
        public int TextHeight(string text) => (int)Math.Ceiling(Format(string.IsNullOrEmpty(text) ? "Wg" : text, Brushes.Black).Height);
        public TPoint TextExtent(string text) => new TPoint(TextWidth(text), TextHeight(text));

        public void Rectangle(int x1, int y1, int x2, int y2)
        {
            var b = Brush.ToMedia(); var p = Pen.ToMedia();
            Draw(dc => dc.DrawRectangle(b, p, new Rect(new Point(x1, y1), new Point(x2, y2))));
        }
        public void Rectangle(TRect r) => Rectangle(r.Left, r.Top, r.Right, r.Bottom);

        public void RoundRect(int x1, int y1, int x2, int y2, int rx, int ry)
        {
            var b = Brush.ToMedia(); var p = Pen.ToMedia();
            Draw(dc => dc.DrawRoundedRectangle(b, p, new Rect(new Point(x1, y1), new Point(x2, y2)), rx / 2.0, ry / 2.0));
        }

        public void FillRect(TRect r)
        {
            var b = Brush.ToMedia();
            if (b != null) Draw(dc => dc.DrawRectangle(b, null, new Rect(new Point(r.Left, r.Top), new Point(r.Right, r.Bottom))));
        }

        public void FrameRect(TRect r)
        {
            var p = new Pen(Rtl.ToBrush(Brush.Color), 1);
            Draw(dc => dc.DrawRectangle(null, p, new Rect(new Point(r.Left, r.Top), new Point(r.Right, r.Bottom))));
        }

        public void Ellipse(int x1, int y1, int x2, int y2)
        {
            var b = Brush.ToMedia(); var p = Pen.ToMedia();
            var rect = new Rect(new Point(x1, y1), new Point(x2, y2));
            Draw(dc => dc.DrawEllipse(b, p, new Point(rect.X + rect.Width / 2, rect.Y + rect.Height / 2), rect.Width / 2, rect.Height / 2));
        }
        public void Ellipse(TRect r) => Ellipse(r.Left, r.Top, r.Right, r.Bottom);

        public void Polyline(TPoint[] points) => PolyShape(points, false);
        public void Polygon(TPoint[] points) => PolyShape(points, true);

        private void PolyShape(TPoint[] points, bool closed)
        {
            if (points == null || points.Length < 2) return;
            var geo = new StreamGeometry();
            using (var ctx = geo.Open())
            {
                ctx.BeginFigure(new Point(points[0].X, points[0].Y), closed, closed);
                for (int i = 1; i < points.Length; i++) ctx.LineTo(new Point(points[i].X, points[i].Y), true, false);
            }
            geo.Freeze();
            var b = closed ? Brush.ToMedia() : null; var p = Pen.ToMedia();
            Draw(dc => dc.DrawGeometry(b, p, geo));
        }

        /// <summary>Canvas.Draw(X, Y, Bitmap) - TBitmap, ImageSource or PictureProxy.</summary>
        public void Draw(int x, int y, object graphic)
        {
            var src = TBitmap.SourceOf(graphic);
            if (src == null) return;
            double scale = PixelsPerInch / 96.0;
            Draw(dc => dc.DrawImage(src, new Rect(x, y, src.Width * scale, src.Height * scale)));
        }

        public void StretchDraw(TRect r, object graphic)
        {
            var src = TBitmap.SourceOf(graphic);
            if (src == null) return;
            Draw(dc => dc.DrawImage(src, new Rect(new Point(r.Left, r.Top), new Point(r.Right, r.Bottom))));
        }

        /// <summary>Removes everything drawn so far.</summary>
        public void Clear()
        {
            Drawing = new DrawingGroup();
            Changed?.Invoke(this, EventArgs.Empty);
        }

        public void Lock() { }
        public void Unlock() { }
        public void Refresh() { }
        public void Free() { }
    }

    /// <summary>TBitmap: an image (BitmapSource) plus a TCanvas to draw on.</summary>
    public sealed class TBitmap
    {
        private BitmapSource _source;
        private TCanvas _canvas;
        public TBitmap() { }
        public TBitmap(object owner) { }

        public int Width { get; set; }
        public int Height { get; set; }
        public bool Transparent { get; set; }
        public int TransparentColor { get; set; } = Rtl.clNone;
        public bool Empty => Source == null;

        public TCanvas Canvas => _canvas ??= new TCanvas(96);

        /// <summary>The image: the loaded bitmap, with anything drawn on <see cref="Canvas"/> rendered on top.</summary>
        public BitmapSource Source
        {
            get
            {
                if (_canvas == null || _canvas.Drawing.Children.Count == 0) return _source;
                int w = Math.Max(1, Width > 0 ? Width : (int)(_source?.PixelWidth ?? 1));
                int h = Math.Max(1, Height > 0 ? Height : (int)(_source?.PixelHeight ?? 1));
                var visual = new DrawingVisual();
                using (var dc = visual.RenderOpen())
                {
                    if (_source != null) dc.DrawImage(_source, new Rect(0, 0, _source.PixelWidth, _source.PixelHeight));
                    dc.DrawDrawing(_canvas.Drawing);
                }
                var rtb = new RenderTargetBitmap(w, h, 96, 96, PixelFormats.Pbgra32);
                rtb.Render(visual);
                rtb.Freeze();
                return rtb;
            }
            set
            {
                _source = value;
                if (value != null) { Width = value.PixelWidth; Height = value.PixelHeight; }
                Changed?.Invoke();
            }
        }

        /// <summary>Raised when the image is replaced (Picture.Bitmap writes it back to the control).</summary>
        public event Action Changed;

        public void LoadFromFile(string fileName)
        {
            var bmp = new BitmapImage();
            bmp.BeginInit();
            bmp.CacheOption = BitmapCacheOption.OnLoad;
            bmp.UriSource = new Uri(Path.GetFullPath(fileName));
            bmp.EndInit();
            bmp.Freeze();
            Source = bmp;
        }

        public void SaveToFile(string fileName)
        {
            var src = Source;
            if (src == null) return;
            var enc = new BmpBitmapEncoder();
            enc.Frames.Add(BitmapFrame.Create(src));
            using (var fs = File.Create(fileName)) enc.Save(fs);
        }

        /// <summary>Bitmap.LoadFromResourceName - resources are not converted; add the image to the project instead.</summary>
        public void LoadFromResourceName(IntPtr instance, string resourceName) { }

        public void Assign(object other)
        {
            if (other == null) { Source = null; _canvas = null; return; }
            Source = SourceOf(other) as BitmapSource;
        }

        public void Dormant() { }
        public void FreeImage() { }
        public void Free() { }

        /// <summary>Image source of a TBitmap, PictureProxy, Image control or ImageSource.</summary>
        public static ImageSource SourceOf(object graphic)
        {
            switch (graphic)
            {
                case null: return null;
                case TBitmap b: return b.Source;
                case ImageSource s: return s;
                case PictureProxy p: return p.Graphic as ImageSource;
                case Image img: return img.Source;
                default: return null;
            }
        }

        public static implicit operator ImageSource(TBitmap b) => b?.Source;
    }

    /// <summary>
    /// Printers.TPrinter emulation. Delphi code draws on Printer.Canvas between BeginDoc and
    /// EndDoc in printer pixels (600 dpi, A4 printable area); EndDoc shows the WPF print
    /// dialog and prints the recorded pages.
    /// </summary>
    public sealed class TPrinter
    {
        public static TPrinter Instance { get; } = new TPrinter();
        /// <summary>Fake device-context handle recognised by Rtl.GetDeviceCaps.</summary>
        public static readonly IntPtr PrinterHandle = new IntPtr(0x50524E54);

        private readonly List<TCanvas> _pages = new List<TCanvas>();
        private TCanvas _current;

        public const int Dpi = 600;
        /// <summary>A4 paper in inches and the unprintable margin.</summary>
        public double PaperWidthInches { get; set; } = 8.27;
        public double PaperHeightInches { get; set; } = 11.69;
        public double MarginInches { get; set; } = 0.25;

        public TPrinterOrientation Orientation { get; set; } = TPrinterOrientation.poPortrait;
        public string Title { get; set; } = "";
        public int Copies { get; set; } = 1;
        public bool Printing { get; private set; }
        public bool Aborted { get; private set; }
        public int PageNumber => _pages.Count;
        public IntPtr Handle => PrinterHandle;
        public int PrinterIndex { get; set; } = -1;
        public TStrings Printers { get; } = new TStringList { "Default printer" };
        public TStrings Fonts { get; } = new TStringList();

        private double PaperW => Orientation == TPrinterOrientation.poPortrait ? PaperWidthInches : PaperHeightInches;
        private double PaperH => Orientation == TPrinterOrientation.poPortrait ? PaperHeightInches : PaperWidthInches;

        /// <summary>Printable width / height in printer pixels (HORZRES / VERTRES).</summary>
        public int PageWidth => (int)((PaperW - 2 * MarginInches) * Dpi);
        public int PageHeight => (int)((PaperH - 2 * MarginInches) * Dpi);

        public TCanvas Canvas => _current ??= NewCanvas();

        private TCanvas NewCanvas() => new TCanvas(Dpi) { Handle = PrinterHandle };

        public void BeginDoc()
        {
            _pages.Clear();
            Aborted = false;
            Printing = true;
            _current = NewCanvas();
            _pages.Add(_current);
        }

        public void NewPage()
        {
            if (!Printing) BeginDoc();
            var font = _current?.Font;
            _current = NewCanvas();
            if (font != null) _current.Font.Assign(font);
            _pages.Add(_current);
        }

        public void Abort()
        {
            Aborted = true;
            Printing = false;
            _pages.Clear();
            _current = null;
        }

        /// <summary>Prints the recorded pages through the WPF print dialog.</summary>
        public void EndDoc()
        {
            Printing = false;
            if (Aborted || _pages.Count == 0) return;
            var dlg = new PrintDialog();
            if (dlg.ShowDialog() != true) { _pages.Clear(); _current = null; return; }
            double scale = 96.0 / Dpi;
            foreach (var page in _pages)
            {
                var visual = new DrawingVisual();
                using (var dc = visual.RenderOpen())
                {
                    dc.PushTransform(new TranslateTransform(MarginInches * 96, MarginInches * 96));
                    dc.PushTransform(new ScaleTransform(scale, scale));
                    dc.DrawDrawing(page.Drawing);
                    dc.Pop();
                    dc.Pop();
                }
                for (int i = 0; i < Math.Max(1, Copies); i++)
                    dlg.PrintVisual(visual, string.IsNullOrEmpty(Title) ? "Document" : Title);
            }
            _pages.Clear();
            _current = null;
        }

        internal int DeviceCaps(int index)
        {
            switch (index)
            {
                case Rtl.LOGPIXELSX: case Rtl.LOGPIXELSY: return Dpi;
                case Rtl.HORZRES: return PageWidth;
                case Rtl.VERTRES: return PageHeight;
                case Rtl.PHYSICALWIDTH: return (int)(PaperW * Dpi);
                case Rtl.PHYSICALHEIGHT: return (int)(PaperH * Dpi);
                case Rtl.PHYSICALOFFSETX: case Rtl.PHYSICALOFFSETY: return (int)(MarginInches * Dpi);
                case Rtl.HORZSIZE: return (int)((PaperW - 2 * MarginInches) * 25.4);
                case Rtl.VERTSIZE: return (int)((PaperH - 2 * MarginInches) * 25.4);
                default: return 0;
            }
        }
    }

    // ================================================================== modern UI (Windows 11)

    /// <summary>
    /// "Modern UI" conversion option: gives the converted program the Windows 11 look while keeping the
    /// original Delphi form layouts.
    /// <list type="bullet">
    /// <item>Turns on WPF's Fluent theme (Application.ThemeMode, .NET 9 and later) following the Windows
    /// light/dark setting, or forced Light/Dark. On older frameworks the call does nothing.</item>
    /// <item>Adds compact versions of the Fluent control styles: Fluent controls have a 32 px minimum height
    /// and wide padding, which would make the absolutely positioned Delphi controls overlap.</item>
    /// <item>Maps the Delphi system colours (clBtnFace, clWindow, clWindowText ...) to the theme colours, both in
    /// XAML (the generated forms use DynamicResource SystemColors.xxxBrushKey, overridden here at application
    /// level) and in code (Rtl.ToColorRef / ToBrush).</item>
    /// <item>Windows 11 title bars: dark title bar in dark mode, rounded corners and the Mica backdrop
    /// (Windows 11 22H2 and later; ignored on older Windows).</item>
    /// </list>
    /// The theme follows Windows when the user switches between light and dark mode.
    /// </summary>
    public static class Modern
    {
        /// <summary>True after <see cref="Apply"/>.</summary>
        public static bool Enabled { get; private set; }

        /// <summary>Requested theme: "System", "Light" or "Dark".</summary>
        public static string Theme { get; private set; } = "System";

        /// <summary>True when the dark palette is in use.</summary>
        public static bool IsDark { get; private set; }

        // Palette used for the Delphi system colours (index = COLOR_xxx, as in clBtnFace = $FF00000F).
        private static readonly Dictionary<int, Color> _palette = new Dictionary<int, Color>();
        private static bool _hooked;

        /// <summary>Call once at start-up, before the first window is created.</summary>
        public static void Apply(Application app, string theme = "System")
        {
            if (app == null) return;
            Theme = string.IsNullOrEmpty(theme) ? "System" : theme;
            Enabled = true;
            SetThemeMode(app, Theme);
            // A problem with the compact styles must not stop the program: it then keeps the plain Fluent look.
            try { AddCompactStyles(app); }
            catch (Exception ex) { Log("compact styles could not be applied: " + ex.Message); }
            Refresh(app);
            if (!_hooked)
            {
                _hooked = true;
                // Every window: Windows 11 title bar + follow theme changes (WM_SETTINGCHANGE "ImmersiveColorSet").
                EventManager.RegisterClassHandler(typeof(Window), FrameworkElement.LoadedEvent, new RoutedEventHandler((s, e) =>
                {
                    if (s is Window w && ReferenceEquals(e.OriginalSource, w)) { ThemeWindow(w); StyleTitleBar(w); }
                }));
                // Converted forms derive from Window, so the theme's implicit Window style does not reach them:
                // give them the theme text colour (labels inherit it) as soon as they are created.
                EventManager.RegisterClassHandler(typeof(Window), FrameworkElement.SizeChangedEvent, new SizeChangedEventHandler((s, e) =>
                {
                    if (s is Window w) ThemeWindow(w);
                }), true);
                // The Fluent styles give controls a 14 px font; the Delphi forms were designed for their own font
                // (usually 8 pt = 11 px). Every element whose font size comes from a theme style gets its parent's size.
                EventManager.RegisterClassHandler(typeof(FrameworkElement), FrameworkElement.LoadedEvent, new RoutedEventHandler((s, e) =>
                {
                    if (s is FrameworkElement fe && ReferenceEquals(e.OriginalSource, fe)) { KeepFormFontSize(fe); CompactTopLevelMenus(fe); }
                }), true);
            }
        }

        /// <summary>Application.ThemeMode = System/Light/Dark, set by reflection so this file also compiles for .NET 8.</summary>
        private static void SetThemeMode(Application app, string theme)
        {
            try
            {
                var prop = typeof(Application).GetProperty("ThemeMode");
                if (prop == null) { Log("Fluent theme needs .NET 9 or later - the project keeps the classic look."); return; }
                var value = prop.PropertyType.GetProperty(theme, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static)?.GetValue(null)
                            ?? prop.PropertyType.GetProperty("System")?.GetValue(null);
                if (value != null) prop.SetValue(app, value);
            }
            catch (Exception ex) { Log("Fluent theme could not be applied: " + ex.Message); }
        }

        private static void Log(string text) { try { SmokeTest.Log("Modern UI: " + text); } catch { } }

        /// <summary>
        /// Compact density: the Fluent styles, minus their minimum sizes and with smaller padding, so the
        /// controls fit the sizes they had on the Delphi form.
        /// </summary>
        private static void AddCompactStyles(Application app)
        {
            // Triggers to add to a type's style; they must be in place before the style goes into the resources
            // (a style is sealed - read-only - once it is used).
            var extraTriggers = new Dictionary<Type, List<TriggerBase>>();
            void AddTrigger(Type type, TriggerBase trigger)
            {
                if (!extraTriggers.TryGetValue(type, out var list)) extraTriggers[type] = list = new List<TriggerBase>();
                list.Add(trigger);
            }
            void Compact(Type type, Thickness? padding, params Setter[] extra)
            {
                var basedOn = app.TryFindResource(type) as Style;
                var st = basedOn != null ? new Style(type, basedOn) : new Style(type);
                st.Setters.Add(new Setter(FrameworkElement.MinHeightProperty, 0.0));
                st.Setters.Add(new Setter(FrameworkElement.MinWidthProperty, 0.0));
                if (padding.HasValue) st.Setters.Add(new Setter(Control.PaddingProperty, padding.Value));
                foreach (var x in extra) st.Setters.Add(x);
                if (extraTriggers.TryGetValue(type, out var triggers)) foreach (var tr in triggers) st.Triggers.Add(tr);
                app.Resources[type] = st;
            }
            // Compact Windows 11-style templates for the controls whose Fluent templates have fixed sizes that do not
            // fit the Delphi layouts (32 px text boxes and combo boxes, 20 px check marks, 40 px tab headers).
            var t = CompactTemplates();
            Setter Tpl(string key) => t != null && t.Contains(key) ? new Setter(Control.TemplateProperty, t[key]) : null;
            Setter[] With(params Setter[] setters) => setters.Where(x => x != null).ToArray();
            object Res(ResourceKey key) => new DynamicResourceExtension(key);
            var inputLook = new[]
            {
                new Setter(Control.BackgroundProperty, Res(SystemColors.WindowBrushKey)),
                new Setter(Control.ForegroundProperty, Res(SystemColors.WindowTextBrushKey)),
                new Setter(Control.BorderBrushProperty, Res(SystemColors.ControlDarkBrushKey)),
                new Setter(Control.BorderThicknessProperty, new Thickness(1)),
            };

            // Read-only edits look like normal edits in the VCL (Fluent greys their text).
            var readOnly = new Trigger { Property = TextBoxBase.IsReadOnlyProperty, Value = true };
            readOnly.Setters.Add(new Setter(Control.ForegroundProperty, Res(SystemColors.WindowTextBrushKey)));
            readOnly.Setters.Add(new Setter(Control.BackgroundProperty, Res(SystemColors.WindowBrushKey)));
            AddTrigger(typeof(TextBox), readOnly);
            // The Fluent style swaps in its own template for editable combo boxes with a style trigger, which would
            // override the template setter - repeat the compact template in a trigger of our own.
            if (Tpl("ComboBox") != null)
            {
                var editable = new Trigger { Property = ComboBox.IsEditableProperty, Value = true };
                editable.Setters.Add(Tpl("ComboBox"));
                AddTrigger(typeof(ComboBox), editable);
            }

            Compact(typeof(Button), new Thickness(6, 1, 6, 1));
            Compact(typeof(ToggleButton), new Thickness(4, 1, 4, 1));
            Compact(typeof(RepeatButton), new Thickness(1));
            Compact(typeof(TextBox), new Thickness(1, 0, 1, 0), With(inputLook.Concat(new[] { Tpl("TextBox"),
                new Setter(TextBoxBase.SelectionBrushProperty, Res(SystemColors.HighlightBrushKey)),
                new Setter(TextBoxBase.CaretBrushProperty, Res(SystemColors.WindowTextBrushKey)) }).ToArray()));
            Compact(typeof(PasswordBox), new Thickness(1, 0, 1, 0), With(inputLook.Concat(new[] { Tpl("PasswordBox") }).ToArray()));
            Compact(typeof(ComboBox), new Thickness(5, 0, 18, 0), With(inputLook.Concat(new[] { Tpl("ComboBox") }).ToArray()));
            Compact(typeof(ComboBoxItem), new Thickness(6, 2, 6, 2), With(Tpl("ComboBoxItem")));
            // List boxes and grids are opaque in the VCL (clWindow): Delphi code often stacks several of them and
            // shows one with BringToFront, which only works when the front one hides the others.
            Compact(typeof(ListBox), new Thickness(0), inputLook);
            Compact(typeof(ListBoxItem), new Thickness(4, 1, 4, 1), new Setter(Control.TemplateProperty, CompactListItemTemplate()));
            Compact(typeof(CheckBox), new Thickness(4, 0, 0, 0), With(Tpl("CheckBox"), new Setter(Control.VerticalContentAlignmentProperty, VerticalAlignment.Center)));
            Compact(typeof(RadioButton), new Thickness(3, 0, 0, 0), With(Tpl("RadioButton"), new Setter(Control.VerticalContentAlignmentProperty, VerticalAlignment.Center)));
            Compact(typeof(TabItem), new Thickness(8, 3, 8, 4), With(Tpl("TabItem")));
            Compact(typeof(Menu), new Thickness(0));
            Compact(typeof(MenuItem), null);
            Compact(typeof(DataGrid), null, With(inputLook.Concat(new[]
            {
                new Setter(DataGrid.RowBackgroundProperty, Res(SystemColors.WindowBrushKey)),
                new Setter(DataGrid.HorizontalGridLinesBrushProperty, Res(SystemColors.ControlLightBrushKey)),
                new Setter(DataGrid.VerticalGridLinesBrushProperty, Res(SystemColors.ControlLightBrushKey)),
            }).ToArray()));
            Compact(typeof(System.Windows.Controls.Primitives.DataGridColumnHeader), new Thickness(4, 1, 4, 1));
            Compact(typeof(DataGridRow), null);
            Compact(typeof(DataGridCell), new Thickness(2, 0, 2, 0), With(Tpl("DataGridCell"), new Setter(Control.BorderThicknessProperty, new Thickness(0))));
            Compact(typeof(ScrollBar), null);
            Compact(typeof(Slider), null);
            Compact(typeof(ProgressBar), null);
            Compact(typeof(GroupBox), null, With(Tpl("GroupBox")));
            // Buttons on a ToolBar use the ToolBar's own button styles (resource keys, not the implicit styles).
            void ToolBarStyle(ResourceKey key, Type type, string template)
            {
                var basedOn = app.TryFindResource(key) as Style;
                var st = basedOn != null && basedOn.TargetType.IsAssignableFrom(type) ? new Style(type, basedOn) : new Style(type);
                st.Setters.Add(new Setter(FrameworkElement.MinHeightProperty, 0.0));
                st.Setters.Add(new Setter(FrameworkElement.MinWidthProperty, 0.0));
                st.Setters.Add(new Setter(Control.BackgroundProperty, Brushes.Transparent));
                st.Setters.Add(new Setter(Control.BorderBrushProperty, Brushes.Transparent));
                st.Setters.Add(new Setter(Control.FocusVisualStyleProperty, null));
                var tpl = Tpl(template);
                if (tpl != null) st.Setters.Add(tpl);
                app.Resources[key] = st;
            }
            ToolBarStyle(ToolBar.ButtonStyleKey, typeof(Button), "ToolBarButton");
            ToolBarStyle(ToolBar.ToggleButtonStyleKey, typeof(ToggleButton), "ToolBarToggleButton");
            Compact(typeof(Label), new Thickness(0));
        }

        /// <summary>Top-level menu items: the Fluent ones are 40 px high; make them as high as a Windows 11 menu bar item.</summary>
        private static void CompactTopLevelMenus(DependencyObject root)
        {
            if (root is Menu menu)
                foreach (var item in menu.Items.OfType<MenuItem>())
                    if (FromStyle(item, Control.PaddingProperty) || item.ReadLocalValue(Control.PaddingProperty) == DependencyProperty.UnsetValue)
                        item.SetCurrentValue(Control.PaddingProperty, new Thickness(8, 3, 8, 3));
        }

        private const string TemplatesXaml = @"
