      <Trigger Property='IsMouseOver' Value='True'><Setter TargetName='Bd' Property='Background' Value='{DynamicResource {x:Static SystemColors.ControlLightBrushKey}}' /></Trigger>
      <Trigger Property='IsPressed' Value='True'><Setter TargetName='Bd' Property='Background' Value='{DynamicResource {x:Static SystemColors.ControlDarkBrushKey}}' /></Trigger>
      <Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='0.4' /></Trigger>
