  <ControlTemplate x:Key='ComboBoxItem' TargetType='ComboBoxItem'>
    <Border x:Name='Bd' CornerRadius='3' Padding='{TemplateBinding Padding}' Background='Transparent' SnapsToDevicePixels='True'>
      <ContentPresenter />
