    <ControlTemplate.Triggers>
      <Trigger Property='IsHighlighted' Value='True'><Setter TargetName='Bd' Property='Background' Value='{DynamicResource {x:Static SystemColors.ControlLightBrushKey}}' /></Trigger>
      <Trigger Property='IsSelected' Value='True'>
        <Setter TargetName='Bd' Property='Background' Value='{DynamicResource {x:Static SystemColors.HighlightBrushKey}}' />
        <Setter Property='Foreground' Value='{DynamicResource {x:Static SystemColors.HighlightTextBrushKey}}' />
      </Trigger>
    </ControlTemplate.Triggers>
  </ControlTemplate>
</ResourceDictionary>";

        /// <summary>The compact templates (null when they cannot be loaded - the Fluent ones are kept then).</summary>
        private static ResourceDictionary CompactTemplates()
        {
            try { return (ResourceDictionary)System.Windows.Markup.XamlReader.Parse(TemplatesXaml); }
            catch (Exception ex) { Log("compact templates could not be loaded: " + ex.Message); return null; }
        }

        /// <summary>
        /// List items as tall as their text (the Fluent item has a fixed 36 px look that turns a Delphi list box
        /// into a few visible rows): rounded accent-coloured selection, subtle hover.
        /// </summary>
        private static ControlTemplate CompactListItemTemplate()
        {
            var t = new ControlTemplate(typeof(ListBoxItem));
            var bd = new FrameworkElementFactory(typeof(Border), "Bd");
            bd.SetValue(Border.CornerRadiusProperty, new CornerRadius(3));
            bd.SetValue(Border.BackgroundProperty, Brushes.Transparent);
            bd.SetValue(Border.PaddingProperty, new TemplateBindingExtension(Control.PaddingProperty));
            bd.SetValue(UIElement.SnapsToDevicePixelsProperty, true);
            var cp = new FrameworkElementFactory(typeof(ContentPresenter));
            cp.SetValue(FrameworkElement.HorizontalAlignmentProperty, new TemplateBindingExtension(Control.HorizontalContentAlignmentProperty));
            cp.SetValue(FrameworkElement.VerticalAlignmentProperty, new TemplateBindingExtension(Control.VerticalContentAlignmentProperty));
            bd.AppendChild(cp);
            t.VisualTree = bd;
            var hover = new Trigger { Property = UIElement.IsMouseOverProperty, Value = true };
            hover.Setters.Add(new Setter(Border.BackgroundProperty, new DynamicResourceExtension(SystemColors.ControlLightBrushKey), "Bd"));
            t.Triggers.Add(hover);
            var sel = new Trigger { Property = ListBoxItem.IsSelectedProperty, Value = true };
            sel.Setters.Add(new Setter(Border.BackgroundProperty, new DynamicResourceExtension(SystemColors.HighlightBrushKey), "Bd"));
            sel.Setters.Add(new Setter(Control.ForegroundProperty, new DynamicResourceExtension(SystemColors.HighlightTextBrushKey)));
            t.Triggers.Add(sel);
            var dis = new Trigger { Property = UIElement.IsEnabledProperty, Value = false };
            dis.Setters.Add(new Setter(Control.ForegroundProperty, new DynamicResourceExtension(SystemColors.GrayTextBrushKey)));
            t.Triggers.Add(dis);
            return t;
        }

        /// <summary>Re-reads light/dark and refreshes the colours (called at start-up and when Windows changes theme).</summary>
        public static void Refresh(Application app = null)
        {
            app = app ?? Application.Current;
            if (app == null) return;
            IsDark = Theme.Equals("Dark", StringComparison.OrdinalIgnoreCase) ||
                     (Theme.Equals("System", StringComparison.OrdinalIgnoreCase) && WindowsUsesDarkMode());

            // Windows 11 design colours; the Fluent theme's own brushes are used when it provides them.
            Color bg = Pick(app, "ApplicationBackgroundColor", IsDark ? Color.FromRgb(0x20, 0x20, 0x20) : Color.FromRgb(0xF3, 0xF3, 0xF3));
            Color text = Pick(app, "TextFillColorPrimary", IsDark ? Color.FromRgb(0xFF, 0xFF, 0xFF) : Color.FromRgb(0x1B, 0x1B, 0x1B));
            Color text2 = Pick(app, "TextFillColorSecondary", IsDark ? Color.FromRgb(0xC5, 0xC5, 0xC5) : Color.FromRgb(0x5F, 0x5F, 0x5F));
            Color disabled = Pick(app, "TextFillColorDisabled", IsDark ? Color.FromRgb(0x78, 0x78, 0x78) : Color.FromRgb(0xA0, 0xA0, 0xA0));
            Color input = IsDark ? Color.FromRgb(0x2B, 0x2B, 0x2B) : Color.FromRgb(0xFF, 0xFF, 0xFF);
            Color card = IsDark ? Color.FromRgb(0x2D, 0x2D, 0x2D) : Color.FromRgb(0xFB, 0xFB, 0xFB);
            Color stroke = IsDark ? Color.FromRgb(0x3D, 0x3D, 0x3D) : Color.FromRgb(0xE0, 0xE0, 0xE0);
            Color strokeDark = IsDark ? Color.FromRgb(0x55, 0x55, 0x55) : Color.FromRgb(0xC8, 0xC8, 0xC8);
            Color accent = SystemColors.HighlightColor;
            try { accent = (Color)typeof(SystemColors).GetProperty("AccentColor")?.GetValue(null) ; } catch { }
            if (accent.A == 0) accent = SystemColors.HighlightColor;

            _palette.Clear();
            _palette[4] = card;       // clMenu
            _palette[5] = input;      // clWindow (edit boxes, lists, grids)
            _palette[6] = strokeDark; // clWindowFrame
            _palette[7] = text;       // clMenuText
            _palette[8] = text;       // clWindowText
            _palette[12] = bg;        // clAppWorkSpace
            _palette[13] = accent;    // clHighlight
            _palette[14] = Colors.White; // clHighlightText
            _palette[15] = bg;        // clBtnFace
            _palette[16] = strokeDark; // clBtnShadow
            _palette[17] = disabled;  // clGrayText
            _palette[18] = text;      // clBtnText
            _palette[19] = text2;     // clInactiveCaptionText
            _palette[20] = card;      // clBtnHighlight
            _palette[21] = strokeDark; // cl3DDkShadow
            _palette[22] = stroke;    // cl3DLight
            _palette[23] = text;      // clInfoText
            _palette[24] = card;      // clInfoBk

            // XAML: the generated forms use {DynamicResource {x:Static SystemColors.xxxBrushKey}} - override the keys.
            void Set(ResourceKey key, Color c) { var b = new SolidColorBrush(c); b.Freeze(); app.Resources[key] = b; }
            Set(SystemColors.ControlBrushKey, bg);
            Set(SystemColors.WindowBrushKey, input);
            Set(SystemColors.WindowTextBrushKey, text);
            Set(SystemColors.ControlTextBrushKey, text);
            Set(SystemColors.ControlLightBrushKey, stroke);
            Set(SystemColors.ControlLightLightBrushKey, card);
            Set(SystemColors.ControlDarkBrushKey, strokeDark);
            Set(SystemColors.ControlDarkDarkBrushKey, strokeDark);
            Set(SystemColors.GrayTextBrushKey, disabled);
            Set(SystemColors.MenuBrushKey, card);
            Set(SystemColors.MenuTextBrushKey, text);
            Set(SystemColors.InfoBrushKey, card);
            Set(SystemColors.InfoTextBrushKey, text);
            Set(SystemColors.AppWorkspaceBrushKey, bg);
            Set(SystemColors.HighlightBrushKey, accent);
            Set(SystemColors.HighlightTextBrushKey, Colors.White);

            foreach (Window w in app.Windows) StyleTitleBar(w);
            // A theme switch re-applies the Fluent styles (and their font size): restore the form fonts afterwards.
            app.Dispatcher.BeginInvoke(new Action(() => { foreach (Window w in app.Windows) KeepFormFontSizes(w); }), DispatcherPriority.Loaded);
        }

        private static Color Pick(Application app, string key, Color fallback)
        {
            try { if (app.TryFindResource(key) is Color c) return c; } catch { }
            return fallback;
        }

        /// <summary>Delphi system colour (index 0..30) in the modern palette.</summary>
        internal static bool TryMapSystemColor(int index, out Color c) => _palette.TryGetValue(index, out c);

        /// <summary>Windows "Choose your app mode" = Dark.</summary>
        public static bool WindowsUsesDarkMode()
        {
            try
            {
                using (var key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"))
                    return key?.GetValue("AppsUseLightTheme") is int v && v == 0;
            }
            catch { return false; }
        }

        // ---- title bar (DWM)

        [System.Runtime.InteropServices.DllImport("dwmapi.dll")]
        private static extern int DwmSetWindowAttribute(IntPtr hwnd, int attribute, ref int value, int size);

        private const int DWMWA_USE_IMMERSIVE_DARK_MODE = 20, DWMWA_WINDOW_CORNER_PREFERENCE = 33, DWMWA_SYSTEMBACKDROP_TYPE = 38;
        private const int DWMWCP_ROUND = 2, DWMSBT_MAINWINDOW = 2, DWMSBT_TRANSIENTWINDOW = 3;

        private static readonly HashSet<IntPtr> _hooks = new HashSet<IntPtr>();

        /// <summary>True when a property's value comes from a style (the theme's), not from the form or inheritance.</summary>
        private static bool FromStyle(DependencyObject d, DependencyProperty p)
        {
            var src = DependencyPropertyHelper.GetValueSource(d, p).BaseValueSource;
            return src == BaseValueSource.Style || src == BaseValueSource.ImplicitStyleReference || src == BaseValueSource.DefaultStyle
                || src == BaseValueSource.StyleTrigger || src == BaseValueSource.DefaultStyleTrigger;
        }

        /// <summary>
        /// Gives an element whose font size was set by a theme style the size it would inherit from its parent
        /// (the font of the Delphi form / panel). Elements inside control templates are left alone (arrow glyphs ...).
        /// </summary>
        private static void KeepFormFontSize(FrameworkElement fe)
        {
            if (!Enabled || fe == null || fe.TemplatedParent != null || fe is Window) return;
            if (!FromStyle(fe, System.Windows.Documents.TextElement.FontSizeProperty)) return;
            // The form font: the nearest ancestor whose size was set by the form itself (XAML / code), not by a
            // theme style and not merely inherited from a styled element.
            double size = 0;
            DependencyObject p = fe;
            for (int guard = 0; guard < 200; guard++)
            {
                p = (p is Visual || p is System.Windows.Media.Media3D.Visual3D ? VisualTreeHelper.GetParent(p) : null) ?? LogicalTreeHelper.GetParent(p);
                if (p == null) break;
                var vs = DependencyPropertyHelper.GetValueSource(p, System.Windows.Documents.TextElement.FontSizeProperty);
                if (vs.BaseValueSource == BaseValueSource.Local || vs.IsCurrent)
                {
                    size = (double)p.GetValue(System.Windows.Documents.TextElement.FontSizeProperty);
                    break;
                }
            }
            if (size > 0 && Math.Abs(size - (double)fe.GetValue(System.Windows.Documents.TextElement.FontSizeProperty)) > 0.1)
                fe.SetCurrentValue(System.Windows.Documents.TextElement.FontSizeProperty, size);
        }

        /// <summary>Re-applies <see cref="KeepFormFontSize"/> to a whole window (after a theme switch re-applied the styles).</summary>
        private static void KeepFormFontSizes(DependencyObject root)
        {
            if (root is FrameworkElement fe) KeepFormFontSize(fe);
            int n = VisualTreeHelper.GetChildrenCount(root);
            for (int i = 0; i < n; i++) KeepFormFontSizes(VisualTreeHelper.GetChild(root, i));
        }

        /// <summary>Theme text and background colours for a window whose own XAML does not set them.</summary>
        private static void ThemeWindow(Window w)
        {
            if (!Enabled || w == null) return;
            if (System.Windows.DependencyPropertyHelper.GetValueSource(w, Control.ForegroundProperty).BaseValueSource < BaseValueSource.Local)
                w.SetResourceReference(Control.ForegroundProperty, SystemColors.ControlTextBrushKey);
            if (System.Windows.DependencyPropertyHelper.GetValueSource(w, Control.BackgroundProperty).BaseValueSource < BaseValueSource.Local)
                w.SetResourceReference(Control.BackgroundProperty, SystemColors.ControlBrushKey);
        }

        /// <summary>Dark/light title bar, rounded corners and Mica (Windows 11; harmless elsewhere).</summary>
        public static void StyleTitleBar(Window w)
        {
            if (!Enabled || w == null) return;
            try
            {
                var hwnd = new System.Windows.Interop.WindowInteropHelper(w).Handle;
                if (hwnd == IntPtr.Zero) return;
                int dark = IsDark ? 1 : 0, corner = DWMWCP_ROUND;
                int backdrop = w.Owner != null || w.ShowInTaskbar == false ? DWMSBT_TRANSIENTWINDOW : DWMSBT_MAINWINDOW;
                DwmSetWindowAttribute(hwnd, DWMWA_USE_IMMERSIVE_DARK_MODE, ref dark, sizeof(int));
                DwmSetWindowAttribute(hwnd, DWMWA_WINDOW_CORNER_PREFERENCE, ref corner, sizeof(int));
                DwmSetWindowAttribute(hwnd, DWMWA_SYSTEMBACKDROP_TYPE, ref backdrop, sizeof(int));
                if (_hooks.Add(hwnd))
                {
                    var src = System.Windows.Interop.HwndSource.FromHwnd(hwnd);
                    src?.AddHook(WndProc);
                    w.Closed += (s, e) => _hooks.Remove(hwnd);
                }
            }
            catch (DllNotFoundException) { }
            catch (EntryPointNotFoundException) { }
        }

        private static bool _refreshQueued;

        private static IntPtr WndProc(IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled)
        {
            const int WM_SETTINGCHANGE = 0x001A, WM_SYSCOLORCHANGE = 0x0015, WM_DWMCOLORIZATIONCOLORCHANGED = 0x0320;
            if (msg == WM_SETTINGCHANGE || msg == WM_SYSCOLORCHANGE || msg == WM_DWMCOLORIZATIONCOLORCHANGED)
            {
                string area = null;
                try { if (msg == WM_SETTINGCHANGE && lParam != IntPtr.Zero) area = System.Runtime.InteropServices.Marshal.PtrToStringUni(lParam); } catch { }
                if ((msg != WM_SETTINGCHANGE || area == "ImmersiveColorSet") && !_refreshQueued && Application.Current != null)
                {
                    // Several windows receive the message: refresh once, after the Fluent theme has switched.
                    _refreshQueued = true;
                    Application.Current.Dispatcher.BeginInvoke(new Action(() => { _refreshQueued = false; Refresh(); }), DispatcherPriority.Background);
                }
            }
            return IntPtr.Zero;
        }
    }
}
